import type { ComponentType } from "react"

/** What a registry entry renders. Mirrors the `kind` segment of a `/view` URL. */
export type RegistryKind = "component" | "example" | "screen"

/** One file a registry item distributes. The shape `/r/<name>.json` serves. */
export interface RegistrySourceFile {
  path: string
  type: string
  target?: string
  /**
   * The file's own text. Mandatory in practice: shadcn's installer skips any
   * entry without one, silently, and still reports the install as a success.
   */
  content?: string
}

export interface RegistryEntry {
  /** The catalogue id, or an example name such as `range-bar-status`. */
  name: string
  /** Behaviour variant. `base` is the only one; the folder proves the axis exists. */
  base: string
  /** CSS-only variant. `base-lyra` is the default. */
  style: string
  kind: RegistryKind
  /**
   * Lazily loaded renderable. The type is `| null` because the field is part of
   * the shape a consumer checks, not because a generated entry ever carries one:
   * an entry exists only where a file does.
   */
  component: (() => Promise<{ default: ComponentType<Record<string, unknown>> }>) | null
  /** The real source text, for `<ComponentSource>`. */
  source: string | null
  /**
   * A pre-built registry-item.json payload. Always `null`: the item served at
   * `/r/<name>.json` is assembled from the catalogue row and `files` by
   * `app/_machine/registry-payload.ts`, so a second copy here would be a second
   * thing to keep in step.
   */
  meta: Record<string, unknown> | null
  /**
   * The files this item distributes, own file first and the shared substrate
   * after it. The machine routes read this directly to build a registry-item
   * response, so what is here is what `shadcn add` writes to disk.
   */
  files?: RegistrySourceFile[]
}

/** Behaviour variants. A second base is a folder under `registry/bases/`, never a URL migration. */
export const REGISTRY_BASES: string[] = ["base"]

/** Style variants. Style is a stylesheet and nothing else; see decision 6. */
export const REGISTRY_STYLES: string[] = ["base-lyra"]

const SOURCE_BASES_BASE_BUTTON = "/**\n * Button — the control you press to make something happen.\n *\n * THE LEAST CLINICAL COMPONENT, AND THE ONE WITH THE FEWEST PLACES TO HIDE. It\n * asserts nothing about a person, so every decision in this file is about the\n * two things a control owes everybody: a name you can read and a target you can\n * hit. Both are easier to get wrong here than anywhere else, because a button\n * is the component people copy first and read last.\n *\n * IT IS ALWAYS A REAL <button>. There is no `href`, no `as` and no `render`\n * escape hatch, and that is a refusal rather than an omission. A control that\n * produces a new URL is a link: it can be opened in a new tab, copied, and\n * found in a screen reader's list of links, and none of that survives being\n * reimplemented as a button with a click handler. The specification's anatomy\n * says \"a real <button>, or an <a> only when it navigates\" and this file\n * implements the first half; the second half belongs to `link`, which is on the\n * considered roster and is not this component wearing a different tag.\n *\n * WHY BASE UI RATHER THAN A BARE <button>. Exactly one prop needs it. `busy`\n * has to make the control unactivatable WITHOUT removing it from the\n * accessibility tree — the native `disabled` attribute does both at once, and\n * losing the control mid-save loses the reader's place. Base UI's `useButton`\n * gives that combination directly: with `disabled` and `focusableWhenDisabled`\n * together it sets `aria-disabled`, leaves the native attribute off, keeps the\n * element in the tab order, and swallows activation. Rebuilding that by hand\n * means merging the caller's own onClick and onKeyDown with ours, which is the\n * kind of code that works until somebody passes a handler we did not expect.\n *\n * THERE IS NO DESTRUCTIVE COLOUR IN THIS SYSTEM, AND THIS FILE DOES NOT INVENT\n * ONE. The product palette is the two axes plus eleven neutral roles; the\n * status axis is reserved for what a reading means, and\n * `handbook/migrating-from-shadcn` is explicit that a delete button is not a\n * clinical status and that mapping one onto the other is the fastest way to\n * contaminate the axis. So `destructive` is separated from `secondary` by\n * weight rather than by hue — the emphasis border width, and no fill — and the\n * signal a reader can actually rely on is the label and the confirmation step\n * around it. Colour is not carrying this, because in opsinjs there is no colour\n * available to carry it.\n *\n * WHAT IT DOES NOT DO. It does not derive anything, does not animate anything,\n * does not move focus, and does not mount a live region. `busy` is announced by\n * `aria-busy` on the control itself; whether a save is worth speaking aloud is\n * the product's call and not a decision a button is entitled to make.\n */\n\nimport { Button as BaseButton } from \"@base-ui/react/button\"\nimport { LoaderCircle } from \"lucide-react\"\nimport type { ButtonHTMLAttributes, ReactNode } from \"react\"\n\nimport { isDevelopment } from \"@/lib/opsinjs\"\nimport { cn } from \"@/lib/utils\"\n\n/**\n * Four variants, in descending emphasis.\n *\n * Deliberately few, and deliberately NOT exported: the substrate contract fixes\n * a registry file at three public exports — the props interface, the component\n * and the zero-prop demo — so a consumer names this union as\n * `ButtonProps[\"variant\"]` rather than importing a fourth symbol. The\n * specification writes it as an export; that difference is recorded on the page\n * rather than resolved in favour of a wider surface.\n */\ntype ButtonVariant = \"primary\" | \"secondary\" | \"quiet\" | \"destructive\"\n\n/**\n * Fill, ink and boundary per variant, written out as literal class strings.\n *\n * Tailwind reads class names out of source as text. `bg-${variant}` generates\n * no CSS whatsoever and the button renders unstyled, which is a defect that\n * reviews miss because the code reads as if it works. So the four are spelled\n * in full, once, here.\n *\n * Note what is NOT reached for. The secondary, accent and destructive roles a\n * shadcn button reaches for first are declared only in the docs chrome and\n * resolve to nothing under the product theme, so an emphasis ladder built from\n * them would look correct in review and arrive colourless in the product. The\n * four rungs below are built from the roles the product stylesheet actually\n * bridges: a strong fill, a soft fill, an outline, and nothing at all.\n *\n * Hover and press are approximations rather than derivations.\n * `foundations/interaction-states` specifies a state as a transformation in\n * OKLCH applied to the role the component already uses, but no state token is\n * generated yet, so there is nothing to consume. Until there is, the two filled\n * variants shift their own fill's alpha and the two unfilled ones take the\n * muted role, and `active:translate-y-px` gives every variant a press\n * acknowledgement that does not depend on colour at all.\n */\nconst TONE: Record<ButtonVariant, string> = {\n  primary:\n    \"border-transparent bg-primary text-primary-foreground hover:bg-primary/90 active:bg-primary/80\",\n  secondary:\n    \"border-border bg-card text-foreground hover:bg-muted active:bg-muted\",\n  quiet:\n    \"border-transparent bg-transparent text-foreground hover:bg-muted active:bg-muted\",\n  destructive:\n    \"border-border bg-transparent text-foreground hover:bg-muted active:bg-muted\",\n}\n\n/**\n * The boundary width per variant, as the token rather than as a number.\n *\n * It is an inline style and not a class on purpose. Tailwind can take a border\n * width from a custom property, but a spelling that fails to compile produces\n * no declaration and no error — and the failure mode here is a secondary button\n * that silently loses its only boundary, which is the one thing that keeps it\n * visible in greyscale and under a reader stylesheet that strips backgrounds. A\n * declared `borderStyle` travels with it because the width alone does nothing\n * without it in a project whose reset differs from this one.\n */\nconst EDGE: Record<ButtonVariant, string> = {\n  primary: \"var(--opsin-border-hairline, 1px)\",\n  secondary: \"var(--opsin-border-hairline, 1px)\",\n  quiet: \"var(--opsin-border-hairline, 1px)\",\n  /* The whole of the destructive signal that is not the label. */\n  destructive: \"var(--opsin-border-emphasis, 2px)\",\n}\n\n/**\n * Padding and type step per size.\n *\n * `md` takes the headline step, which is body size at weight 600 — the system\n * has no \"small and emphasised\" step, so `sm` takes subheadline and its weight\n * of 400 with it. That is a real limitation of the eleven-step ramp and not a\n * choice: a component that reached for `font-medium` here would be authoring a\n * weight the type scale does not own.\n *\n * Neither size sets a height. The height floor is the target minimum, applied\n * below, and it is the same for both — `sm` is narrower and quieter, never\n * shorter. `density-and-touch` is unambiguous that compact must not become\n * harder to hit.\n */\nconst SIZE: Record<\"sm\" | \"md\", string> = {\n  sm: \"gap-opsin-1 px-opsin-3 py-opsin-1 text-opsin-subheadline\",\n  md: \"gap-opsin-2 px-opsin-5 py-opsin-2 text-opsin-headline\",\n}\n\nexport interface ButtonProps\n  extends Omit<ButtonHTMLAttributes<HTMLButtonElement>, \"children\"> {\n  /**\n   * Emphasis. Four values, in descending order: `primary`, `secondary`,\n   * `quiet`, `destructive`. One primary per surface — the hierarchy is the\n   * answer to \"what should I do here?\", and three primaries answer it with a\n   * shrug. Defaults to `secondary`, because the safe default is the one that\n   * does not claim to be the most important thing on the screen.\n   */\n  variant?: ButtonVariant\n  /**\n   * Visual weight only. Both sizes clear the 44pt target floor; `sm` is\n   * narrower and takes a smaller type step, and is never shorter. Defaults to\n   * `md`.\n   */\n  size?: \"sm\" | \"md\"\n  /**\n   * Required. The label, and there is no way to remove it: no `iconOnly` prop\n   * and no size at which the icon stands alone. An icon-only control needs its\n   * accessible name supplied some other way and a different target treatment,\n   * which makes it a different component.\n   */\n  children: ReactNode\n  /**\n   * An optional glyph beside the label. Always decorative and always hidden\n   * from assistive technology — the label carries the meaning, and an announced\n   * icon makes a screen reader say the action twice.\n   */\n  icon?: ReactNode\n  /**\n   * Which side the icon sits on. Defaults to `leading`. Use `trailing` for a\n   * control that moves the reader forward through a flow, so the glyph points\n   * the way the action goes.\n   */\n  iconPosition?: \"leading\" | \"trailing\"\n  /**\n   * In-place loading. The label stays visible and unchanged, the button stays\n   * in the accessibility tree and in the tab order, and it is announced as busy\n   * and unavailable rather than disappearing. It replaces the icon slot, so a\n   * button that has no icon grows by one glyph when it becomes busy; give a\n   * button an icon if its width must not move.\n   */\n  busy?: boolean\n  /**\n   * Fills its container. For the bottom of a sheet or a form, where the primary\n   * action should be as wide as the thumb's reach. Not for a row of buttons —\n   * two full-width buttons stacked read as two primary actions.\n   */\n  fullWidth?: boolean\n}\n\nexport function Button({\n  variant = \"secondary\",\n  size = \"md\",\n  children,\n  icon,\n  iconPosition = \"leading\",\n  busy = false,\n  fullWidth = false,\n  className,\n  style,\n  ...rest\n}: ButtonProps) {\n  /* Development-only, and not an OPSIN code. The codes in tokens/errors.json\n     describe mistakes a consumer makes with the clinical API; \"this control\n     shipped with no accessible name\" is a mistake anybody can make with any\n     control and there is no code allocated for it. Reported here rather than\n     passed over, because an unlabelled button is the exact failure the missing\n     `iconOnly` prop exists to prevent, and TypeScript cannot see it: `children`\n     is required, and `\"\"` satisfies a required `ReactNode`. */\n  if (isDevelopment() && (children === \"\" || children === null || children === undefined)) {\n    console.warn(\n      \"[opsinjs] <Button> was rendered with no label. The visible label is the \" +\n        \"accessible name; without it the control is announced as \\\"button\\\" and \" +\n        \"nothing else, and it is unreachable by voice control. There is no \" +\n        \"icon-only Button — if the design calls for one, it needs its own name \" +\n        \"and its own target rules.\",\n    )\n  }\n\n  /* The caller's own `disabled` and our `busy` are different states and the\n     first wins. A caller who asked for a genuinely unavailable control gets\n     native disabled semantics; `busy` on its own gets `aria-disabled` with the\n     element left in the tree. Asking for both at once is a contradiction — the\n     native attribute takes the button out of the tab order, so the `aria-busy`\n     nobody can reach is announced to nobody. */\n  const nativeDisabled = rest.disabled === true\n  if (isDevelopment() && busy && nativeDisabled) {\n    console.warn(\n      \"[opsinjs] <Button> has both `busy` and `disabled`. `disabled` removes the \" +\n        \"control from the tab order and from the accessibility tree, so the busy \" +\n        \"state it is meant to announce reaches nobody. Use `busy` alone: it \" +\n        \"blocks activation and keeps the button reachable and announced.\",\n    )\n  }\n\n  /* The icon slot, rendered once and placed on whichever side was asked for.\n     Busy REPLACES the icon and never the label — the label is the reader's\n     record of what they pressed, and a control whose name disappears while it\n     works is a control that has lost their place. */\n  const slot = busy ? (\n    <span\n      data-slot=\"button-busy\"\n      aria-hidden=\"true\"\n      className=\"inline-flex shrink-0 items-center\"\n    >\n      {/* The spin is kept under `prefers-reduced-motion`. A frozen spinner\n          communicates nothing at all, and the alternative signals — the label\n          and `aria-busy` — are already present for everybody. This is a\n          deliberate exception to the reduce-motion default, not an oversight;\n          it is the one piece of motion in the component. */}\n      <LoaderCircle className=\"size-[1em] animate-spin\" />\n    </span>\n  ) : icon ? (\n    <span\n      data-slot=\"button-icon\"\n      aria-hidden=\"true\"\n      className=\"inline-flex shrink-0 items-center [&_svg]:size-[1em]\"\n    >\n      {icon}\n    </span>\n  ) : null\n\n  return (\n    <BaseButton\n      {...rest}\n      data-slot=\"button\"\n      /* `disabled` + `focusableWhenDisabled` is the whole mechanism behind\n         `busy`: Base UI sets `aria-disabled`, leaves the native attribute off,\n         keeps the tab stop and refuses activation. With a real `disabled` from\n         the caller, `focusableWhenDisabled` goes false and the native attribute\n         comes back, which is what that caller asked for. */\n      disabled={busy || nativeDisabled}\n      focusableWhenDisabled={busy && !nativeDisabled}\n      aria-busy={busy || undefined}\n      style={{ borderStyle: \"solid\", borderWidth: EDGE[variant], ...style }}\n      className={cn(\n        /* `relative` is load-bearing: the hit-area part below is positioned\n           against it. `whitespace-normal` and `items-center` rather than a\n           fixed height, because at 200% text the label has to wrap and the\n           button has to grow with it — a truncated label is unreadable and\n           unspeakable, and a fixed height is how it happens. */\n        \"relative inline-flex items-center justify-center whitespace-normal rounded-opsin-md text-center align-middle\",\n        \"transition-colors duration-(--opsin-duration-fast) ease-opsin-standard\",\n        /* The press acknowledgement, and the only state signal in this file that\n           does not depend on colour. `transition-colors` deliberately excludes\n           transform, so the shift is instantaneous rather than animated — which\n           is what `prefers-reduced-motion` asks a press feedback to be, so this\n           needs no reduced-motion branch and behaves identically for everybody. */\n        \"active:translate-y-px\",\n        /* Drawn outside the box with an offset, so it never changes layout and\n           never gets clipped. Declared here as well as in the product theme\n           because a consumer installs this file without that stylesheet. */\n        \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring\",\n        /* THE TWO UNAVAILABLE STATES LOOK DIFFERENT BECAUSE THEY ARE DIFFERENT,\n           and the selectors land on exactly one each. Base UI sets the native\n           attribute when `focusableWhenDisabled` is off and `aria-disabled`\n           when it is on, so `:disabled` is the caller's own disabled and\n           `[aria-disabled]` is `busy` — there is no state where both match.\n\n           Native disabled dims, but only to 60%: a control faded until nobody\n           can read it turns \"you cannot do this yet\" into \"you cannot find out\n           what this is\". Busy does NOT dim, because the label is the reader's\n           record of what they pressed and it has to stay at full contrast while\n           the work happens; the spinner is the signal, not a fade.\n\n           Both drop pointer events. That is what stops a hover fill promising\n           an activation neither state will honour. Neither touches the tab\n           order — busy keeps its stop by construction, and a natively disabled\n           control loses it to the platform rather than to this rule. */\n        \"disabled:opacity-60 disabled:pointer-events-none\",\n        \"aria-disabled:pointer-events-none\",\n        TONE[variant],\n        SIZE[size],\n        fullWidth ? \"w-full\" : null,\n        className,\n      )}\n    >\n      {/* Button.Target — the hit area, and the reason it is an element rather\n          than a rule on the root.\n\n          The product stylesheet floors every `button` at\n          `--opsin-target-minimum`, so inside this repository this span agrees\n          with the backstop rather than doing anything. Its job is the consumer\n          project that installed this file and not that stylesheet: centred on\n          the button and floored in both axes, it keeps a 44pt pressable region\n          even where the visible box is smaller, because pointer events on a\n          descendant activate the button.\n\n          The floor is a rem and not 44px on purpose. At 200% text the root font\n          size genuinely doubles, so a rem floor grows with the label while a\n          pixel one leaves a doubled label overflowing a fixed box. */}\n      <span\n        data-slot=\"button-target\"\n        aria-hidden=\"true\"\n        className=\"absolute top-1/2 left-1/2 size-full min-h-[var(--opsin-target-minimum,2.75rem)] min-w-[var(--opsin-target-minimum,2.75rem)] -translate-x-1/2 -translate-y-1/2\"\n      />\n      {iconPosition === \"leading\" ? slot : null}\n      <span data-slot=\"button-label\">{children}</span>\n      {iconPosition === \"trailing\" ? slot : null}\n    </BaseButton>\n  )\n}\n\n/**\n * The zero-prop default export (ADR 0009).\n *\n * `/view` renders this with no props and `shadcn add` ships it into a\n * consumer's project, so it is reviewed public code rather than a scratch\n * demo. It shows the four variants together because the only question worth\n * answering at a glance is whether the emphasis ladder reads as a ladder — and\n * that question is best asked in greyscale, where three of the four rungs have\n * to be told apart by fill and boundary alone.\n *\n * The labels name a fictional reading (ADR 0012). No number, no unit, nothing a\n * screenshot could be mistaken for.\n */\nexport default function ButtonDemo() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-opsin-2\">\n      <Button variant=\"primary\">Save example reading</Button>\n      <Button variant=\"secondary\">Add a note</Button>\n      <Button variant=\"quiet\">Cancel</Button>\n      <Button variant=\"destructive\">Delete this example reading</Button>\n      <Button variant=\"secondary\" size=\"sm\">\n        Edit\n      </Button>\n      <Button variant=\"primary\" busy>\n        Save example reading\n      </Button>\n    </div>\n  )\n}\n"

const SOURCE_BASES_BASE_CARD = "/**\n * Card — a boundary, some padding, and one rung of the material ladder.\n *\n * Card is the most-used component in any design system and the one that most\n * often becomes a dumping ground, so the interesting work here is what it\n * refuses. There is no `status`, no `variant` and no `color`: a Card that could\n * be tinted from the clinical axis would be a ResultCard with none of a\n * ResultCard's obligations — no staleness treatment, no attribution, no axis\n * discipline — and nothing in review catches the difference, because the two\n * render identically.\n *\n * THE DEFAULT RUNG IS `card`, AND THE SPECIFICATION SAID `raised`. That page was\n * written against the retired rung vocabulary, where `raised` was the name for\n * the rung a resting block of content sits on. On the ladder the tokens\n * actually publish, `raised` is one rung higher — `tokens/material.json` gives\n * it a drop shadow and describes it as \"menus, popovers, tooltips, a dragged\n * card\" — and the rung named `card` is \"the default home for a health value\",\n * opaque and deliberately shadowless. Taking the old word literally would have\n * put a shadow under every resting card in the system, which is the exact\n * clutter that rung's note exists to prevent. So the default is `card` and the\n * page has been corrected rather than implemented. See ADR 0014.\n *\n * \"Products may move a card down the ladder, never off it\" survives that\n * correction and means what it says: `canvas` for a card that should read as\n * part of the page, `raised` while a card is being lifted — dragged, or opened\n * as a menu — and never above `raised`, because a number a reader is trying to\n * read must not sit over a moving backdrop.\n *\n * IT IS ONE OF EXACTLY THREE COMPONENTS WITH REAL COMPOUND PARTS. `Card.Header`,\n * `Card.Body` and `Card.Footer` are exported functions rather than `data-slot`\n * names, because the consumer supplies their content and no prop could carry\n * three ordered slots of arbitrary children. Everything else in the anatomy —\n * the root, the title, the description — is a `data-slot`, which is enough to\n * style and not enough to take apart. All three parts are optional: a Card with\n * only children is the common case and takes no ceremony at all.\n *\n * IT IS A SERVER COMPONENT. It holds no state, listens for nothing, and every\n * decision it makes is made from props at render time. The one thing a reader\n * can change underneath it — the density of the interface — arrives as a CSS\n * custom property on the document, not as a value this component reads.\n */\n\nimport type { ReactNode } from \"react\"\n\nimport { isDevelopment, type MaterialRung } from \"@/lib/opsinjs\"\nimport { cn } from \"@/lib/utils\"\nimport { Surface } from \"@/registry/base-lyra/ui/surface\"\n\n/**\n * The three rungs that composite what is behind them.\n *\n * A second copy of a fact `tokens/material.json` owns and `Surface` also holds,\n * and it is here rather than imported because a registry file's import surface\n * is closed: `Surface` exports its component, its props and its demo, and a\n * private lookup is not one of the three. The cost of the duplication is a\n * warning that goes quiet if a rung changes phase; the cost of avoiding it\n * would be a fourth public export on Surface that exists only for this check.\n *\n * The list is used for one thing: telling somebody that a Card has been asked\n * to be a layer. `choosing-a-layer` puts it plainly — a translucent rung may\n * never contain another translucent rung, and a card inside a sheet stays\n * opaque — and `tokens/material.json` adds that a health value never goes above\n * `raised`. Both are rules a caller can break with one prop and never see.\n */\nconst TRANSLUCENT_RUNGS: MaterialRung[] = [\"sheet\", \"overlay\", \"scrim\"]\n\n/**\n * Padding, as literal class strings.\n *\n * Tailwind reads class names out of source as text, so this cannot be built\n * from the density at runtime: `p-${density === \"compact\" ? 4 : 5}` generates\n * no CSS and renders a card with no padding at all.\n *\n * WHY THESE TWO STEPS. `tokens/space.json` publishes step 5 as \"card inner\n * padding on a phone\" and step 4 as the step below it; the density scale it\n * declares for `compact` is 0.875, and 0.875 of 20px is 17.5px, which is not a\n * step on a 4px grid — the token source's first rule is that there is no 13px.\n * So `compact` moves one published step down rather than multiplying, and the\n * two values stay values somebody chose.\n *\n * They are the density-SCALED utilities (`p-5`, not `p-opsin-5`), which is the\n * one place this component follows `app/product.css` rather than the token\n * steps directly: that file names \"the inside of a card\" as the canonical use\n * of the scaled scale, so a reader who asks for a denser interface gets one\n * here. The two controls multiply — a product asking for `compact` inside a\n * document already set to a compact density gets the tightest card the system\n * offers, and that is the intended floor rather than an accident.\n */\nconst PADDING: Record<\"comfortable\" | \"compact\", string> = {\n  comfortable: \"p-5\",\n  compact: \"p-4\",\n}\n\n/**\n * The corner, and the enhancement that rides on it.\n *\n * `radius-md` is what `tokens/shape.json` publishes as the default for cards.\n * A card that is nearly the width of a phone screen takes `radius-lg` instead,\n * and that is a caller's decision through `className` rather than a prop —\n * it depends on the layout the card is in, which this component cannot see.\n *\n * `corner-shape` is applied as a property rather than through the product\n * theme's `data-opsin-shape=\"squircle\"` attribute, for two reasons. The\n * attribute is a fifth member of a data-attribute vocabulary that is closed at\n * four, and it lives in a stylesheet that does not travel with this file into a\n * consumer's project. An engine without `corner-shape` drops the declaration\n * and draws an ordinary rounded corner, which is the fallback `tokens/shape.json`\n * specifies and the reason every radius on the ladder is chosen to look correct\n * without it.\n */\nconst SHAPE = \"rounded-opsin-md [corner-shape:var(--opsin-corner-shape)]\"\n\n/**\n * The boundary, for print.\n *\n * The rung paints its fill with a background and its edge with an inset\n * box-shadow, and a browser drops both when it prints unless the reader has\n * gone looking for the setting that keeps them. Left alone, every card on a\n * printed page loses its boundary — and a printout is how a reading most often\n * reaches a clinician. A real border is the one boundary a printer keeps, so\n * the card grows one at print time and only at print time.\n */\nconst PRINT_BOUNDARY = \"print:border print:border-border\"\n\nexport interface CardProps {\n  /**\n   * Which rung of the material ladder. Defaults to `\"card\"` — the rung named\n   * for this component, opaque and deliberately shadowless. Products may move a\n   * card down the ladder to `\"canvas\"`, or up to `\"raised\"` while it is being\n   * lifted, and never above that: a value a reader is trying to read must not\n   * sit over a moving backdrop.\n   *\n   * @default \"card\"\n   */\n  rung?: MaterialRung\n  /**\n   * Padding scale. Affects space only, never type size. `\"compact\"` moves the\n   * padding one published step down the spacing scale; it does not shrink the\n   * type, the separation between two controls in the footer, or the card's\n   * touch target.\n   *\n   * @default \"comfortable\"\n   */\n  density?: \"comfortable\" | \"compact\"\n  /**\n   * Makes the whole card a single link. A card that is a link may hold no other\n   * interactive element: a reader cannot tell what tapping the gap between two\n   * buttons will do, and a keyboard user reaches controls that are nested\n   * inside a control. TypeScript cannot express that exclusion — `children` is\n   * a `ReactNode` and an element's interactivity is not in its type — so it is\n   * a rule this component states and does not enforce.\n   */\n  href?: string\n  /**\n   * Merged onto the root. Layout belongs here: a card sets no width, no\n   * position and no place in a grid, because those are decisions of the screen\n   * it is on rather than of the card.\n   */\n  className?: string\n  /**\n   * Everything the card holds — usually `Card.Header`, `Card.Body` and\n   * `Card.Footer`, and — equally correctly — a single paragraph.\n   */\n  children: ReactNode\n}\n\nexport function Card({\n  rung = \"card\",\n  density = \"comfortable\",\n  href,\n  className,\n  children,\n}: CardProps) {\n  /* Not an OPSIN code. `tokens/errors.json` has no entry for a card asked to be\n     a layer, and a component may not mint one — the codes are a versioned\n     contract and the table on the errors page is generated from that file. A\n     development warning is the honest channel until one exists.\n\n     It warns and renders. A rung that is legal for a Surface is legal here; the\n     mistake is a composition mistake rather than a broken value, and taking a\n     reader's content off the screen to report one would be the larger error.\n     A rung outside the six is not checked here at all: Surface already warns\n     about it, names the retired rung the caller probably meant, and renders the\n     children with no material, and a second warning would only make the first\n     harder to read. */\n  if (isDevelopment() && TRANSLUCENT_RUNGS.includes(rung)) {\n    console.warn(\n      `[opsinjs] <Card rung=\"${rung}\"> puts a card on a translucent rung. A card ` +\n        \"is a block of content on the page, not a layer over it: `sheet`, \" +\n        \"`overlay` and `scrim` composite what is behind them, and a card on one \" +\n        \"of them costs a blur, dissolves into whatever is scrolling underneath, \" +\n        \"and may not hold a health value at all. Use `card`, `canvas`, or \" +\n        \"`raised` while the card is being lifted. If you want the layer itself, \" +\n        \"the component is <Surface>. \" +\n        \"See /docs/foundations/materials/choosing-a-layer.\",\n    )\n  }\n\n  /* The material is a child rather than the root, which is what Surface's own\n     page asks for: a component that needs a different element wraps a Surface\n     instead of becoming one. It also has to be — the root carries\n     `data-slot=\"card\"` and a Surface root carries `data-slot=\"surface\"`, and\n     one element cannot carry both.\n\n     The padding goes on the Surface, not on the wrapper. Surface's three\n     decorative layers are absolutely positioned to `inset-0`, whose containing\n     block is the padding box, so the fill and the edge cover the padding rather\n     than being inset from it. Padding the wrapper instead would leave a card\n     with a boundary drawn inside its own whitespace. */\n  const material = (\n    <Surface\n      rung={rung}\n      className={cn(\"h-full rounded-[inherit]\", PADDING[density])}\n    >\n      {children}\n    </Surface>\n  )\n\n  if (href === undefined) {\n    return (\n      <div\n        data-slot=\"card\"\n        className={cn(SHAPE, PRINT_BOUNDARY, className)}\n      >\n        {material}\n      </div>\n    )\n  }\n\n  return (\n    /* One control, and everything that follows from that.\n       `min-h-(--opsin-target-minimum)` carries the 44px floor in the component\n       rather than relying on the product theme's `a[data-opsin-target]`\n       backstop: that attribute is outside the four-attribute vocabulary a\n       component may stamp, and the stylesheet declaring it does not travel with\n       this file into somebody else's project. The token is rem, so the floor\n       grows when a reader raises their text size instead of pinning at 44\n       device pixels.\n\n       The focus ring is declared here for the same reason. `app/product.css`\n       already gives every `:focus-visible` an outline, and a consumer's\n       stylesheet may not; a card whose focus ring depends on a file it was not\n       installed with is a card that loses it silently.\n\n       `group` is what lets the title underline on hover without knowing it is\n       inside a link. It is a CSS ancestor relationship, so `Card.Title` needs\n       no prop, no context and no client boundary to respond to it. */\n    <a\n      href={href}\n      data-slot=\"card\"\n      className={cn(\n        \"group block min-h-(--opsin-target-minimum) text-inherit no-underline\",\n        \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring\",\n        SHAPE,\n        PRINT_BOUNDARY,\n        className,\n      )}\n    >\n      {material}\n    </a>\n  )\n}\n\n/**\n * Vertical rhythm between the parts, as a class every part carries.\n *\n * `:not(:first-child)` rather than a gap on a flex parent, because the parent\n * is Surface's content layer and this component does not reach inside another\n * component to lay out its children. Step 4 is what `tokens/space.json`\n * publishes as \"the default gap between elements inside a card\", on the same\n * density-scaled scale as the padding, so the two move together.\n */\nconst PART_RHYTHM = \"[&:not(:first-child)]:mt-4\"\n\nexport interface CardHeaderProps {\n  /**\n   * The card's title. Pass the heading element the page's outline needs —\n   * `<h3>Recent readings</h3>` — and the slot takes care of how it looks. Pass\n   * a string instead and the title is styled text with no place in the outline,\n   * which is a legitimate choice for a card nobody needs to navigate to and a\n   * mistake for one they do.\n   */\n  title: ReactNode\n  /**\n   * One supporting line under the title. It renders a paragraph, so it takes\n   * text or inline content rather than a block element.\n   */\n  description?: ReactNode\n  /** Anything else the header holds, after the title and the description. */\n  children?: ReactNode\n  /** Merged onto the header. */\n  className?: string\n}\n\nexport function CardHeader({\n  title,\n  description,\n  children,\n  className,\n}: CardHeaderProps) {\n  return (\n    <div data-slot=\"card-header\" className={cn(PART_RHYTHM, className)}>\n      {/* THE HEADING LEVEL IS THE PAGE'S AND THE APPEARANCE IS THE CARD'S, and\n          the two lines below are what keeps them separate. A card that hard-codes\n          its own level produces an outline that jumps from h1 to h3, or a screen\n          of eleven h2s, depending on which mistake the library made; a card that\n          takes the level as a number is the same mistake with an extra prop. So\n          the caller passes the element.\n\n          The reset is what makes that safe. Left alone a browser gives an `h3`\n          its own size, weight and margins, so the same title would be a\n          different size in a card under an h2 and a card under an h4 — the\n          level would be carrying visual weight it is not entitled to. `font`\n          and `margin` are reset on the direct children only, which is exactly\n          the element the caller passed. */}\n      <div\n        data-slot=\"card-title\"\n        className=\"text-opsin-headline *:m-0 *:[font:inherit] group-hover:underline group-focus-visible:underline\"\n      >\n        {title}\n      </div>\n      {description === undefined ? null : (\n        <p\n          data-slot=\"card-description\"\n          className=\"mt-2 mb-0 text-opsin-footnote text-muted-foreground\"\n        >\n          {description}\n        </p>\n      )}\n      {children}\n    </div>\n  )\n}\n\nexport interface CardBodyProps {\n  /** The content. */\n  children: ReactNode\n  /** Merged onto the body. */\n  className?: string\n}\n\nexport function CardBody({ children, className }: CardBodyProps) {\n  return (\n    <div data-slot=\"card-body\" className={cn(PART_RHYTHM, className)}>\n      {children}\n    </div>\n  )\n}\n\nexport interface CardFooterProps {\n  /** Actions or metadata. */\n  children: ReactNode\n  /** Merged onto the footer. */\n  className?: string\n}\n\nexport function CardFooter({ children, className }: CardFooterProps) {\n  return (\n    <div\n      data-slot=\"card-footer\"\n      className={cn(\n        /* `gap-opsin-2` and not `gap-2`: this is the one measurement in the\n           card that must not move with density. `--opsin-target-separation` is\n           the minimum gap between two adjacent controls, and a footer with two\n           buttons in it is exactly the case it was measured for. Padding may\n           tighten when somebody asks for a denser interface; the distance\n           between two things a thumb has to hit may not. */\n        \"flex flex-wrap items-center gap-opsin-2\",\n        PART_RHYTHM,\n        className,\n      )}\n    >\n      {children}\n    </div>\n  )\n}\n\n/* The compound parts, assigned after their declarations rather than through\n   Object.assign, so each one keeps its own name in a stack trace and in React\n   devtools. `Card.Header` and `CardHeader` are the same function; the dotted\n   spelling is the one the anatomy uses and the one to write. */\nCard.Header = CardHeader\nCard.Body = CardBody\nCard.Footer = CardFooter\n\n/**\n * The zero-prop default export (ADR 0009).\n *\n * `/view` renders this with no props and `shadcn add` ships it, so it is public,\n * reviewed code rather than a scratch demo. It shows the two things worth\n * seeing: the full anatomy with the page supplying its own heading level, and\n * the same card at the other density beside it, so the prop's effect is visible\n * as a difference rather than described as a percentage.\n *\n * There is not a number anywhere in it, and there is no status pill and no\n * category tint (ADR 0012). A Card holding a value, a coloured pill and a\n * paragraph is a ResultCard drawn without any of a ResultCard's guarantees, and\n * a demo that showed one would teach the mistake this component's boundary\n * exists to prevent.\n */\nexport default function CardDemo() {\n  return (\n    <div className=\"grid w-full max-w-lg gap-opsin-6 sm:grid-cols-2\">\n      <Card>\n        <Card.Header\n          title={<h3>Example section</h3>}\n          description=\"One supporting line, which stays when the card is tight.\"\n        />\n        <Card.Body>\n          <p className=\"m-0 text-opsin-body\">\n            The body is whatever the card is for. It has no contract of its own,\n            which is the point: a card that knew what was inside it would be a\n            different component.\n          </p>\n        </Card.Body>\n        <Card.Footer>\n          <span className=\"text-opsin-footnote text-muted-foreground\">\n            Example metadata\n          </span>\n        </Card.Footer>\n      </Card>\n\n      <Card density=\"compact\">\n        <Card.Body>\n          <p className=\"m-0 text-opsin-body\">\n            A card with only a body, at the compact density. One idea, one\n            boundary, no ceremony.\n          </p>\n        </Card.Body>\n      </Card>\n    </div>\n  )\n}\n"

const SOURCE_BASES_BASE_DIALOG = "\"use client\"\n\n/**\n * Dialog — the window that takes a reader's place, their focus and their ability\n * to do anything else, and hands all three back where it found them.\n *\n * THE PAGE ASKED FOR TWO THINGS THAT CANNOT BOTH BE TRUE, AND THIS FILE ANSWERS\n * ONE OF THEM. `dialog.mdx:114` says `severity=\"alert\"` \"removes the close\n * control and makes the scrim non-dismissing: an alert dialogue has no valid\n * 'went away' outcome\". `dialog.mdx:124` says that below `sheetBelow` pixels\n * \"the dialog renders as a Sheet instead\" — and a Sheet is, by its own\n * specification, draggable and dismissible. Put together, an alert dialogue\n * that nobody may dismiss on a laptop becomes dismissible with a thumb on a\n * phone, silently, at whichever width the caller happened to pass. That is not\n * a styling difference; it is the safety contract inverting on the device most\n * readers use. So `sheetBelow` is not implemented and is not a prop.\n *\n * What the sentence under it was complaining about is kept. \"A modal window on\n * a 360px screen is a sheet wearing the wrong clothes\" is a complaint about\n * SHAPE, and shape is free: below the `sm` breakpoint this dialog meets the\n * bottom edge of the screen, takes the full width and rounds only its top\n * corners, which is what `tokens/shape.json` publishes `radius-xl` for. It does\n * that in CSS, at every width, with no prop, no measurement and no change of\n * component — so the role, the focus trap, the inertness and the dismissal\n * rules are identical on a phone and on a desktop. A dialog never becomes\n * something else.\n *\n * TWO ROOTS, NOT A FLAG. `severity` swaps `AlertDialog.Root` for `Dialog.Root`\n * rather than toggling props on one of them. Base UI's alert-dialog root is the\n * same store in a different mode: it forces `modal`, forces\n * `disablePointerDismissal`, and sets `role=\"alertdialog\"` — three behaviours\n * the specification requires together, arriving together, with no way for a\n * caller or a later refactor to get two of the three. Faking it with\n * `disablePointerDismissal` on the ordinary root would produce a\n * non-dismissing surface still announced as a plain dialog, which is the\n * failure that looks correct in review.\n *\n * ESCAPE IS THE ONE PART BASE UI DOES NOT DO FOR US. `useDialogRoot` passes\n * `escapeKey: isTopmost` to `useDismiss` in every mode, alert-dialog included,\n * so an untouched alert dialog closes on Escape and the whole contract is lost\n * on the keyboard. This file cancels that close through the change event's own\n * `cancel()`, and then moves focus to the safest action so the key produces a\n * visible and an announced response rather than silence. It does not write a\n * sentence saying an answer is needed: those are the product's words, they\n * belong in `description`, and a development warning asks for them.\n *\n * IT IS A CLIENT COMPONENT, and the two refs are why. `initialFocus=\"safest\"`\n * has to resolve to an ELEMENT — Base UI takes a ref or a function, never a\n * string — and the element it means is the last control in the actions slot,\n * which only a ref can find. The Escape handler needs the same ref. Nothing\n * else here is stateful: there is no width observation, no media query listener\n * and no measurement, because the responsive behaviour is a stylesheet's job.\n *\n * WHAT IT DOES NOT DO. It does not move focus on appearance beyond the one\n * placement Base UI performs on open, does not mount a live region, does not\n * animate anything a reader has asked not to see, and does not know what any of\n * its actions do. It renders no measurement, carries no clinical level, and\n * stamps neither `data-status` nor `data-category`.\n */\n\nimport { AlertDialog as AlertDialogPrimitive } from \"@base-ui/react/alert-dialog\"\nimport {\n  Dialog as DialogPrimitive,\n  type DialogRootChangeEventDetails,\n} from \"@base-ui/react/dialog\"\nimport { X } from \"lucide-react\"\nimport { useRef, useState, type ReactNode } from \"react\"\n\nimport { isDevelopment } from \"@/lib/opsinjs\"\nimport { cn } from \"@/lib/utils\"\nimport { Surface } from \"@/registry/base-lyra/ui/surface\"\n\n/**\n * What counts as somewhere focus can be put.\n *\n * Deliberately does NOT exclude `[aria-disabled=\"true\"]`. That is how this\n * system spells a control which is busy rather than unavailable — a Button\n * saving a change keeps its tab stop and its name on purpose — and skipping it\n * would send initial focus past the control the reader is waiting on.\n *\n * The popup itself carries `tabindex=\"-1\"` from Base UI so that a touch screen\n * reader can land on it, and the final clause is what keeps this selector from\n * treating that as an answer.\n */\nconst FOCUSABLE =\n  'a[href],button:not([disabled]),input:not([disabled]),select:not([disabled]),' +\n  'textarea:not([disabled]),[tabindex]:not([tabindex=\"-1\"])'\n\n/**\n * The first or the last place focus can go inside a region.\n *\n * `last` is the one that matters and it is not an arbitrary end of the row. The\n * page's own worked example orders its actions **[Delete reading] [Keep it]**\n * and then puts initial focus on *Keep it* — the action that changes nothing,\n * at the end. So the rule this component states, and the page repeats, is that\n * the action which changes something comes first and the safest one comes last,\n * and the last is where focus lands. A reader who presses Return without\n * reading gets the answer that does nothing, which is what \"defaults should be\n * safe\" means in a component rather than in a sentence.\n */\nfunction focusableIn(\n  region: HTMLElement | null,\n  which: \"first\" | \"last\",\n): HTMLElement | null {\n  if (region === null) {\n    return null\n  }\n  const found = region.querySelectorAll<HTMLElement>(FOCUSABLE)\n  return (which === \"first\" ? found[0] : found[found.length - 1]) ?? null\n}\n\n/**\n * The shape, and the one place it changes with the viewport.\n *\n * `tokens/shape.json` publishes `radius-xl` as \"sheets and dialogs\", with the\n * qualifier that it is \"applied to the leading edge only when the surface meets\n * a screen edge on the other side\" — which is exactly the phone case below the\n * `sm` breakpoint, where the dialog sits on the bottom edge. Above it the\n * dialog floats and takes the radius on all four corners.\n *\n * `corner-shape` is a property here rather than the product theme's\n * `data-opsin-shape=\"squircle\"` attribute, for the reason Card gives: the\n * attribute would be a fifth member of a data-attribute vocabulary closed at\n * four, and the stylesheet that reads it does not travel with this file into\n * somebody else's project. An engine without `corner-shape` draws an ordinary\n * rounded corner, which every radius on the ladder is chosen to survive.\n */\nconst SHAPE =\n  \"rounded-t-opsin-xl sm:rounded-opsin-xl [corner-shape:var(--opsin-corner-shape)]\"\n\n/**\n * The entrance and the exit, and the two independent reasons a reader who asked\n * for less motion gets it.\n *\n * `--opsin-duration-base` is one of the five standalone durations that\n * `app/product.css` collapses to 1ms under `prefers-reduced-motion: reduce`, so\n * the transition is over before it is visible without this file branching on\n * anything. `motion-reduce:transition-none` is the second answer and it is not\n * redundant: a consumer who installs this component without that stylesheet\n * gets the same result from the component alone.\n *\n * The dialog rises from the bottom edge on a phone, where that is the direction\n * it comes from, and scales on a wider screen, where it does not. Under reduced\n * motion neither happens and the dialog appears in place — at which point depth\n * is carried by the scrim and by the surface's edge, which is why the\n * specification says neither of those is optional and why no prop removes them.\n */\nconst MOTION = cn(\n  \"transition-[opacity,transform] duration-(--opsin-duration-base) ease-opsin-standard\",\n  \"motion-reduce:transition-none\",\n  \"data-[starting-style]:opacity-0 data-[ending-style]:opacity-0\",\n  \"data-[starting-style]:translate-y-4 data-[ending-style]:translate-y-4\",\n  \"sm:data-[starting-style]:translate-y-0 sm:data-[ending-style]:translate-y-0\",\n  \"sm:data-[starting-style]:scale-95 sm:data-[ending-style]:scale-95\",\n)\n\nexport interface DialogProps {\n  /**\n   * Whether the dialog is on screen. Required and controlled: a surface that\n   * blocks everything else is not a thing a component should be able to open by\n   * itself, and the product that owns the decision owns the state.\n   */\n  open: boolean\n  /**\n   * Called with the state the dialog wants to be in. One argument, deliberately:\n   * every reason Base UI would report is either handled inside this component\n   * or means the same thing to a caller, and a second parameter that only\n   * sometimes matters is a second parameter people copy without reading.\n   *\n   * It is not called when Escape is pressed on an alert dialog, because that\n   * dialog does not close.\n   */\n  onOpenChange: (open: boolean) => void\n  /**\n   * The accessible name, and a question wherever the dialog is asking one. It\n   * is a heading, it is always visible, and there is no prop that hides it: an\n   * unnamed modal surface is announced as \"dialog\" and nothing else.\n   */\n  title: string\n  /**\n   * What happens if the reader says yes, and what happens if they say no, in\n   * one or two sentences. Optional on an ordinary dialog and effectively\n   * required on an alert one — it is the only place the reader is told why\n   * Escape will not let them out, and its absence raises a development warning.\n   */\n  description?: string\n  /**\n   * `alert` renders `role=\"alertdialog\"`, removes the close control, stops the\n   * scrim dismissing and stops Escape closing. Use it only where going away\n   * without answering is not a valid outcome, which is rarer than it feels:\n   * almost every dialog a product reaches for has a safe answer, and that\n   * answer is a button rather than a missing exit.\n   *\n   * @default \"default\"\n   */\n  severity?: \"default\" | \"alert\"\n  /**\n   * Where focus lands when the dialog opens. `safest` puts it on the LAST\n   * control in `actions`, which is where the specification's own example puts\n   * the answer that changes nothing; `content` puts it on the first control\n   * inside `children`, for a dialog whose job is a short task rather than a\n   * question. Neither ever lands on the scrim or on the container while a\n   * control is available, and neither can be pointed at a destructive action\n   * without the caller ordering their actions the wrong way round.\n   *\n   * @default \"safest\"\n   */\n  initialFocus?: \"safest\" | \"content\"\n  /**\n   * The actions, in order, least destructive LAST. At most two — a dialog with\n   * three answers is a menu that has not admitted it — and that limit is a rule\n   * this component states rather than enforces, because `ReactNode` does not\n   * say how many controls are inside it and `React.Children.count` cannot see\n   * through a fragment.\n   *\n   * They are pinned to the foot of the dialog and never scroll away.\n   */\n  actions?: ReactNode\n  /**\n   * Anything the dialog holds beyond its title and its description: a short\n   * form, a list of what will be affected. Optional, and most confirmations\n   * need none of it.\n   *\n   * Nothing translucent goes in here. The dialog is itself a translucent rung\n   * and a translucent rung may never contain another one — a card inside a\n   * dialog is a `card`, which is opaque and is where a health value has to sit.\n   */\n  children?: ReactNode\n  /**\n   * Merged onto the container. Width belongs here: the dialog takes the full\n   * width of a phone and a readable measure above that, and a product with a\n   * genuinely wider dialog overrides it rather than asking for a prop.\n   */\n  className?: string\n}\n\nexport function Dialog({\n  open,\n  onOpenChange,\n  title,\n  description,\n  severity = \"default\",\n  initialFocus = \"safest\",\n  actions,\n  children,\n  className,\n}: DialogProps) {\n  const contentRef = useRef<HTMLDivElement | null>(null)\n  const actionsRef = useRef<HTMLDivElement | null>(null)\n\n  const nonDismissing = severity === \"alert\"\n\n  /* Development-only, and none of these is an OPSIN code. `tokens/errors.json`\n     allocates codes for mistakes a consumer makes with the CLINICAL API — a\n     status without a word, a range without a source — and a component may not\n     mint one, because that table is generated from that file and the codes are\n     a versioned contract. These three are ordinary interface defects, reported\n     in the ordinary channel.\n\n     They all render anyway. A dialog is already on screen and already holding\n     the reader's focus by the time any of this is true; taking it away to\n     report a mistake would leave a reader stranded mid-decision. */\n  if (isDevelopment()) {\n    if (title.trim() === \"\") {\n      console.warn(\n        \"[opsinjs] <Dialog> was given an empty `title`. The title is the \" +\n          \"dialog's accessible name, so without it the surface is announced as \" +\n          '\"dialog\" and nothing else, and a reader arriving by screen reader is ' +\n          \"told that something has taken over without being told what.\",\n      )\n    }\n    if (nonDismissing && actions === undefined) {\n      console.warn(\n        '[opsinjs] <Dialog severity=\"alert\"> has no `actions`. An alert dialog ' +\n          \"has no close control, its scrim does not dismiss and Escape does not \" +\n          \"close it, so its actions are the only way out of it. One with none is \" +\n          \"a surface a reader cannot leave. Either give it the answers it is \" +\n          'asking for, or use severity=\"default\", where going away is a valid ' +\n          \"outcome.\",\n      )\n    }\n    if (nonDismissing && description === undefined) {\n      console.warn(\n        '[opsinjs] <Dialog severity=\"alert\"> has no `description`. On an alert ' +\n          \"dialog the description is where the reader is told that an answer is \" +\n          \"needed and what each answer does — Escape will not let them out, and \" +\n          \"this component will not write that sentence on your behalf, because \" +\n          \"the words belong to the product that knows what the answers mean.\",\n      )\n    }\n  }\n\n  /**\n   * Base UI takes a ref, `true`, `false`, or a function returning an element.\n   * There is no string form, so the two values this component publishes are\n   * resolved here, at open time, when the popup and its parts are in the DOM.\n   *\n   * Falling back to `true` rather than to `false` is the safe direction: `true`\n   * is Base UI's own behaviour, which puts focus on the first tabbable element\n   * inside the popup, and `false` would leave focus outside a surface that has\n   * made everything outside it inert.\n   */\n  function resolveInitialFocus(): HTMLElement | true {\n    const target =\n      initialFocus === \"content\"\n        ? focusableIn(contentRef.current, \"first\")\n        : focusableIn(actionsRef.current, \"last\")\n    return target ?? true\n  }\n\n  /**\n   * THE ESCAPE KEY, WHICH IS THE ONLY PLACE THIS COMPONENT OVERRULES THE\n   * PRIMITIVE.\n   *\n   * `useDialogRoot` passes `escapeKey: isTopmost` to `useDismiss` in every mode,\n   * so Base UI's alert dialog closes on Escape exactly like an ordinary one.\n   * `DialogStore.setOpen` calls this handler first and returns early when\n   * `eventDetails.isCanceled`, which is what makes `cancel()` a refusal rather\n   * than a request.\n   *\n   * Cancelling on its own would make the key do nothing at all, and the\n   * specification is explicit that the dialog \"does not simply swallow the\n   * key\". So focus moves to the safest action: a sighted keyboard reader sees\n   * the ring land on the way out, and a screen-reader user hears that control\n   * announced. It is not a sentence, and it is not meant to be — the sentence\n   * lives in `description`, in the product's own words.\n   */\n  function handleOpenChange(\n    next: boolean,\n    details: DialogRootChangeEventDetails,\n  ): void {\n    if (!next && nonDismissing && details.reason === \"escape-key\") {\n      details.cancel()\n      focusableIn(actionsRef.current, \"last\")?.focus()\n      return\n    }\n    onOpenChange(next)\n  }\n\n  const hasBody = description !== undefined || children !== undefined\n\n  /* The whole tree below the root, written once. The root is the only thing\n     `severity` changes, and building the body separately is what keeps that\n     true: there is no branch inside here that could drift between the two\n     modes, so the alert dialog is the ordinary dialog minus its close control\n     and nothing else. */\n  const body = (\n    <DialogPrimitive.Portal data-slot=\"dialog\">\n      {/* Dialog.Scrim. A sibling of the surface it serves and never its child,\n          which is nesting rule N2 in `choosing-a-layer`: the scrim sits between\n          the dialog and everything below it in the stacking order, not inside\n          the dialog's box. It takes the `scrim` rung's own material rather than\n          a hand-picked tint, so reduced transparency, increased contrast and a\n          browser with no `backdrop-filter` all degrade it the way the token\n          source says to and not the way this file guesses.\n\n          It is decorative and it is not the mechanism that blocks the page —\n          Base UI makes everything behind genuinely inert, and dimming is what\n          the reader sees rather than what stops them. */}\n      <DialogPrimitive.Backdrop\n        data-slot=\"dialog-scrim\"\n        className={cn(\n          \"fixed inset-0\",\n          \"transition-opacity duration-(--opsin-duration-base) ease-opsin-standard\",\n          \"motion-reduce:transition-none\",\n          \"data-[starting-style]:opacity-0 data-[ending-style]:opacity-0\",\n        )}\n      >\n        <Surface rung=\"scrim\" className=\"absolute inset-0\">\n          {null}\n        </Surface>\n      </DialogPrimitive.Backdrop>\n\n      {/* Dialog.Viewport. Not in the specification's part tree and added on\n          purpose: it is the fixed, full-screen box the container is placed\n          inside, and having a real element to place against is what lets the\n          dialog sit on the bottom edge of a phone and in the middle of a laptop\n          with no transform, no measurement and no JavaScript.\n\n          `pt-opsin-16` is the one deliberate gap at phone width. A surface that\n          covers the entire screen is not covering the page \"while leaving it\n          recognisable\", which is the whole job of the rung it is on, and a\n          reader needs to see where they will return to. */}\n      <DialogPrimitive.Viewport\n        data-slot=\"dialog-viewport\"\n        className={cn(\n          \"fixed inset-0 flex items-end justify-center pt-opsin-16\",\n          \"sm:items-center sm:p-opsin-6\",\n        )}\n      >\n        {/* Dialog.Container. The popup element, carrying the role, the name and\n            the description; the material inside it is a Surface, because one\n            element cannot carry both `data-slot=\"dialog-container\"` and\n            `data-slot=\"surface\"`.\n\n            `max-h-full` resolves here because the viewport is `fixed inset-0`\n            and therefore has a definite height. That is what makes the internal\n            scroll below work at 200% text: the dialog stops at the height of\n            the screen instead of growing past it with its actions somewhere\n            below the fold. */}\n        <DialogPrimitive.Popup\n          data-slot=\"dialog-container\"\n          initialFocus={resolveInitialFocus}\n          className={cn(\n            \"flex max-h-full w-full flex-col overflow-hidden\",\n            \"sm:max-w-(--opsin-measure-tight)\",\n            SHAPE,\n            MOTION,\n            className,\n          )}\n        >\n          <Surface\n            rung=\"sheet\"\n            className={cn(\n              /* THE RUNG IS `sheet` AND THE PAGE SAYS `overlay`. ADR 0014 made\n                 the six rung names the token names, and the retired vocabulary\n                 the specification was written in put `overlay` on the rung that\n                 covers the page while leaving it recognisable. That rung is now\n                 called `sheet`. This ladder's `overlay` is chrome that content\n                 scrolls beneath — a pinned toolbar, a tab bar — so mapping the\n                 old name by spelling rather than by job would put a modal\n                 dialog on the rung built for a tab bar, and it would compile. */\n              \"flex min-h-0 flex-col rounded-[inherit]\",\n              /* The safe-area inset goes on the Surface rather than on the\n                 popup so the material covers it. Surface's three decorative\n                 layers are positioned to `inset-0`, whose containing block is\n                 the padding box, so the fill and the edge reach the bottom of\n                 the screen instead of stopping above the home indicator. */\n              \"pb-(--opsin-safe-bottom) sm:pb-0\",\n              /* Surface owns its content wrapper, so the column that holds the\n                 three regions has to be declared from out here. Without the\n                 `min-h-0` the wrapper refuses to shrink below its content and\n                 the scroll region below never gets a height to scroll in. */\n              \"[&>[data-slot=surface-content]]:flex\",\n              \"[&>[data-slot=surface-content]]:min-h-0\",\n              \"[&>[data-slot=surface-content]]:flex-col\",\n            )}\n          >\n            {/* Dialog.Header — pinned, so the question stays on screen while\n                the consequence scrolls. DOM order is visual order: the title\n                first, the close control after it, which is what makes reverse\n                tab order match what a reader sees. */}\n            <div\n              data-slot=\"dialog-header\"\n              className={cn(\n                \"flex shrink-0 items-start gap-opsin-3 px-opsin-5 pt-opsin-5\",\n                /* Every region below this one pads its own foot, so the header\n                   only pads its own when it is the last thing in the dialog —\n                   a title with no consequence, no content and no answer, which\n                   is a degenerate dialog rather than an impossible one. */\n                hasBody || actions !== undefined ? null : \"pb-opsin-5\",\n              )}\n            >\n              <DialogPrimitive.Title\n                data-slot=\"dialog-title\"\n                className=\"m-0 min-w-0 flex-1 text-opsin-title3\"\n              >\n                {title}\n              </DialogPrimitive.Title>\n\n              {/* Dialog.Close, present on a dialog and absent on an alert one.\n                  Base UI's own guidance is to render a close control inside\n                  every modal popup so a touch screen reader can escape it, and\n                  this is a deliberate departure from it rather than an\n                  oversight: on an alert dialog the actions ARE the way out, the\n                  development warning above refuses to let one ship without\n                  them, and a close control on a surface whose whole contract is\n                  \"there is no valid went-away outcome\" would be a control that\n                  contradicts the role it sits inside. */}\n              {nonDismissing ? null : (\n                <DialogPrimitive.Close\n                  data-slot=\"dialog-close\"\n                  className={cn(\n                    \"inline-flex shrink-0 items-center justify-center rounded-opsin-md\",\n                    /* The floor is carried by the control rather than by the\n                       product stylesheet's backstop, because that stylesheet\n                       does not travel with this file. It is a rem, so at 200%\n                       text it doubles with the glyph instead of pinning at 44\n                       device pixels. */\n                    \"min-h-(--opsin-target-minimum) min-w-(--opsin-target-minimum)\",\n                    \"transition-colors duration-(--opsin-duration-fast) ease-opsin-standard\",\n                    \"hover:bg-muted\",\n                    \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring\",\n                  )}\n                >\n                  <X aria-hidden=\"true\" className=\"size-[1.25em]\" />\n                  {/* The only reader-facing word this component owns, and it is\n                      English with no way to translate it. That is a real gap\n                      and it is listed on the page rather than hidden here. */}\n                  <span className=\"sr-only\">Close</span>\n                </DialogPrimitive.Close>\n              )}\n            </div>\n\n            {/* Dialog.Body — the scroll region, and the reason the actions stay\n                reachable at 200% text. `overscroll-contain` stops a flick at\n                the end of the description turning into a scroll of the page\n                behind, which is inert and should not move. */}\n            <div\n              data-slot=\"dialog-body\"\n              className={cn(\n                \"min-h-0 overflow-y-auto overscroll-contain\",\n                hasBody ? \"px-opsin-5 pt-opsin-2 pb-opsin-5\" : null,\n              )}\n            >\n              {description === undefined ? null : (\n                /* Plain foreground, not the muted role. A muted caption on a\n                   translucent surface is the thing this system's own material\n                   guidance tells products not to do, and the description is\n                   where the consequence of each answer is written — which is\n                   the last text on the screen that should be quiet. */\n                <DialogPrimitive.Description\n                  data-slot=\"dialog-description\"\n                  className=\"m-0 text-opsin-body text-foreground\"\n                >\n                  {description}\n                </DialogPrimitive.Description>\n              )}\n              {children === undefined ? null : (\n                <div\n                  data-slot=\"dialog-content\"\n                  ref={contentRef}\n                  className={cn(description === undefined ? null : \"mt-opsin-4\")}\n                >\n                  {children}\n                </div>\n              )}\n            </div>\n\n            {/* Dialog.Actions — pinned, in DOM order, least destructive last.\n                The gap is `opsin-2`, which is 0.5rem, which is exactly\n                `--opsin-target-separation`: two adjacent targets need that much\n                between them and this is the one row in the component where it\n                is this file's job rather than the caller's. */}\n            {actions === undefined ? null : (\n              <div\n                data-slot=\"dialog-actions\"\n                ref={actionsRef}\n                className={cn(\n                  \"flex shrink-0 flex-wrap items-center gap-opsin-2\",\n                  \"px-opsin-5 pt-opsin-2 pb-opsin-5 sm:justify-end\",\n                )}\n              >\n                {actions}\n              </div>\n            )}\n          </Surface>\n        </DialogPrimitive.Popup>\n      </DialogPrimitive.Viewport>\n    </DialogPrimitive.Portal>\n  )\n\n  if (nonDismissing) {\n    return (\n      <AlertDialogPrimitive.Root open={open} onOpenChange={handleOpenChange}>\n        {body}\n      </AlertDialogPrimitive.Root>\n    )\n  }\n\n  return (\n    <DialogPrimitive.Root open={open} onOpenChange={handleOpenChange}>\n      {body}\n    </DialogPrimitive.Root>\n  )\n}\n\n/**\n * The zero-prop default export (ADR 0009).\n *\n * `/view` renders this with no props and `shadcn add` ships it, so it is public,\n * reviewed code rather than a scratch demo. It is an ordinary dialog, because\n * an ordinary dialog is what almost every product actually needs and the demo\n * should not teach the exception first.\n *\n * The trigger is a plain `button` rather than this system's Button, so that the\n * file a consumer installs depends on Surface and nothing else. It carries the\n * target floor and a focus ring of its own for the same reason.\n *\n * There is not a number anywhere in it. Dialog renders no measurement, so there\n * is no reading here for anybody to mistake for their own.\n */\nexport default function DialogDemo() {\n  const [open, setOpen] = useState(false)\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col items-start gap-opsin-4\">\n      <button\n        type=\"button\"\n        onClick={() => setOpen(true)}\n        className={cn(\n          \"inline-flex min-h-(--opsin-target-minimum) items-center rounded-opsin-md\",\n          \"border border-border bg-card px-opsin-4 text-opsin-body text-card-foreground\",\n          \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring\",\n        )}\n      >\n        Delete this reading\n      </button>\n\n      <Dialog\n        open={open}\n        onOpenChange={setOpen}\n        title=\"Delete this reading?\"\n        description=\"It will be removed from your history and from any trends it appears in. This cannot be undone.\"\n        actions={\n          <>\n            <button\n              type=\"button\"\n              onClick={() => setOpen(false)}\n              className={cn(\n                \"inline-flex min-h-(--opsin-target-minimum) items-center rounded-opsin-md\",\n                \"border-2 border-border px-opsin-4 text-opsin-body\",\n                \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring\",\n              )}\n            >\n              Delete reading\n            </button>\n            <button\n              type=\"button\"\n              onClick={() => setOpen(false)}\n              className={cn(\n                \"inline-flex min-h-(--opsin-target-minimum) items-center rounded-opsin-md\",\n                \"bg-primary px-opsin-4 text-opsin-body text-primary-foreground\",\n                \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring\",\n              )}\n            >\n              Keep it\n            </button>\n          </>\n        }\n      />\n    </div>\n  )\n}\n"

const SOURCE_BASES_BASE_FIELD = "/**\n * Field — a label, its guidance, its error, and the wiring that ties all three\n * to one control.\n *\n * THIS IS THE COMPONENT THAT DECIDES WHETHER EVERY FORM IN A PRODUCT IS\n * ACCESSIBLE, once. Not because a label is hard, but because the relationships\n * are: an id that has to match a `for`, a description list that has to name two\n * elements and drop one when it unmounts, an invalid state that has to reach the\n * control rather than the wrapper. Hand-wired, those four things are correct on\n * the day they are written and wrong by the third refactor. Field's whole claim\n * is that a product never types any of them.\n *\n * WHAT IS BASE UI'S RESPONSIBILITY AND WHAT IS THIS FILE'S. A component that\n * delegates its central promise and does not say so is one nobody can audit, so\n * the split is written out here and repeated on the page.\n *\n *   Base UI (`@base-ui/react/field`, 1.7.0) owns EVERY id relationship:\n *     - `Field.Control` mints an id and registers it on the labelable context;\n *       `Field.Label` renders a real `<label for>` against that id, so the\n *       accessible name comes from a native label relationship rather than from\n *       `aria-label`.\n *     - `Field.Description` and `Field.Error` each register their own id into\n *       the same context on mount and REMOVE it on unmount; the control's\n *       `aria-describedby` is rebuilt from that set. This is the part hand-rolled\n *       forms get wrong: an error that unmounts and leaves its id behind points\n *       the description at nothing.\n *     - `aria-invalid` is applied to the control — not to the wrapper — whenever\n *       the field's computed validity is false.\n *     - `data-invalid`, `data-valid`, `data-touched`, `data-dirty`, `data-filled`,\n *       `data-focused` and `data-disabled` on the root and the control.\n *\n *   This file owns everything that is a JUDGEMENT rather than a mechanism:\n *     - that the label is required, visible and has no way to be hidden;\n *     - that the error appears IN ADDITION to the hint and never replaces it;\n *     - that the error is carried by a word, a glyph and the invalid state, and\n *       by no colour at all (see NO STATUS COLOUR below);\n *     - that optionality is marked in words inside the label, so it is part of\n *       the accessible name rather than a symbol beside it;\n *     - the `data-slot` names, the type steps, the spacing and the 44px floor.\n *\n * NO STATUS COLOUR, AND THIS IS THE DECISION MOST LIKELY TO BE \"FIXED\" BY\n * SOMEBODY LATER. A form error is not a clinical status. The four status\n * levels say how much attention a READING needs; painting a mistyped date in\n * `--opsin-status-attention-*` would teach a reader that the colour meaning\n * \"this measurement needs a decision\" also means \"you typed the date wrong\",\n * and the two-axis rule is worth nothing if the axes leak into ordinary form\n * chrome. There is also no non-clinical danger role in the product theme at\n * all: the one the docs chrome uses is declared in `app/globals.css` and\n * resolves to nothing under /view, which the accessibility gate fails a\n * component for reaching. So the error is carried by a glyph, a weight change,\n * the border\n * emphasis on the control, and the words — which is what the specification asks\n * for anyway (\"text plus an icon plus the invalid state\"), arrived at from the\n * other direction.\n *\n * The glyph is `CircleAlert` and it is deliberately NOT `TriangleAlert`. The\n * triangle is `attention`'s glyph in CLINICAL_STATUS_META, and four distinct\n * silhouettes only work as a vocabulary if nothing else in the system borrows\n * one of them.\n *\n * IT IS A SERVER COMPONENT. Every Base UI part it composes carries its own\n * 'use client', so the state, the effects and the id generation all happen\n * inside the client boundary the primitive already declares. This file adds no\n * hook, no state and no handler of its own — it maps props to markup — so a\n * directive here would only pull the wrapper into a bundle it does not need to\n * be in.\n */\n\nimport type { ComponentPropsWithoutRef, CSSProperties, ReactElement, ReactNode } from \"react\"\n\nimport { Field as FieldPrimitive } from \"@base-ui/react/field\"\nimport { CircleAlert } from \"lucide-react\"\n\nimport { isDevelopment } from \"@/lib/opsinjs\"\nimport { cn } from \"@/lib/utils\"\n\n/**\n * The two words Field ships, and the only reader-facing copy it owns.\n *\n * They are words rather than an asterisk on purpose: the specification asks for\n * required and optional to be \"marked in text, with a legend where a symbol is\n * used\", and a marker that needs a legend is a marker most readers meet without\n * one. Rendered inside the `<label>`, so the accessible name is\n * \"Example measurement (optional)\" and a screen-reader user hears the exception\n * at the same moment a sighted reader sees it — rather than as a floating\n * symbol somewhere near the field.\n *\n * They are English, and there is no prop to translate them. That is a real gap\n * and it is listed on the page rather than hidden here.\n */\nconst OPTIONALITY_WORD: Record<\"required\" | \"optional\", string> = {\n  required: \"(required)\",\n  optional: \"(optional)\",\n}\n\n/**\n * `validateOn` in this system's vocabulary, mapped to Base UI's.\n *\n * TWO OF THE THREE VALUES COLLAPSE ONTO ONE MODE, and pretending otherwise\n * would be the more comfortable lie. Base UI's `onSubmit` is documented as\n * \"triggers validation when the form is submitted, and re-validates on change\n * after submission\" — which IS this system's `submit-then-change`. There is no\n * mode that validates on submit and then refuses to look again, so `\"submit\"`\n * takes the same one.\n *\n * That is the harmless direction of the two. A field that re-checks itself\n * after the reader corrects it clears its error as soon as the correction is\n * typed; the mode this cannot express would leave a corrected field still\n * marked invalid until the next submit, which is the cruelty the specification\n * names. Field is more forgiving than asked, never less.\n */\nconst VALIDATION_MODE: Record<\n  \"blur\" | \"submit\" | \"submit-then-change\",\n  \"onBlur\" | \"onSubmit\" | \"onChange\"\n> = {\n  blur: \"onBlur\",\n  submit: \"onSubmit\",\n  \"submit-then-change\": \"onSubmit\",\n}\n\n/**\n * Written out rather than assembled, because Tailwind reads class names as\n * literal strings and anything built at runtime generates no CSS at all.\n *\n * Three things here are load-bearing and easy to mistake for taste:\n *\n *   `min-h-[var(--opsin-target-minimum)]` — the product stylesheet's 44px\n *   backstop covers `button`, `[role=\"button\"]`, checkboxes and radios, and\n *   NOT a text input. The floor has to be set here or it is not set. The\n *   generated token is a rem, so it grows with the reader's own text size; the\n *   shorter authored spelling in `app/product.css` is a hard 44px that does\n *   not, and it is being retired.\n *\n *   No focus styles. `app/product.css` already gives every `:focus-visible` a\n *   two-pixel ring in `--ring` with a two-pixel offset, so a component that\n *   writes its own is a component that will drift from the rest of the product\n *   the first time that rule changes.\n *\n *   `data-[invalid]:` and not a colour. Base UI stamps `data-invalid` on the\n *   control, so the emphasis border tracks the field's real validity — the\n *   `error` prop AND a native constraint that failed — rather than only the\n *   half this file knows about. It is an inset shadow rather than a wider\n *   border so that nothing moves by a pixel when the error appears.\n *\n * AND ONE TRAP, because this list goes through `cn()` and the parts above do\n * not. `cn` is `twMerge(clsx(...))`, and tailwind-merge is unconfigured — it\n * has never been told that `--text-opsin-*` is a font-size namespace, so it\n * files `text-opsin-body` and `text-foreground` in the SAME conflict group and\n * silently drops whichever comes first. There is no ordering that keeps both.\n * So the size is set here and the colour is not: Tailwind's preflight already\n * gives every form control `color: inherit`, which takes the page's foreground\n * and is one fewer value to keep in step. Adding a text colour to this list\n * would remove the type step, not sit beside it.\n */\nconst CONTROL_CLASS = [\n  \"block w-full min-h-[var(--opsin-target-minimum)]\",\n  \"rounded-opsin-sm border border-input bg-background\",\n  \"px-opsin-3 py-opsin-2\",\n  \"placeholder:text-muted-foreground text-opsin-body\",\n  \"data-[invalid]:shadow-[inset_0_0_0_var(--opsin-border-emphasis)_currentColor]\",\n  \"disabled:opacity-70\",\n].join(\" \")\n\n/**\n * The error's classes, shared by both branches below so they cannot drift.\n *\n * `items-start` and not `items-center`: at 200% text a message wraps to three\n * lines, and a centred glyph then floats in the middle of the paragraph.\n */\nconst ERROR_CLASS =\n  \"m-0 flex items-start gap-opsin-1 text-opsin-headline text-foreground\"\n\nexport interface FieldProps {\n  /**\n   * Required, visible, and never hidden. There is no `hideLabel` prop and no\n   * value of any other prop that removes it: a control whose name lives only in\n   * a placeholder loses it the moment somebody types.\n   */\n  label: string\n  /**\n   * The control. Put a `Field.Control` here — Field supplies its id, its\n   * `aria-describedby` and its invalid state through context, so a product\n   * never wires them by hand. Anything else that participates in Base UI's\n   * field context works too; anything that does not gets a label pointing at\n   * nothing, which is the one failure this component cannot detect for you.\n   */\n  children: ReactNode\n  /**\n   * Guidance shown before a mistake rather than after it. Stays visible when an\n   * error appears, because a reader who has just made a mistake still needs the\n   * guidance that would have prevented it.\n   */\n  hint?: string\n  /**\n   * The error message, in the product's own words. Its presence marks the\n   * control invalid and adds the message to the control's description; it never\n   * removes the hint. Omit it and the field falls back to whatever the browser\n   * says about the control's own constraints, which is words opsinjs has not\n   * written.\n   */\n  error?: string\n  /**\n   * Which state is marked, in words, inside the label. Mark the exception: in a\n   * form where most fields are required, mark the optional ones, and the\n   * reverse. Defaults to `\"none\"`, because marking both is the same as marking\n   * neither.\n   */\n  optionality?: \"required\" | \"optional\" | \"none\"\n  /**\n   * When the control's own constraints are checked. Governs the invalid state,\n   * not the `error` prop — a message the product passed in is a message the\n   * product has already decided to show. Defaults to `\"submit-then-change\"`:\n   * never tell somebody their answer is wrong while they are still typing it.\n   */\n  validateOn?: \"blur\" | \"submit\" | \"submit-then-change\"\n  /**\n   * Merged onto the root. Field lays its own parts out in a column and leaves\n   * the space BETWEEN fields to the form, which is the only place that knows\n   * how many there are.\n   */\n  className?: string\n}\n\nexport function Field({\n  label,\n  children,\n  hint,\n  error,\n  optionality = \"none\",\n  validateOn = \"submit-then-change\",\n  className,\n}: FieldProps) {\n  /* THE TWO FAILURES THAT ARE WORTH A WARNING, and neither gets an OPSIN code.\n     `tokens/errors.json` has no entry for either, and a component may not mint\n     one: the table is generated from that file and the codes are a versioned\n     contract. A plain development warning is the honest channel.\n\n     Nothing is dropped from the render in either case. Field wraps somebody's\n     form control, and refusing to draw it in order to report a copy mistake\n     takes the form off the screen. */\n  if (isDevelopment() && label.trim() === \"\") {\n    console.warn(\n      \"[opsinjs] <Field> was given an empty `label`. The control now has no \" +\n        \"accessible name, which is the single thing this component exists to \" +\n        \"prevent. No substitute is invented here on purpose: a made-up name \" +\n        'like \"Field\" would silence the audit that would otherwise catch this. ' +\n        \"See /docs/components/field.\",\n    )\n  }\n\n  const message = error !== undefined && error.trim() !== \"\" ? error : undefined\n\n  if (isDevelopment() && error !== undefined && message === undefined) {\n    console.warn(\n      '[opsinjs] <Field label=\"' +\n        label +\n        '\"> was given an empty `error` string. An ' +\n        \"empty message would have marked the control invalid and then said \" +\n        \"nothing about why, so it was ignored. Pass a sentence that says what \" +\n        \"went wrong and what to do, or omit the prop.\",\n    )\n  }\n\n  const marker = optionality === \"none\" ? null : OPTIONALITY_WORD[optionality]\n\n  return (\n    <FieldPrimitive.Root\n      data-slot=\"field\"\n      /* App-controlled invalidity. Base UI keeps this true even while the\n         field's own constraint validation says otherwise, which is what makes\n         a form library's verdict win over the browser's. */\n      invalid={message !== undefined}\n      validationMode={VALIDATION_MODE[validateOn]}\n      className={cn(\"flex w-full flex-col gap-opsin-2\", className)}\n    >\n      {/* `text-opsin-headline` is body size at the emphasis weight — the same\n          size, leading and tracking as the answer the reader is about to type,\n          heavier. A label set smaller than the field it labels is a label that\n          stops being read. It wraps rather than truncating, which is the whole\n          of the 200%-text requirement for this part. */}\n      <FieldPrimitive.Label\n        data-slot=\"field-label\"\n        className=\"text-opsin-headline text-foreground\"\n      >\n        {label}\n        {marker === null ? null : (\n          <>\n            {\" \"}\n            {/* Inside the label, so it joins the accessible name. It takes the\n                full foreground colour and is distinguished by WEIGHT rather\n                than by being greyed out: required-or-optional is information a\n                reader acts on, and information does not go in the colour\n                reserved for things that can be skipped. */}\n            <span data-slot=\"field-optionality\" className=\"font-normal\">\n              {marker}\n            </span>\n          </>\n        )}\n      </FieldPrimitive.Label>\n\n      {/* The hint is set at BODY size, not smaller. Shrinking guidance is how\n          it stops being read, and this system's readers are laypeople looking\n          at their own health data rather than people who have used the form\n          before. The muted role is what separates it from the label. */}\n      {hint === undefined || hint.trim() === \"\" ? null : (\n        <FieldPrimitive.Description\n          data-slot=\"field-hint\"\n          className=\"m-0 text-opsin-body text-muted-foreground\"\n        >\n          {hint}\n        </FieldPrimitive.Description>\n      )}\n\n      {children}\n\n      {/* ONE ELEMENT, TWO SOURCES OF WORDS.\n          With `error`, `match` is forced on and the product's sentence is the\n          content — the branch that should be taken in a shipped product.\n          Without it, Base UI decides: the element mounts only when the\n          control's own constraints have failed at the moment `validateOn`\n          prescribes, and the content is the browser's message.\n\n          The fallback is kept rather than suppressed because the alternative is\n          worse: `aria-invalid` on a control with nothing describing it tells a\n          reader something is wrong and refuses to say what. It is still a\n          fallback, and it is still the browser's tone rather than this\n          system's, which is why the page tells you to pass `error`.\n\n          Both branches render the same element type in the same position, so\n          React reuses the node and the id registered on the description\n          context does not churn. */}\n      {message === undefined ? (\n        <FieldPrimitive.Error data-slot=\"field-error\" className={ERROR_CLASS} />\n      ) : (\n        <FieldPrimitive.Error match data-slot=\"field-error\" className={ERROR_CLASS}>\n          {/* Decorative: the sentence beside it carries the meaning. Sized in\n              em so it grows with the text rather than staying put while the\n              words around it get bigger, and pushed down by a fraction of a\n              line so it sits on the first line's baseline rather than at the\n              top of a two-line message. */}\n          <CircleAlert aria-hidden=\"true\" className=\"mt-[0.2em] size-[1em] shrink-0\" />\n          <span>{message}</span>\n        </FieldPrimitive.Error>\n      )}\n    </FieldPrimitive.Root>\n  )\n}\n\ntype NativeInputProps = Omit<\n  ComponentPropsWithoutRef<\"input\">,\n  \"children\" | \"className\" | \"color\" | \"defaultValue\" | \"style\"\n>\n\nexport interface FieldControlProps extends NativeInputProps {\n  /**\n   * Renders a different element in place of the `<input>`, keeping every id and\n   * aria attribute Field generated: `render={<textarea rows={3} />}`. This is\n   * the escape hatch that makes the wiring guarantee survive a control opsinjs\n   * does not ship.\n   */\n  render?: ReactElement\n  /**\n   * Only meaningful alongside `render`, for an element that has children of its\n   * own — the `<option>` list of a `<select>`. An `<input>` is void and takes\n   * none.\n   */\n  children?: ReactNode\n  /** Merged onto the control. The control's own classes win where they conflict. */\n  className?: string\n  /** The uncontrolled starting value. Use `value` and `onChange` for a controlled control. */\n  defaultValue?: string | number | readonly string[]\n  /** Merged onto the control. */\n  style?: CSSProperties\n}\n\n/**\n * The one part of Field that is a real export rather than a `data-slot`.\n *\n * Everywhere else in opsinjs a part is internal structure identified by\n * `data-slot`, because the content arrives as a prop. Field is one of three\n * exceptions, and the reason is specific: the CONSUMER supplies the control, and\n * there is no prop that could carry an `<input>` with its own type, name,\n * `autocomplete`, `inputmode`, value and change handler. So the slot is a\n * component, and it is the only way to get the generated id, the description\n * list and the invalid state onto an element this file never sees.\n *\n * It sets no `autocomplete` and no `inputmode` of its own. Both are required by\n * the accessibility contract and both are answers only the product has: the\n * right `autocomplete` token depends on what is being asked for, and a guess\n * would fill somebody's postcode into a field asking for something else.\n */\nexport function FieldControl({ className, ...props }: FieldControlProps) {\n  return (\n    <FieldPrimitive.Control\n      {...props}\n      data-slot=\"field-control\"\n      className={cn(CONTROL_CLASS, className)}\n    />\n  )\n}\n\n/* Assigned after the declaration rather than through `Object.assign`, so the\n   function keeps its name in a stack trace and in React devtools. */\nField.Control = FieldControl\n\n/**\n * The zero-prop default export (ADR 0009).\n *\n * `/view` renders this with no props and `shadcn add` ships it, so it is public,\n * reviewed code rather than a scratch demo. It shows the three states that\n * decide whether this component is worth having: a field with guidance, a field\n * whose exception is marked, and a field with an error — where the point is\n * what has NOT happened, because the hint is still there underneath it.\n *\n * The labels are deliberately unreal (ADR 0012). Nothing here is a measurement\n * anybody could mistake for their own, and the date is one nobody has.\n */\nexport default function FieldDemo() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-opsin-6\">\n      <Field label=\"Example measurement\" hint=\"For example, 14.\">\n        <Field.Control\n          name=\"example-measurement\"\n          inputMode=\"decimal\"\n          autoComplete=\"off\"\n        />\n      </Field>\n\n      <Field\n        label=\"Example note\"\n        optionality=\"optional\"\n        hint=\"Anything you want to remember about this entry.\"\n      >\n        <Field.Control name=\"example-note\" autoComplete=\"off\" />\n      </Field>\n\n      <Field\n        label=\"Example date\"\n        hint=\"For example, 27 3 1985.\"\n        error=\"Enter a date in the past.\"\n      >\n        <Field.Control\n          name=\"example-date\"\n          inputMode=\"numeric\"\n          autoComplete=\"off\"\n          defaultValue=\"27 3 3985\"\n        />\n      </Field>\n    </div>\n  )\n}\n"

const SOURCE_BASES_BASE_SHEET = "\"use client\"\n\n/**\n * Sheet — a panel that comes up from the bottom edge, rests at a stated height,\n * and can always be left.\n *\n * WHY THIS FILE IS `\"use client\"` AND SURFACE IS NOT. Surface answers every\n * question it has with a media query, so it renders once on the server and is\n * correct forever. A Sheet cannot: it holds which detent it is resting at, it\n * mounts a portal, it moves focus, and it listens for a drag. None of that has\n * a CSS answer, so the directive is a requirement rather than a convenience —\n * and it is on this file rather than borrowed from Base UI, because the demo at\n * the bottom holds state of its own and a file whose demo needs `useState` is a\n * client file whatever its imports say.\n *\n * THERE IS NO `sheet` PRIMITIVE IN BASE UI 1.7.0. `@base-ui/react/drawer` is\n * the one this is built on, and the mapping is not one-to-one — every place the\n * two vocabularies disagree is written out beside the code that resolves it,\n * because a wrapper that quietly renames a prop is a wrapper nobody can audit:\n *\n *   spec `dismissible`  ↔ Base UI `disablePointerDismissal`  (INVERTED, and\n *                         Base UI's covers the pointer only, so the escape key\n *                         and the close watcher are cancelled by hand below)\n *   spec `detents`      ↔ Base UI `snapPoints`               (fractions, pixels\n *                         or rems — there is no content-sized snap point)\n *   spec `modal`        ↔ Base UI `modal`                    (Base UI has a\n *                         third state, `'trap-focus'`, that this API does not\n *                         model and deliberately does not expose)\n *   spec `title`        ↔ `Drawer.Title`                     (a part, not a\n *                         root prop; it is what `aria-labelledby` points at)\n *\n * A MODAL SURFACE OWNS ITS OWN `open`/`onOpenChange`, AND THAT IS DECIDED HERE.\n * The specifications for LogSheet and ConsentSheet both say they \"extend Sheet\"\n * and neither declares `open` or `onOpenChange`, so as written neither of them\n * can be opened. The resolution belongs in the base rather than in each\n * descendant: a surface that takes the screen decides nothing about when it is\n * on it, and a component that extends Sheet inherits both props unchanged.\n *\n * `onOpenChange` TAKES A SECOND ARGUMENT THE SPECIFICATION DOES NOT DECLARE,\n * and it is not decoration. The page requires that a sheet holding unsaved\n * input \"asks first — by the same route as a background tap\", which a product\n * cannot do unless it is told which route was taken. A one-argument handler is\n * still assignable to the two-argument type, so `onOpenChange={setOpen}` keeps\n * working and a product that needs the route can read it.\n *\n * WHAT IT DOES NOT DO. It mounts no live region, it announces nothing on its\n * own behalf, and it never decides that a reader has finished. It also refuses\n * to be a Dialog: there is no way to make a Sheet undismissable AND unclosable,\n * because the one modal surface with no valid way out is a question, and a\n * question is `Dialog`.\n */\n\nimport { Drawer } from \"@base-ui/react/drawer\"\nimport { X } from \"lucide-react\"\nimport {\n  Children,\n  createContext,\n  isValidElement,\n  useContext,\n  useState,\n  type ReactNode,\n} from \"react\"\n\nimport { isDevelopment, type Detent } from \"@/lib/opsinjs\"\nimport { cn } from \"@/lib/utils\"\nimport { Button } from \"@/registry/base-lyra/ui/button\"\nimport { Surface } from \"@/registry/base-lyra/ui/surface\"\n\n/**\n * How a close was asked for.\n *\n * Five routes rather than Base UI's nine, because the distinctions this\n * component's accessibility contract turns on are coarser than the ones the\n * primitive reports. What matters to a product is whether the reader made a\n * deliberate exit (`close-control`) or brushed against one of the ambient ones\n * (`scrim`, `escape`, `drag`) — the first needs no confirmation and the other\n * three, over unsaved input, need the same one.\n *\n * Module-local, not exported: a registry file's public surface is its props,\n * its component and its demo, and callers name this as\n * `SheetProps[\"onOpenChange\"]`'s second parameter.\n */\ntype SheetDismissRoute = \"close-control\" | \"scrim\" | \"escape\" | \"drag\" | \"other\"\n\n/**\n * Base UI's reason, translated. `closeWatcher` joins `escapeKey` because it is\n * the same intention arriving through the platform's back gesture instead of\n * through a key, and a product that confirms one and not the other has a hole\n * on exactly the devices where a sheet matters most.\n */\nfunction routeFor(reason: string): SheetDismissRoute {\n  switch (reason) {\n    case \"closePress\":\n      return \"close-control\"\n    case \"outsidePress\":\n      return \"scrim\"\n    case \"escapeKey\":\n    case \"closeWatcher\":\n      return \"escape\"\n    case \"swipe\":\n      return \"drag\"\n    default:\n      return \"other\"\n  }\n}\n\n/**\n * The two detents that have a numeric answer, as fractions of the viewport.\n *\n * `content` is deliberately absent and the reason is mechanical rather than\n * aesthetic. Base UI resolves every snap point against the popup's own measured\n * height and clamps it there (`useDrawerSnapPoints`: `offset = popupHeight -\n * clampedHeight`), so a sheet that can reach `full` has to be viewport-tall —\n * and once it is, its natural height IS the viewport and there is no content\n * height left to snap to. The two requirements are not satisfiable at the same\n * time, so `content` is supported as the only detent, where it needs no snap\n * point at all: the popup takes its own height and the browser lays it out.\n */\nconst VIEWPORT_FRACTION: Record<\"half\" | \"full\", number> = {\n  half: 0.5,\n  full: 1,\n}\n\n/**\n * What each detent is called when the grabber has to say what it will do.\n *\n * Plain words rather than the API's own values: the reader of the accessible\n * name is a person using the product, not a person reading this file, and\n * \"half\" on its own is an adjective with no noun.\n */\nconst DETENT_WORD: Record<Detent, string> = {\n  content: \"fit the content\",\n  half: \"half the screen\",\n  full: \"the full screen\",\n}\n\n/**\n * The default, and the reason it is the smallest of the three.\n *\n * Declared at module scope rather than inline in the parameter list so that the\n * array identity is stable across renders — an inline `= [\"content\"]` is a new\n * array every time and would defeat any memo that is ever added below it.\n */\nconst DEFAULT_DETENTS: Detent[] = [\"content\"]\n\nfunction isDetent(value: unknown): value is Detent {\n  return value === \"content\" || value === \"half\" || value === \"full\"\n}\n\n/**\n * How deep in a stack of Sheets this one is.\n *\n * Base UI supports nested drawers on purpose and this system forbids them on\n * purpose, so the primitive cannot report the mistake and this context is how\n * the component sees it. A count rather than a boolean because the warning is\n * more useful when it can say how many deep the reader has got.\n */\nconst SheetDepth = createContext(0)\n\n/**\n * Whether the caller placed a `Sheet.Content` among the direct children.\n *\n * SAY EXACTLY WHAT THIS CAN SEE, because a check that over-promises is worse\n * than none. It reads direct children only. A `Sheet.Content` wrapped in a\n * `<div>` or a fragment is invisible to it and reports a false absence, which\n * is why the warning names what it looked at rather than asserting a defect.\n * The failure it exists to catch is the common one: content that overflows a\n * sheet with no scroll boundary, where a flick meant to scroll dismisses the\n * sheet instead, because Base UI treats every touch outside `[data-drawer-content]`\n * as a swipe.\n */\nfunction hasContentSlot(children: ReactNode): boolean {\n  return Children.toArray(children).some(\n    (child) => isValidElement(child) && child.type === SheetContent,\n  )\n}\n\n/**\n * The detents this sheet will actually rest at, from the ones it was given.\n *\n * Order is preserved because the specification says \"rest positions, in order\"\n * and the first one is where the sheet opens. Duplicates are dropped silently —\n * two identical stops are not a mistake worth a warning, and Base UI\n * deduplicates resolved heights within a pixel anyway.\n */\nfunction resolveDetents(detents: Detent[]): Detent[] {\n  const stops: Detent[] = []\n\n  for (const detent of detents) {\n    if (!isDetent(detent)) {\n      if (isDevelopment()) {\n        console.warn(\n          `[opsinjs] <Sheet> was given the detent \"${String(detent)}\", which is ` +\n            \"not one of content, half or full. It was ignored.\",\n        )\n      }\n      continue\n    }\n    if (!stops.includes(detent)) stops.push(detent)\n  }\n\n  if (stops.length === 0) {\n    if (isDevelopment()) {\n      console.warn(\n        \"[opsinjs] <Sheet> was given an empty `detents` array. A sheet with no \" +\n          'rest position has no height, so it fell back to [\"content\"].',\n      )\n    }\n    return DEFAULT_DETENTS\n  }\n\n  if (stops.length > 1 && stops.includes(\"content\")) {\n    const measured = stops.filter((stop) => stop !== \"content\")\n    if (isDevelopment()) {\n      console.warn(\n        \"[opsinjs] <Sheet> was given `content` alongside another detent. A \" +\n          \"content-sized stop and a viewport-sized stop cannot both exist: a \" +\n          \"sheet that can reach half or full is as tall as the viewport, and a \" +\n          \"snap point is resolved against the sheet's own height. `content` was \" +\n          `dropped; the sheet rests at ${measured.join(\" and \")}.`,\n      )\n    }\n    return measured\n  }\n\n  return stops\n}\n\n/**\n * Base UI's snap points for a set of detents, or `undefined` for the\n * content-sized sheet, which needs none.\n */\nfunction toSnapPoints(stops: Detent[]): number[] | undefined {\n  const points: number[] = []\n  for (const stop of stops) {\n    if (stop === \"content\") return undefined\n    points.push(VIEWPORT_FRACTION[stop])\n  }\n  return points.length > 0 ? points : undefined\n}\n\n/**\n * The popup's resting transform, as a class rather than an inline style, and\n * this is the one line in the file most likely to be \"simplified\" into a bug.\n *\n * Base UI writes `transform` inline on the popup WHILE a drag is in flight and\n * writes nothing there the rest of the time, publishing the movement as\n * `--drawer-swipe-movement-y` and the active stop as\n * `--drawer-snap-point-offset` instead. An inline style here would win against\n * the one it writes during the drag and freeze the sheet under the reader's\n * finger; a Tailwind `translate-y-*` utility would set the `translate`\n * property, which composes with `transform` rather than being replaced by it,\n * and the sheet would move twice as far. So it is an arbitrary `transform`\n * property, in a class, where the primitive's inline style beats it exactly\n * when it should.\n */\nconst RESTING_TRANSFORM =\n  \"[transform:translateY(calc(var(--drawer-snap-point-offset,0px)_+_var(--drawer-swipe-movement-y,0px)))]\"\n\n/**\n * Off the bottom edge, on the way in and on the way out.\n *\n * A whole `transform` rather than an added term, so it replaces the resting one\n * outright: a sheet entering is not at a detent yet and must not be offset by\n * one. `100%` is of the popup's own height, so it is off-screen at every detent\n * and at every text size without a measurement.\n */\nconst OFFSCREEN_TRANSFORM =\n  \"data-starting-style:[transform:translateY(100%)] data-ending-style:[transform:translateY(100%)]\"\n\n/**\n * The slide.\n *\n * `spring-sheet` paired with its own duration, never crossed with another\n * spring's: a `linear()` stop list runs from 0 to 1 whatever the spring, so\n * putting one spring's curve on another's duration produces a different spring\n * rather than a faster one.\n *\n * `motion-reduce:transition-none` is the component's own answer and not a\n * duplicate of the token layer's. Under `prefers-reduced-motion` the token\n * layer collapses `--opsin-duration-spring-sheet` to 120ms, which is the right\n * answer for a cue that says a value changed and the wrong one for a panel\n * travelling the height of the screen — 120ms of full-height translation is\n * still the slide the page says to remove. Removing the transition leaves the\n * sheet appearing at its detent, and the drag still works: reduced motion is\n * not reduced capability.\n */\nconst SLIDE =\n  \"transition-transform duration-(--opsin-duration-spring-sheet) ease-opsin-spring-sheet motion-reduce:transition-none\"\n\n/**\n * How the Surface inside the popup is told to lay its content out.\n *\n * Surface owns the class list on its own content wrapper and takes no prop for\n * it, so a composing component reaches it by its `data-slot` — which is the\n * whole point of the slot contract, and is the supported way to do this rather\n * than a workaround. Without it the header, the scrolling content and the\n * footer are three blocks in normal flow, the content has no bounded height,\n * and `overflow-y: auto` on it does nothing at all.\n *\n * `flex-auto` and not `flex-1`: `flex-1` sets a zero flex basis, and a sheet\n * whose height is its content's would then compute that height as zero.\n */\nconst SURFACE_LAYOUT = [\n  \"flex min-h-0 flex-auto flex-col\",\n  \"[&>[data-slot=surface-content]]:flex\",\n  \"[&>[data-slot=surface-content]]:min-h-0\",\n  \"[&>[data-slot=surface-content]]:flex-auto\",\n  \"[&>[data-slot=surface-content]]:flex-col\",\n].join(\" \")\n\n/**\n * The focus ring, declared here rather than inherited.\n *\n * `app/product.css` gives every `:focus-visible` an outline, and that file does\n * not travel with this one into a consumer's project. A control whose ring\n * depends on a stylesheet it was not installed with is a control that loses it\n * silently, on the surface where a keyboard reader most needs to know where\n * they are.\n */\nconst FOCUS_RING =\n  \"focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring\"\n\nexport interface SheetProps {\n  /**\n   * Whether the sheet is on screen. Required and controlled: a modal surface\n   * that owned its own visibility would be a surface a product could not close\n   * when the data underneath it changed.\n   */\n  open: boolean\n  /**\n   * Called when the sheet asks to open or close. The second argument says which\n   * route was taken — `close-control` for the header's close button,\n   * `scrim` for a tap on the background, `escape` for the escape key or the\n   * platform's back gesture, `drag` for a swipe down, and `other` for anything\n   * else, including a close the product asked for itself.\n   *\n   * The sheet does not close itself: `open` is the only thing that closes it.\n   * That is what makes \"ask before discarding unsaved input\" possible — leave\n   * `open` alone, show the confirmation, and close when the reader answers.\n   */\n  onOpenChange: (open: boolean, route: SheetDismissRoute) => void\n  /**\n   * The sheet's accessible name, and a visible heading. Required: an unnamed\n   * modal surface is announced as \"dialog\" and nothing else, which tells a\n   * screen-reader user that something has taken the screen and not what.\n   */\n  title: string\n  /**\n   * Rest positions, in order; the first is where the sheet opens. A single\n   * entry disables drag-between-detents, which is the common case and the\n   * default.\n   *\n   * `\"content\"` is supported only on its own. It is not a snap point but the\n   * absence of one: the sheet takes its own height, up to the full viewport,\n   * and the browser lays it out. `\"half\"` and `\"full\"` are fractions of the\n   * viewport and can be combined; passing `\"content\"` alongside either drops it\n   * with a development warning, because a sheet that can reach the full screen\n   * is already as tall as the screen and has no content height to return to.\n   *\n   * @default [\"content\"]\n   */\n  detents?: Detent[]\n  /**\n   * Traps focus and makes the page behind genuinely inert — not dimmed, but\n   * unreachable, by a pointer and by assistive technology alike. Non-modal does\n   * neither and is a different component wearing the same clothes; the flag\n   * exists so that the difference is declared rather than emergent.\n   *\n   * @default true\n   */\n  modal?: boolean\n  /**\n   * Whether the scrim, the escape key and a downward drag close the sheet. Set\n   * it `false` for a form, where each of those three is an accident waiting to\n   * throw away what somebody typed. It never removes the close control in the\n   * header: a modal surface with no way out is a trap, and the one surface that\n   * legitimately has no \"went away\" outcome is a `Dialog`.\n   *\n   * @default true\n   */\n  dismissible?: boolean\n  /**\n   * The pinned action area. A prop rather than a compound part because a prop\n   * can carry it, and because the pinning is the point: the footer sits outside\n   * the scrolling region, above the software keyboard and above the safe-area\n   * inset, so the primary action cannot be scrolled away from or covered.\n   */\n  footer?: ReactNode\n  /**\n   * Merged onto the sheet's container. Width belongs here: a sheet is as wide\n   * as the screen by default, and a product that wants it narrower on a large\n   * display knows something about its layout that this component does not.\n   */\n  className?: string\n  /**\n   * What the sheet holds. Usually a single `Sheet.Content`, which is the\n   * scrolling region; anything placed beside it does not scroll.\n   */\n  children: ReactNode\n}\n\nexport function Sheet({\n  open,\n  onOpenChange,\n  title,\n  detents = DEFAULT_DETENTS,\n  modal = true,\n  dismissible = true,\n  footer,\n  className,\n  children,\n}: SheetProps) {\n  const depth = useContext(SheetDepth)\n  const stops = resolveDetents(detents)\n  const snapPoints = toSnapPoints(stops)\n  const [stopIndex, setStopIndex] = useState(0)\n  const [openLastRender, setOpenLastRender] = useState(open)\n\n  /* Back to the first detent on every open. A sheet that reopened at whatever\n     height the reader last dragged it to would be a sheet whose size depends on\n     something they did minutes ago and cannot see; \"the first is where it\n     opens\" is only true if it is true every time.\n\n     Adjusted during the render that notices the change rather than in an\n     effect, which is React's own answer for state derived from a prop: an\n     effect would commit the sheet at the old detent, paint it, and then correct\n     it — one frame of the sheet at the height it was left at last time, on the\n     way in. */\n  if (openLastRender !== open) {\n    setOpenLastRender(open)\n    if (open) setStopIndex(0)\n  }\n\n  if (isDevelopment()) {\n    if (depth > 0) {\n      console.warn(\n        \"[opsinjs] A <Sheet> is nested inside another <Sheet>. Two stacked \" +\n          \"modal surfaces produce a focus order nobody can predict and an \" +\n          \"escape key with two plausible meanings. Put the second task on the \" +\n          \"first sheet, or make it a screen.\",\n      )\n    }\n    /* `typeof` first because this file ships as source into JavaScript\n       projects, where `title: string` is advice and `title.trim()` on whatever\n       arrived is a crash rather than a warning. */\n    if (typeof title !== \"string\" || title.trim() === \"\") {\n      console.warn(\n        \"[opsinjs] <Sheet> was given an empty `title`. It is the accessible \" +\n          \"name, and without it the sheet is announced as \\\"dialog\\\" and \" +\n          \"nothing else. There is no honest default; name the task the reader \" +\n          \"came here to do.\",\n      )\n    }\n    if (open && !hasContentSlot(children)) {\n      console.warn(\n        \"[opsinjs] <Sheet> has no <Sheet.Content> among its direct children. \" +\n          \"That element is the scroll boundary: without it nothing inside the \" +\n          \"sheet scrolls, and a flick meant to scroll is read as a drag and \" +\n          \"dismisses the sheet. This check reads direct children only, so a \" +\n          \"Sheet.Content wrapped in another element is invisible to it.\",\n      )\n    }\n  }\n\n  const index = Math.min(stopIndex, stops.length - 1)\n  const nextStop = stops[(index + 1) % stops.length]\n  const canChangeDetent = stops.length > 1\n\n  return (\n    <SheetDepth.Provider value={depth + 1}>\n      <Drawer.Root\n        open={open}\n        modal={modal}\n        /* INVERTED, AND THE POLARITY IS THE WHOLE PROP. Base UI's flag disables\n           dismissal; this API's enables it. Getting it the wrong way round\n           ships a form sheet that throws away what somebody typed the first\n           time their thumb lands beside it. */\n        disablePointerDismissal={!dismissible}\n        snapPoints={snapPoints}\n        snapPoint={snapPoints ? snapPoints[index] : undefined}\n        onSnapPointChange={(snapPoint) => {\n          if (!snapPoints || typeof snapPoint !== \"number\") return\n          const next = snapPoints.indexOf(snapPoint)\n          if (next >= 0) setStopIndex(next)\n        }}\n        onOpenChange={(nextOpen, details) => {\n          const route = routeFor(details.reason)\n          /* `disablePointerDismissal` covers the pointer and nothing else — the\n             escape key and the platform's close watcher reach the primitive by\n             a different path and would close an undismissable sheet. Cancelling\n             here is the other half of the same promise. The close control is\n             never cancelled: `dismissible` governs the ambient routes, not the\n             deliberate one. */\n          if (!nextOpen && !dismissible && route !== \"close-control\") {\n            details.cancel()\n            return\n          }\n          onOpenChange(nextOpen, route)\n        }}\n      >\n        {/* Inside the root, because it reads the drawer's own store. It is what\n            publishes `--drawer-keyboard-inset` on the viewport, which is how\n            the footer stays above the software keyboard on a phone. */}\n        <Drawer.VirtualKeyboardProvider>\n          <Drawer.Portal>\n            {modal ? (\n              <Drawer.Backdrop\n                data-slot=\"sheet-scrim\"\n                className={cn(\n                  \"fixed inset-0 z-50\",\n                  \"transition-opacity duration-(--opsin-duration-base) ease-opsin-standard\",\n                  \"data-starting-style:opacity-0 data-ending-style:opacity-0\",\n                )}\n              >\n                {/* The scrim rung, painted by the one component that knows how\n                    to paint a rung. Doing it here by hand would mean a second\n                    copy of the reduced-transparency and no-backdrop-filter\n                    fallbacks, and the copy is the one that would rot. It holds\n                    no content, so it is handed none — `null` is a legitimate\n                    `ReactNode` and this is the one place in the system that\n                    passes it. */}\n                <Surface rung=\"scrim\" className=\"size-full\">\n                  {null}\n                </Surface>\n              </Drawer.Backdrop>\n            ) : null}\n\n            {/* `pointer-events-none` so that a tap beside the sheet reaches the\n                scrim rather than this full-screen box, which is what makes\n                tap-to-dismiss work at all. Base UI's drag handlers live on this\n                element and still fire, because events from the popup bubble to\n                it regardless of what its own pointer-events say. */}\n            <Drawer.Viewport\n              className={cn(\n                \"pointer-events-none fixed inset-0 z-50 flex items-end justify-center\",\n                /* Present only while a software keyboard is up, and 0 otherwise.\n                   Padding on the viewport rather than a margin on the sheet, so\n                   the sheet's own max height shrinks with it and the footer is\n                   pushed up instead of being covered. */\n                \"pb-(--drawer-keyboard-inset,0px)\",\n              )}\n            >\n              <Drawer.Popup\n                data-slot=\"sheet-container\"\n                className={cn(\n                  \"pointer-events-auto flex w-full max-h-full flex-col overflow-hidden\",\n                  \"rounded-t-opsin-xl [corner-shape:var(--opsin-corner-shape)]\",\n                  RESTING_TRANSFORM,\n                  OFFSCREEN_TRANSFORM,\n                  SLIDE,\n                  FOCUS_RING,\n                  /* A sheet with snap points has to be as tall as its tallest\n                     one, because a snap point is an offset from the popup's own\n                     height and cannot exceed it. A content-sized sheet must NOT\n                     be, or it would stop being content-sized. */\n                  snapPoints ? \"h-full\" : null,\n                  className,\n                )}\n              >\n                <Surface\n                  rung=\"sheet\"\n                  className={cn(\n                    SURFACE_LAYOUT,\n                    \"rounded-[inherit]\",\n                    /* Safe-area insets as padding INSIDE the surface, never as\n                       a margin outside it: the material has to reach the edge\n                       of the display, and only the content has to stay clear of\n                       the notch and the home indicator. */\n                    \"pb-(--opsin-safe-bottom) pl-(--opsin-safe-left) pr-(--opsin-safe-right)\",\n                  )}\n                >\n                  {canChangeDetent ? (\n                    /* THE GESTURE'S CONTROL, not an ornament. Drag-between-\n                       detents does not exist for a keyboard user, a switch\n                       user, or anybody whose grip makes a precise drag\n                       unreliable, and the page's rule is that every gesture\n                       has one. The grabber is the control: the same bar, at a\n                       44pt target, that says in words which height it moves\n                       to. */\n                    <button\n                      type=\"button\"\n                      data-slot=\"sheet-grabber\"\n                      onClick={() =>\n                        setStopIndex((current) => (current + 1) % stops.length)\n                      }\n                      className={cn(\n                        \"flex min-h-(--opsin-target-minimum) w-full shrink-0 items-center justify-center\",\n                        FOCUS_RING,\n                      )}\n                    >\n                      <span\n                        aria-hidden=\"true\"\n                        className=\"h-opsin-1 w-opsin-10 rounded-full bg-border\"\n                      />\n                      <span className=\"sr-only\">\n                        Change the sheet height to {DETENT_WORD[nextStop]}\n                      </span>\n                    </button>\n                  ) : (\n                    /* One detent, so there is nothing to move between and the\n                       bar is decorative. It stays because it is what tells a\n                       reader the sheet can be pulled down at all — and the\n                       control for THAT gesture is the close button below, which\n                       is why it is never optional. */\n                    <div\n                      data-slot=\"sheet-grabber\"\n                      aria-hidden=\"true\"\n                      className=\"flex shrink-0 items-center justify-center pt-opsin-2 pb-opsin-1\"\n                    >\n                      <span className=\"h-opsin-1 w-opsin-10 rounded-full bg-border\" />\n                    </div>\n                  )}\n\n                  <div\n                    data-slot=\"sheet-header\"\n                    className=\"flex shrink-0 items-start justify-between gap-opsin-4 px-opsin-5 pt-opsin-2 pb-opsin-2\"\n                  >\n                    {/* Renders an `<h2>`, and Base UI points the popup's\n                        `aria-labelledby` at it. The level is fixed because a\n                        modal surface starts its own outline; it is not part of\n                        the page's. */}\n                    <Drawer.Title\n                      data-slot=\"sheet-title\"\n                      className=\"m-0 text-opsin-title3\"\n                    >\n                      {title}\n                    </Drawer.Title>\n\n                    {/* ALWAYS PRESENT. It is the control for drag-to-dismiss,\n                        the only exit a keyboard or switch user has, and the one\n                        route `dismissible={false}` does not cancel. The word is\n                        visible rather than hidden behind the glyph: an icon\n                        with an invisible name is a control a voice-control user\n                        cannot say, and this system's readers are laypeople\n                        reading about their own health. */}\n                    <Drawer.Close\n                      data-slot=\"sheet-close\"\n                      className={cn(\n                        \"inline-flex min-h-(--opsin-target-minimum) shrink-0 items-center gap-opsin-1\",\n                        \"rounded-opsin-sm px-opsin-2 text-opsin-footnote text-muted-foreground\",\n                        \"hover:text-foreground\",\n                        FOCUS_RING,\n                      )}\n                    >\n                      <X aria-hidden=\"true\" className=\"size-[1em] shrink-0\" />\n                      Close\n                    </Drawer.Close>\n                  </div>\n\n                  {children}\n\n                  {footer ? (\n                    <div\n                      data-slot=\"sheet-footer\"\n                      className=\"flex shrink-0 flex-wrap items-center gap-opsin-2 border-t border-border px-opsin-5 pt-opsin-3 pb-opsin-3\"\n                    >\n                      {footer}\n                    </div>\n                  ) : null}\n                </Surface>\n              </Drawer.Popup>\n            </Drawer.Viewport>\n          </Drawer.Portal>\n        </Drawer.VirtualKeyboardProvider>\n      </Drawer.Root>\n    </SheetDepth.Provider>\n  )\n}\n\nexport interface SheetContentProps {\n  /** Everything that scrolls. */\n  children: ReactNode\n  /**\n   * Merged onto the scrolling region. The region's own classes win where they\n   * conflict, and the two that must not be overridden are the ones that make it\n   * a scroll boundary at all.\n   */\n  className?: string\n}\n\n/**\n * The scrolling region, and the one part of a Sheet that is a real export.\n *\n * It is an export because the consumer supplies its content and no prop could\n * carry it: a sheet may hold something above or below the scrolling area, and\n * only the caller knows which of the things they are putting in should move\n * when the rest does.\n *\n * It is also the element Base UI looks for. `Drawer.Content` stamps\n * `data-drawer-content`, and the drawer's own pointer handling treats a touch\n * that begins inside it as a scroll rather than a swipe. That is what stops a\n * flick at the top of a scrolled list from dismissing the sheet, and it is why\n * `overscroll-contain` sits beside it: one stops the sheet from being dragged,\n * the other stops the page behind from being scrolled.\n */\nexport function SheetContent({ children, className }: SheetContentProps) {\n  return (\n    <Drawer.Content\n      data-slot=\"sheet-content\"\n      className={cn(\n        \"min-h-0 flex-auto overflow-y-auto overscroll-contain px-opsin-5 py-opsin-2\",\n        className,\n      )}\n    >\n      {children}\n    </Drawer.Content>\n  )\n}\n\n/* Assigned after the declaration, never `Object.assign`: the assignment keeps\n   `Sheet.Content` and `SheetContent` the same function, and the declaration\n   keeps the name in a stack trace. */\nSheet.Content = SheetContent\n\n/**\n * The zero-prop default export (ADR 0009).\n *\n * `/view` renders this with no props and `shadcn add` ships it, so it is public,\n * reviewed code rather than a scratch demo. It shows the default sheet — one\n * content-sized detent, dismissible, modal — because that is the shape a\n * product reaches for first, and because the two things worth checking about it\n * are visible in that shape: the close control is in the header before you look\n * for it, and the action is pinned below the content rather than at the end of\n * it.\n *\n * There is not a number anywhere in it. A sheet renders no measurement of its\n * own, and a screenshot of an opsinjs demo must never be mistakable for\n * somebody's result.\n *\n * IT USES THE REAL `Button`, which is why `button` is in this component's\n * `registryDependencies` even though `Sheet` itself never imports it. A demo\n * that hand-rolled two controls would be teaching, in shipped source, that the\n * primary action at the foot of a sheet is a styled `<button>` — and it would\n * be teaching it in the one file a consumer reads first.\n */\nexport default function SheetDemo() {\n  const [open, setOpen] = useState(false)\n\n  return (\n    <div className=\"flex w-full flex-col items-center gap-opsin-4 p-opsin-4\">\n      <p className=\"m-0 max-w-sm text-center text-opsin-footnote text-muted-foreground\">\n        The sheet covers this frame while it is open. Close it with the button\n        in its header, with the escape key, or by tapping the dimmed area.\n      </p>\n\n      <Button onClick={() => setOpen(true)}>Open the example sheet</Button>\n\n      <Sheet\n        open={open}\n        onOpenChange={(nextOpen) => setOpen(nextOpen)}\n        title=\"An example sheet\"\n        footer={\n          <Button variant=\"primary\" fullWidth onClick={() => setOpen(false)}>\n            Save the example\n          </Button>\n        }\n      >\n        <Sheet.Content>\n          <p className=\"m-0 text-opsin-body\">\n            A sheet is a place the reader chose to go and can leave at any\n            moment. Everything in this paragraph is here to take up room, so\n            that the scrolling region has something to scroll.\n          </p>\n          <p className=\"mt-opsin-3 mb-0 text-opsin-body\">\n            The action below stays where it is while this text moves, which is\n            the whole reason it is a footer rather than the last thing in the\n            content.\n          </p>\n        </Sheet.Content>\n      </Sheet>\n    </div>\n  )\n}\n"

const SOURCE_BASES_BASE_STATUS_PILL = "/**\n * StatusPill — the level of attention something needs, as a word, an icon and a\n * colour together.\n *\n * NOT COMPOSABLE, AND THAT IS THE WHOLE DESIGN. There is no `StatusPill.Icon`\n * export, no `color` prop, no `variant` prop, and no way to remove the word.\n * The specification puts it plainly: \"every way of removing it that has ever\n * been offered has been used.\" The parts named in the anatomy are identified by\n * `data-slot`, which is enough to style them and not enough to take them apart.\n *\n * WHY THE WORD IS THE PRIMARY CARRIER, not a redundancy. The measured CVD audit\n * in `tokens/color.json` found that `steady` and `attention` are indistinguishable\n * under deuteranopia and in greyscale (Lc 0), and `steady` and `urgent` are\n * indistinguishable under tritanopia. Four ordered levels cannot be made mutually\n * distinguishable by hue alone. So the order of reliance is word, then glyph\n * shape, then colour — and the glyphs are four distinct silhouettes rather than\n * one glyph in four colours, for the same reason.\n *\n * StatusPill derives nothing. It has no thresholds, no ranges and no opinions:\n * `status` is assigned by the consuming product from a reference range or a\n * clinically reviewed threshold that the product owns.\n */\n\nimport { Check, Eye, OctagonAlert, TriangleAlert } from \"lucide-react\"\n\nimport {\n  CLINICAL_STATUS_META,\n  isClinicalStatus,\n  isDevelopment,\n  warnOnce,\n  type ClinicalStatus,\n} from \"@/lib/opsinjs\"\nimport { cn } from \"@/lib/utils\"\n\n/**\n * The glyph for each level.\n *\n * `CLINICAL_STATUS_META[level].icon` is the source of truth for WHICH lucide\n * icon a level uses; this map is the binding from that name to the component,\n * and it has to exist because a bundler cannot resolve `lucide-react`'s exports\n * from a runtime string without pulling the entire icon set into the bundle.\n * Typing it `Record<ClinicalStatus, …>` is what makes a missing level a compile\n * error rather than a pill with no icon, and the assertion below is what catches\n * the two drifting apart.\n */\nconst ICONS: Record<ClinicalStatus, typeof Check> = {\n  steady: Check,\n  watch: Eye,\n  attention: TriangleAlert,\n  urgent: OctagonAlert,\n}\n\n/* Development-only. If somebody changes an icon name in lib/status.ts and not\n   here, the pill keeps rendering a plausible glyph for the wrong level, which is\n   precisely the failure the four-distinct-shapes rule exists to prevent. */\nif (isDevelopment()) {\n  for (const [level, Icon] of Object.entries(ICONS)) {\n    const expected = CLINICAL_STATUS_META[level as ClinicalStatus].icon\n    const actual = (Icon as { displayName?: string }).displayName\n    if (actual && actual !== expected) {\n      /* Not an OPSIN code. Those describe a mistake a CONSUMER made with the\n         API; this is this file disagreeing with lib/status.ts, which is a defect\n         in opsinjs itself and belongs in a different channel. */\n      console.warn(\n        `[opsinjs] StatusPill renders <${actual}> for status \"${level}\", but ` +\n          `CLINICAL_STATUS_META says the icon is \"${expected}\". The four levels ` +\n          `must be four distinct glyph shapes; fix ICONS in status-pill.tsx.`,\n      )\n    }\n  }\n}\n\n/**\n * Tailwind reads class names out of source as literal strings, so these cannot\n * be built from the level at runtime — `bg-status-${status}-surface` generates\n * no CSS at all and the pill renders unstyled. Written out, once.\n *\n * Note which role does which job. `-surface` is the tinted background, `-ink` is\n * the text that is guaranteed legible on it, and the bare `-<level>` name is the\n * LINE role, which is the boundary. `-accent` is deliberately absent: it is the\n * identity fill, chosen for recognition rather than contrast, and it is never\n * text and never a sole boundary.\n */\nconst TONE: Record<ClinicalStatus, string> = {\n  steady: \"border-status-steady bg-status-steady-surface text-status-steady-ink\",\n  watch: \"border-status-watch bg-status-watch-surface text-status-watch-ink\",\n  attention:\n    \"border-status-attention bg-status-attention-surface text-status-attention-ink\",\n  urgent: \"border-status-urgent bg-status-urgent-surface text-status-urgent-ink\",\n}\n\nconst SIZE = {\n  sm: \"gap-opsin-1 px-opsin-2 py-opsin-0-5 text-opsin-caption1\",\n  md: \"gap-opsin-1 px-opsin-3 py-opsin-1 text-opsin-footnote\",\n} as const\n\nexport interface StatusPillProps {\n  /** Required. There is no neutral default and no \"unknown\" level. */\n  status: ClinicalStatus\n  /**\n   * Overrides the default word for this level — for translation, or for a\n   * product whose readers use different language. It may not change the\n   * meaning, and it may not be an empty string.\n   */\n  label?: string\n  /**\n   * Visual weight only. Both sizes render icon, word and colour; neither drops\n   * the word.\n   */\n  size?: \"sm\" | \"md\"\n  /**\n   * What the pill applies to, for the accessible name: \"HbA1c result\". Without\n   * it a screen-reader user hears a level with no subject.\n   */\n  describes?: string\n  /** Merged onto the root. The pill's own classes win where they conflict. */\n  className?: string\n}\n\nexport function StatusPill({\n  status,\n  label,\n  size = \"md\",\n  describes,\n  className,\n}: StatusPillProps) {\n  /* THE FIFTH LEVEL IS REFUSED, NOT APPROXIMATED.\n     `status` is typed to the four, and this file ships as source into JavaScript\n     projects where a type is advice. A value outside the vocabulary has no\n     entry in CLINICAL_STATUS_META and no glyph, so there is no honest pill to\n     draw — and drawing a plausible one would be the component inventing a\n     verdict about somebody's health, which is the single thing it exists not to\n     do. `unknown` gets its own code because it is the likeliest wrong answer\n     and the most dangerous: it is the absence of an assertion, and a reader who\n     sees it rendered as a level will read it as \"probably fine\". */\n  if (!isClinicalStatus(status)) {\n    warnOnce(status === \"unknown\" ? \"OPSIN-0011\" : \"OPSIN-0021\", {\n      component: \"StatusPill\",\n      status: String(status),\n    })\n    return null\n  }\n\n  const meta = CLINICAL_STATUS_META[status]\n  const Icon = ICONS[status]\n\n  /* OPSIN-0002, at its enforcement point. `label=\"\"` is the only way this\n     component can be made to render a status with no word, and the specification\n     forbids it in prose that the type cannot express. Falling back to the\n     level's own word is the honest repair: a coloured pill with no word is a\n     status carried by colour alone, which does not survive greyscale, colour\n     vision deficiency or a black-and-white printout. */\n  if (label !== undefined && label.trim() === \"\") {\n    warnOnce(\"OPSIN-0002\", { component: \"StatusPill\", status })\n  }\n  const word = label?.trim() ? label : meta.word\n\n  return (\n    <span\n      data-slot=\"status-pill\"\n      data-status={status}\n      className={cn(\n        /* `inline-flex` with `items-center` rather than a fixed height: at 200%\n           text the pill has to grow and wrap with the word, and a height would\n           truncate it. `whitespace-normal` is explicit for the same reason —\n           the word is never shortened to an ellipsis and never replaced by the\n           icon alone. */\n        \"inline-flex max-w-full items-center whitespace-normal rounded-full border align-middle\",\n        TONE[status],\n        SIZE[size],\n        className\n      )}\n    >\n      {/* Decorative. The word beside it carries the meaning, so announcing the\n          glyph as well would make a screen reader say the level twice. */}\n      <Icon\n        data-slot=\"status-pill-icon\"\n        aria-hidden=\"true\"\n        className=\"size-[1em] shrink-0\"\n      />\n      <span data-slot=\"status-pill-label\">{word}</span>\n      {/* The subject, for the accessible name only. A sighted reader sees\n          \"Needs attention\" next to the thing it describes; a screen-reader user\n          hears \"Needs attention, HbA1c result\" and does not have to hold a\n          floating level in their head until they reach whatever it applies to. */}\n      {describes ? <span className=\"sr-only\">, {describes}</span> : null}\n    </span>\n  )\n}\n\n/**\n * The zero-prop default export (ADR 0009).\n *\n * `/view` renders this with no props and `shadcn add` ships it, so it is public,\n * reviewed code rather than a scratch demo. It shows all four levels because the\n * one thing a reader needs to see about this component is that the four are\n * distinguishable without colour — which is also why the page's preview is worth\n * looking at in greyscale.\n *\n * The subjects are deliberately unreal (ADR 0012). No number, no unit, no\n * measurement anybody could mistake for their own.\n */\nexport default function StatusPillDemo() {\n  return (\n    <div className=\"flex flex-wrap items-center gap-opsin-3\">\n      <StatusPill status=\"steady\" describes=\"example measurement\" />\n      <StatusPill status=\"watch\" describes=\"example measurement\" />\n      <StatusPill status=\"attention\" describes=\"example measurement\" />\n      <StatusPill status=\"urgent\" describes=\"example measurement\" />\n      <StatusPill status=\"watch\" size=\"sm\" describes=\"example measurement\" />\n    </div>\n  )\n}\n"

const SOURCE_BASES_BASE_SURFACE = "/**\n * Surface — the material a layer is made of, and the promise that whatever sits\n * on it stays readable.\n *\n * THE RUNG NAMES ARE THE TOKEN NAMES (ADR 0014). `canvas`, `card`, `raised`,\n * `sheet`, `overlay`, `scrim`. Three documents named these six rungs three\n * different ways and the token source won, because it is the only one a\n * stylesheet resolves: every value below is a `--opsin-material-<rung>-*`\n * custom property emitted from `tokens/material.json`. The union this component\n * takes is imported from `@/lib/opsinjs` rather than declared here, so there is\n * one list and it is the list the CSS has.\n *\n * The trap in that renaming is worth stating before anybody translates an older\n * design file: `raised`, `sheet` and `overlay` appear in the retired vocabulary\n * AND in this one, and two of them mean a different depth. What the retired set\n * called `overlay` — covering the page while leaving it recognisable — is this\n * ladder's `sheet`; this ladder's `overlay` is chrome that content scrolls\n * beneath, a pinned toolbar or a tab bar. Mapping by ordinal lands a dismissible\n * sheet on the chrome rung and a tab bar on the sheet rung, and both compile.\n *\n * WHAT THIS COMPONENT ACTUALLY OWNS, given that the token layer already does\n * most of the work. `app/tokens.generated.css` emits a\n * `@media (prefers-reduced-transparency: reduce)` block for all six rungs that\n * swaps `-tint` to `-opaque`, forces `-tint-alpha` to 1 and drops `-blur` to 0,\n * deliberately leaving `-border`, `-shadow` and the geometry alone. So the\n * scrim needs no reduced-transparency handling from this file at all: it reads\n * the same two custom properties in both states and gets the right answer.\n *\n * The one thing a stylesheet cannot do is remove an element. A backdrop whose\n * filter has collapsed to `blur(0px) saturate(1)` is still a backdrop root: the\n * browser still snapshots what is behind it and still promotes the layer, on a\n * rung that has asked not to be composited at all. That is the part this\n * component owns, and it is why `Surface.Backdrop` is not rendered on an opaque\n * rung and is removed from the render under reduced transparency, under\n * increased contrast, and where `backdrop-filter` is unavailable.\n *\n * IT IS A SERVER COMPONENT, and that is a requirement rather than an\n * optimisation. Every state it has — reduced transparency, increased contrast,\n * no `backdrop-filter` — is a user preference or an engine capability, and each\n * one is answered by a media or support query in CSS. Reading any of them in\n * JavaScript would mean rendering the wrong material on the server and\n * correcting it after hydration, which is a visible flash of the wrong depth on\n * the surface a health value is sitting on.\n */\n\nimport type { CSSProperties, ReactNode } from \"react\"\n\nimport { isDevelopment, type MaterialRung } from \"@/lib/opsinjs\"\nimport { cn } from \"@/lib/utils\"\n\n/**\n * Which rungs composite what is behind them.\n *\n * This is the one structural fact about the ladder that lives in this file\n * rather than in the tokens, and it is here because it decides whether an\n * ELEMENT exists — a decision CSS cannot express from a custom property's\n * value. Everything else about a rung (its tint, alpha, blur, saturation,\n * border and shadow) is read through `var()` and is never copied here.\n *\n * `Record<MaterialRung, boolean>` on purpose: adding a rung to the union\n * without answering this question is a compile error rather than a surface that\n * silently renders with no backdrop. The drift this cannot catch is a rung that\n * changes its mind — if `tokens/material.json` flipped `raised` to\n * `translucent: true`, this file would keep it opaque and the rung would render\n * its tint with no blur behind it. That shows up as a flat panel where a\n * frosted one was expected, and the fix is one line here.\n */\nconst TRANSLUCENT: Record<MaterialRung, boolean> = {\n  canvas: false,\n  card: false,\n  raised: false,\n  sheet: true,\n  overlay: true,\n  scrim: true,\n}\n\n/**\n * The three rung names that exist only in the retired vocabulary, and the rung\n * each one meant, matched by JOB rather than by position on the ladder.\n *\n * Only three of the six can be caught here. `raised`, `sheet` and `overlay` are\n * spelled the same in both vocabularies, so a component cannot tell a caller\n * who meant this ladder from one who meant the other — which is exactly why the\n * page says a search-and-replace is not a safe translation.\n */\nconst RENAMED_RUNGS: Record<string, MaterialRung> = {\n  base: \"canvas\",\n  panel: \"card\",\n  chrome: \"overlay\",\n}\n\n/**\n * This file ships as source into JavaScript projects, where the union is\n * advice. A rung outside the six resolves no tokens at all, so there is no\n * material to draw and no honest guess to make.\n */\nfunction isMaterialRung(value: unknown): value is MaterialRung {\n  return typeof value === \"string\" && Object.hasOwn(TRANSLUCENT, value)\n}\n\n/**\n * The opacity the scrim has to reach for this rung, as a CSS expression over\n * the rung's own tokens.\n *\n * `max()` rather than either token alone, and the reason is the whole point of\n * the part. `-tint-alpha` is how the rung wants to look; `-scrim` is the\n * minimum opacity `tokens/material.json` publishes for it. They are equal for\n * every rung today, so the expression is currently a no-op — but the day\n * somebody lightens a tint for a design review, the floor is what stops the\n * change reaching a reader. That is what \"the scrim cannot be removed by any\n * prop\" means in code: there is no prop, and there is also no token value, that\n * takes this below the published floor.\n */\nfunction publishedScrimFloor(rung: MaterialRung): string {\n  return `max(var(--opsin-material-${rung}-tint-alpha), var(--opsin-material-${rung}-scrim))`\n}\n\n/**\n * The floor each content weight has to clear.\n *\n * BOTH ENTRIES ARE THE SAME EXPRESSION, and that is the finding rather than an\n * oversight. `tokens/material.json` publishes one `minScrimOpacity` per rung and\n * measures it against that rung's opaque fallback, which is the worst case for\n * text on it. There is no second, thinner floor for large text anywhere in the\n * token source, and a component is not allowed to invent one: a number that\n * decides whether somebody can read their own result is measured or it does not\n * exist. So `contentWeight=\"large\"` is accepted, is honoured as a promise about\n * the content, and takes the body floor until a large-text floor is published.\n * A surface that is more readable than it needs to be is not a defect; the\n * other direction is.\n */\nconst SCRIM_FLOOR: Record<\"body\" | \"large\", (rung: MaterialRung) => string> = {\n  body: publishedScrimFloor,\n  large: publishedScrimFloor,\n}\n\n/**\n * The custom properties the root sets and the three decorative layers read.\n *\n * They exist so that every conditional state is a CSS declaration on the layer\n * that needs it rather than a branch in JavaScript. The layers set their\n * regular properties through `style`, and the variants below override these\n * custom properties with a class — a declaration on the element always beats an\n * inherited value, so the two never fight, and an inline `style` never has to\n * lose to a class it cannot see.\n *\n * They are internal plumbing, not a public theming API. Restyle a Surface\n * through its `data-slot` parts or through the `--opsin-material-*` tokens,\n * which are versioned; these names are not.\n */\ninterface SurfaceStyle extends CSSProperties {\n  \"--opsinjs-surface-tint\": string\n  \"--opsinjs-surface-opaque\": string\n  \"--opsinjs-surface-alpha\": string\n  \"--opsinjs-surface-blur\": string\n  \"--opsinjs-surface-saturation\": string\n  \"--opsinjs-surface-edge\": string\n  \"--opsinjs-surface-edge-width\": string\n}\n\n/**\n * The filter, written once and used twice. Safari carried `backdrop-filter`\n * behind the `-webkit-` prefix until version 18, and the tested floor for this\n * system is Safari 16.4 — so the prefixed spelling is not legacy politeness,\n * it is the difference between a blurred sheet and an opaque one for readers on\n * a phone they have not replaced.\n */\nconst BACKDROP_FILTER =\n  \"blur(var(--opsinjs-surface-blur)) saturate(var(--opsinjs-surface-saturation))\"\n\nexport interface SurfaceProps {\n  /**\n   * Which rung of the material ladder. Required: there is no sensible default\n   * depth, and a component that guessed would put a surface at the wrong height\n   * silently. The names are the token names — `canvas`, `card`, `raised`,\n   * `sheet`, `overlay`, `scrim`.\n   */\n  rung: MaterialRung\n  /**\n   * Whether content on this surface has to clear the floor for body text or\n   * only for large text. Defaults to `\"body\"`, which is the stricter of the\n   * two. Both take the published floor today, because the token source measures\n   * one floor per rung.\n   */\n  contentWeight?: \"body\" | \"large\"\n  /**\n   * Renders the rung's opaque fallback regardless of engine or preference — the\n   * path for print and export, where there is no backdrop to see through and a\n   * translucent tint composites against paper.\n   */\n  opaque?: boolean\n  /**\n   * Merged onto the root. Shape belongs here: Surface sets no corner of its\n   * own, and every layer inside it inherits whatever radius the caller applies.\n   */\n  className?: string\n  /** Everything the surface holds. */\n  children: ReactNode\n}\n\nexport function Surface({\n  rung,\n  contentWeight = \"body\",\n  opaque = false,\n  className,\n  children,\n}: SurfaceProps) {\n  if (!isMaterialRung(rung)) {\n    /* Not an OPSIN code. `tokens/errors.json` has no entry for a material rung\n       outside the six, and a component may not mint one — the table is\n       generated from that file and the codes are a versioned contract. A plain\n       development warning is the honest channel until OPSIN-0022 exists.\n\n       The content still renders. StatusPill returns null for a status outside\n       its four because a pill with no level asserts nothing; a Surface with no\n       material is a different case entirely — it is a presentational wrapper,\n       and dropping it would take a reader's own readings off the screen to\n       report a styling mistake. So the material is omitted, visibly, and the\n       content is left where it was. */\n    if (isDevelopment()) {\n      const suggestion = RENAMED_RUNGS[String(rung)]\n      console.warn(\n        `[opsinjs] <Surface> received rung=\"${String(rung)}\", which is not one of ` +\n          \"canvas, card, raised, sheet, overlay, scrim. \" +\n          (suggestion === undefined\n            ? \"No material was applied.\"\n            : `That name is from the retired vocabulary; the rung that does that ` +\n              `job is now \"${suggestion}\". Map the old names by job, never by ` +\n              `position: the retired \"overlay\" is this ladder's \"sheet\". `) +\n          \"See /docs/project/decisions/0014-material-rung-names.\",\n      )\n    }\n    return (\n      <div data-slot=\"surface\" className={cn(\"relative\", className)}>\n        <div data-slot=\"surface-content\" className=\"relative\">\n          {children}\n        </div>\n      </div>\n    )\n  }\n\n  const style: SurfaceStyle = {\n    \"--opsinjs-surface-tint\": opaque\n      ? `var(--opsin-material-${rung}-opaque)`\n      : `var(--opsin-material-${rung}-tint)`,\n    \"--opsinjs-surface-opaque\": `var(--opsin-material-${rung}-opaque)`,\n    \"--opsinjs-surface-alpha\": opaque ? \"1\" : SCRIM_FLOOR[contentWeight](rung),\n    \"--opsinjs-surface-blur\": `var(--opsin-material-${rung}-blur)`,\n    \"--opsinjs-surface-saturation\": `var(--opsin-material-${rung}-saturation)`,\n    \"--opsinjs-surface-edge\": `var(--opsin-material-${rung}-border)`,\n    \"--opsinjs-surface-edge-width\": \"var(--opsin-border-hairline)\",\n    /* The rung's drop shadow, which is a `<shadow>` or the keyword `none` in\n       every rung's token, so it can be handed straight to the property. The\n       reduced-transparency block deliberately leaves it alone: once the\n       translucency is gone, the shadow and the edge are what is left to say\n       which layer is on top. */\n    boxShadow: `var(--opsin-material-${rung}-shadow)`,\n  }\n\n  return (\n    /* `relative` and nothing else. NOT `isolate`, and this is the one line in\n       the file most likely to be \"tidied up\" into a bug: `isolation: isolate`\n       creates a backdrop root, and a backdrop root is the boundary a\n       `backdrop-filter` is allowed to see behind. Isolate the root and the\n       backdrop blurs the inside of the surface instead of the page underneath\n       it, which looks like nothing happening at all. Painting order does the\n       job on its own — all four layers are positioned with `z-index: auto`, so\n       they paint in document order and the content is last. */\n    <div data-slot=\"surface\" style={style} className={cn(\"relative\", className)}>\n      {opaque || !TRANSLUCENT[rung] ? null : (\n        <div\n          data-slot=\"surface-backdrop\"\n          aria-hidden=\"true\"\n          className={cn(\n            \"pointer-events-none absolute inset-0 rounded-[inherit]\",\n            /* Absent, not neutralised. The token layer has already collapsed\n               the blur to 0 under this query; what it cannot do is stop the\n               element being a backdrop root, so this is the component's half of\n               the same answer. `display: none` leaves the node in the DOM and\n               removes it from the render, which is as close to absent as a\n               server component gets without shipping a media-query listener and\n               a hydration flash to a reader who asked for less. */\n            \"[@media(prefers-reduced-transparency:reduce)]:hidden\",\n            /* accessibility/increased-contrast names four things\n               `prefers-contrast: more` will do, and the fourth is \"disable\n               translucency and blur, by reusing the reduced-transparency\n               degradation\". This is that, for this component. High contrast and\n               frosted glass are incompatible requests. */\n            \"contrast-more:hidden\",\n            /* The `@supports` fallback and the reduced-transparency fallback are\n               the same fallback on purpose (tokens/material.json), which is what\n               makes the degraded path the one that gets exercised by real\n               readers rather than only by an old engine nobody has. Both\n               spellings are tested because Safari carried only the prefixed one\n               until 18 and the tested floor is 16.4. */\n            \"[@supports_not_((backdrop-filter:blur(1px))_or_(-webkit-backdrop-filter:blur(1px)))]:hidden\",\n          )}\n          style={{\n            backdropFilter: BACKDROP_FILTER,\n            WebkitBackdropFilter: BACKDROP_FILTER,\n          }}\n        />\n      )}\n      {/* The scrim is what makes translucency safe, so it is not conditional on\n          anything: every rung has one, at the published floor, and no prop\n          reaches it. On an opaque rung it is simply the surface's fill. */}\n      <div\n        data-slot=\"surface-scrim\"\n        aria-hidden=\"true\"\n        className={cn(\n          \"pointer-events-none absolute inset-0 rounded-[inherit]\",\n          /* Where the backdrop is gone, the tint has to stop being a tint. The\n             reduced-transparency case needs no class here because the tokens\n             already swap `-tint` for `-opaque` and force the alpha to 1; these\n             two cases are the ones no stylesheet in the system covers. */\n          \"contrast-more:[--opsinjs-surface-tint:var(--opsinjs-surface-opaque)] contrast-more:[--opsinjs-surface-alpha:1]\",\n          \"[@supports_not_((backdrop-filter:blur(1px))_or_(-webkit-backdrop-filter:blur(1px)))]:[--opsinjs-surface-tint:var(--opsinjs-surface-opaque)]\",\n          \"[@supports_not_((backdrop-filter:blur(1px))_or_(-webkit-backdrop-filter:blur(1px)))]:[--opsinjs-surface-alpha:1]\",\n        )}\n        style={{\n          backgroundColor: \"var(--opsinjs-surface-tint)\",\n          opacity: \"var(--opsinjs-surface-alpha)\",\n        }}\n      />\n      {/* An inset ring rather than a border, and the reason is a feature of the\n          token layer rather than a preference. `--opsin-material-canvas-border`\n          and `--opsin-material-scrim-border` are the keyword `none`, because\n          those two rungs have no edge. Substituted into `border-color` that is\n          invalid at computed-value time and the property falls back to\n          `currentColor`, which draws a hairline in the text colour around the\n          page background. Substituted into `box-shadow` it is invalid in the\n          same way, and `box-shadow` falls back to its initial value, which is\n          `none` — the right answer, arrived at by the CSS engine, with no table\n          of which rungs have an edge for anybody to keep up to date. */}\n      <div\n        data-slot=\"surface-edge\"\n        aria-hidden=\"true\"\n        className={cn(\n          \"pointer-events-none absolute inset-0 rounded-[inherit]\",\n          /* \"Make every border explicit\" is the second of the four things\n             increased contrast is specified to do. On a rung whose border token\n             is `none` there is no edge to strengthen, and inventing one would\n             be this component overruling the ladder. */\n          \"contrast-more:[--opsinjs-surface-edge-width:var(--opsin-border-emphasis)]\",\n        )}\n        style={{\n          boxShadow:\n            \"inset 0 0 0 var(--opsinjs-surface-edge-width) var(--opsinjs-surface-edge)\",\n        }}\n      />\n      {/* `relative` so the content joins the other three in the positioned\n          painting step and, being last in document order, paints above them.\n          No padding: spacing is the composing component's decision, and a\n          Surface that padded itself would make every Card fight it. */}\n      <div data-slot=\"surface-content\" className=\"relative\">\n        {children}\n      </div>\n    </div>\n  )\n}\n\n/**\n * The five content rungs, in ladder order. `scrim` is handled separately below\n * because it is the one rung that is not a place to put anything.\n */\nconst CONTENT_RUNGS = [\n  { rung: \"canvas\", label: \"Canvas\", job: \"The page itself.\" },\n  { rung: \"card\", label: \"Card\", job: \"A distinct block of content on the page.\" },\n  { rung: \"raised\", label: \"Raised\", job: \"Above the page, but not covering it.\" },\n  { rung: \"sheet\", label: \"Sheet\", job: \"Covering the page, which stays recognisable.\" },\n  { rung: \"overlay\", label: \"Overlay\", job: \"Chrome that content scrolls beneath.\" },\n] as const\n\n/**\n * A backdrop chosen to be hard on a translucent surface rather than kind to it.\n *\n * Four tones with the page's darkest and lightest among them, so a rung that\n * only holds its floor over a tasteful photograph fails here in review instead\n * of on somebody's phone. It is decorative and carries no meaning, which is why\n * it takes surface roles and never a category or status colour: those two axes\n * say what a reading is about and how urgent it is, and neither is available\n * for wallpaper.\n */\nconst BACKDROP_TILES = [\n  \"bg-foreground\",\n  \"bg-background\",\n  \"bg-primary\",\n  \"bg-muted\",\n  \"bg-background\",\n  \"bg-foreground\",\n  \"bg-muted\",\n  \"bg-primary\",\n  \"bg-primary\",\n  \"bg-muted\",\n  \"bg-foreground\",\n  \"bg-background\",\n] as const\n\n/**\n * The zero-prop default export (ADR 0009).\n *\n * `/view` renders this with no props and `shadcn add` ships it, so it is public,\n * reviewed code. It shows the whole ladder over a deliberately hostile backdrop\n * because the only claim this component makes is that content on it stays\n * readable, and that claim is worth nothing demonstrated over a flat grey.\n *\n * There is not a number anywhere in it. Surface renders no measurement, so\n * there is no reading here for anybody to mistake for their own.\n *\n * Every line of text in it takes the plain foreground role rather than the\n * muted one, deliberately: this page's own guidance says not to put small grey\n * captions on a blurred surface, and a demo that broke its own rule would be\n * the more persuasive of the two documents.\n */\nexport default function SurfaceDemo() {\n  return (\n    <div className=\"relative w-full max-w-lg overflow-hidden rounded-opsin-lg\">\n      <div\n        aria-hidden=\"true\"\n        className=\"absolute inset-0 grid grid-cols-4 grid-rows-3\"\n      >\n        {BACKDROP_TILES.map((tone, index) => (\n          <div key={`${tone}-${index}`} className={tone} />\n        ))}\n      </div>\n\n      <div className=\"relative grid gap-opsin-3 p-opsin-4 sm:grid-cols-2\">\n        {CONTENT_RUNGS.map((entry) => (\n          <Surface\n            key={entry.rung}\n            rung={entry.rung}\n            className=\"rounded-opsin-md\"\n          >\n            <div className=\"p-opsin-3\">\n              <p className=\"m-0 text-opsin-headline\">{entry.label}</p>\n              <p className=\"m-0 text-opsin-footnote\">\n                {entry.job}\n              </p>\n            </div>\n          </Surface>\n        ))}\n\n        {/* The scrim doing its actual job. Its use is to take the page out of\n            consideration, so the honest way to show it is with something on a\n            rung above it — never with text on the scrim itself. */}\n        <Surface rung=\"scrim\" className=\"rounded-opsin-md\">\n          <div className=\"p-opsin-3\">\n            <Surface rung=\"card\" className=\"rounded-opsin-sm\">\n              <div className=\"p-opsin-2\">\n                <p className=\"m-0 text-opsin-headline\">Scrim</p>\n                <p className=\"m-0 text-opsin-footnote\">\n                  The dimming layer behind a modal. Content sits on a rung above\n                  it.\n                </p>\n              </div>\n            </Surface>\n          </div>\n        </Surface>\n      </div>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_BUTTON_BUSY_AT_THE_FOOT_OF_A_FORM = "/**\n * The busy state, where it actually happens: the submit control at the foot of\n * a form, mid-save, on a phone.\n *\n * Three things are worth watching here, and all three are the same decision\n * seen from different angles.\n *\n * THE LABEL DOES NOT CHANGE. It still says \"Save reading\" while it saves. The\n * common alternative — swapping the label for a spinner, or rewriting it to\n * \"Saving…\" — changes the control's width, jumps the layout under the reader's\n * thumb, and makes its accessible name disappear and reappear. The reader's\n * record of what they pressed is the label; it stays put.\n *\n * THE BUTTON DOES NOT DISAPPEAR. It is not `disabled`: it keeps its tab stop\n * and its place in the accessibility tree, and it is announced as busy and\n * unavailable rather than removed. A control that vanishes mid-save takes the\n * reader's place in the form with it.\n *\n * THE BUSY GLYPH TAKES THE ICON'S SEAT. Which is why the primary control here\n * has an icon in the first place: with one, the button does not change width\n * when it becomes busy. Without one, it grows by a glyph.\n *\n * `fullWidth` on the primary and not on the escape hatch beneath it is the\n * hierarchy again. Two full-width buttons stacked read as two primary actions,\n * and this form has one.\n */\n\nimport { ArrowRight } from \"lucide-react\"\n\nimport { Button } from \"@/registry/base-lyra/ui/button\"\n\nexport default function ButtonBusyAtTheFootOfAForm() {\n  return (\n    <div className=\"flex w-full max-w-xs flex-col gap-opsin-2\">\n      <Button variant=\"primary\" icon={<ArrowRight />} iconPosition=\"trailing\" busy fullWidth>\n        Save reading\n      </Button>\n      <Button variant=\"quiet\" fullWidth>\n        Cancel\n      </Button>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_BUTTON_ONE_PRIMARY_PER_SURFACE = "/**\n * The emphasis ladder, on one surface, doing the job it exists for.\n *\n * The rule this demonstrates is the one that is broken most often and costs the\n * most: ONE primary action per surface. Three filled buttons of equal weight\n * answer \"what should I do here?\" with a shrug, and a reader in a corridor with\n * one hand free does not have time to work it out. Everything that is not the\n * one action gets `secondary` or `quiet`.\n *\n * It is also the honest place to look at `destructive`, because opsinjs has no\n * destructive colour and does not borrow one from the clinical status axis. The\n * only differences between the outlined destructive control and the soft-filled\n * secondary one are the boundary weight and the words — which is why the label\n * here says what will be deleted rather than just \"Delete\".\n *\n * The row is spaced by `gap-opsin-2`, which is 0.5rem, which is exactly\n * `--opsin-target-separation`. Adjacent targets need that gap and a component\n * cannot enforce its neighbours' spacing, so the caller owns it — and this is\n * what owning it looks like.\n *\n * The reading is fictional and carries no number at all.\n */\n\nimport { Plus } from \"lucide-react\"\n\nimport { Button } from \"@/registry/base-lyra/ui/button\"\n\nexport default function ButtonOnePrimaryPerSurface() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-opsin-4\">\n      <p className=\"m-0 text-opsin-body text-muted-foreground\">\n        Example measurement, taken this morning.\n      </p>\n      <div className=\"flex flex-wrap items-center gap-opsin-2\">\n        <Button variant=\"primary\" icon={<Plus />}>\n          Add a reading\n        </Button>\n        <Button variant=\"secondary\">Edit this reading</Button>\n        <Button variant=\"quiet\">Cancel</Button>\n      </div>\n      <div className=\"flex flex-wrap items-center gap-opsin-2\">\n        <Button variant=\"destructive\">Delete this example reading</Button>\n      </div>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_CARD_AS_A_LINK = "/**\n * The whole card as one link, which is the only interactive shape a Card has.\n *\n * Three things are worth watching here, and none of them is visible in a\n * screenshot. Tab through: each card is ONE stop, not one per line, because the\n * card is a single control rather than a container full of them. Hover: the\n * title underlines, because a whole-card link with no affordance on its text\n * leaves a reader guessing which part of it is the link — the underline comes\n * from the root's `group` class and needs no prop. Focus: the ring is drawn\n * around the card's own corner, outside the material, so it stays visible on\n * every rung.\n *\n * The accessible name of a link card is its whole text content — Card sets no\n * `aria-label`, because it cannot know which part of a card is its name, and a\n * label that does not begin with the visible text breaks voice control. That is\n * why both lines in each card here are short: everything inside the link is\n * read out as the link.\n *\n * The rule this example exists to demonstrate by omission: there is not a\n * button inside any of these. A card that is a link may hold no other\n * interactive element. A reader cannot tell what tapping the gap between two\n * buttons will do, and a keyboard user reaches a control nested inside a\n * control — which is a DOM the browser is entitled to flatten in whatever way\n * it likes. If a card needs two actions, it is not a link.\n *\n * The rung is `raised` rather than the default `card`, following the decision\n * table on `choosing-a-layer`: a tappable card is an object, and an object may\n * look lifted. A card that is not tappable stays on the `card` rung, where\n * nothing is lifted and nothing looks it.\n */\n\nimport { Card } from \"@/registry/base-lyra/ui/card\"\n\n/* Fictional sections with no readings in them. A screenshot of an opsinjs\n   example must never be mistakable for somebody's own result, so there is no\n   number, no unit and no date anywhere in this file. */\nconst SECTIONS = [\n  {\n    title: \"First example section\",\n    description: \"What the reader will find after they tap it.\",\n    href: \"#first-example-section\",\n  },\n  {\n    title: \"Second example section\",\n    description: \"One line, and it stays one line at the compact density.\",\n    href: \"#second-example-section\",\n  },\n]\n\nexport default function CardAsALink() {\n  return (\n    <ul className=\"m-0 flex w-full max-w-sm list-none flex-col gap-opsin-4 p-0\">\n      {SECTIONS.map((section) => (\n        <li key={section.href}>\n          <Card rung=\"raised\" href={section.href}>\n            <Card.Header\n              title={<h3>{section.title}</h3>}\n              description={section.description}\n            />\n          </Card>\n        </li>\n      ))}\n    </ul>\n  )\n}\n"

const SOURCE_EXAMPLES_CARD_ON_A_SHEET = "/**\n * Cards inside a translucent layer, and the rule that keeps them readable.\n *\n * `choosing-a-layer` states it as N1: a translucent rung may never contain\n * another translucent rung. The sheet is the layer — it blurs the page and\n * leaves it recognisable underneath — and the cards on it stay on the `card`\n * rung, opaque and bounded by a line. Two stacked blurs cost twice as much,\n * composite against each other rather than against the page, and produce a\n * surface whose contrast floor nobody has measured, because the floor is\n * published per rung and not per stack.\n *\n * That is also why a health value never goes above `raised`. A number sitting\n * on the sheet itself would be a number over a moving backdrop; the same number\n * inside one of these cards is over an opaque fill, and the sheet's translucency\n * is doing its real job — telling the reader where they will return to.\n *\n * The backdrop is a grid of the page's own tones rather than a photograph,\n * chosen to be hard on the material rather than kind to it: a light tile and a\n * dark tile meet under the sheet, which is where a blur that only holds over a\n * flattering background gives itself away.\n */\n\nimport { Card } from \"@/registry/base-lyra/ui/card\"\nimport { Surface } from \"@/registry/base-lyra/ui/surface\"\n\nconst BACKDROP_TILES = [\n  \"bg-foreground\",\n  \"bg-background\",\n  \"bg-primary\",\n  \"bg-muted\",\n  \"bg-primary\",\n  \"bg-foreground\",\n  \"bg-background\",\n  \"bg-muted\",\n]\n\nconst SECTIONS = [\n  {\n    title: \"First example section\",\n    body: \"A card on the sheet, opaque, bounded by a line rather than a shadow.\",\n  },\n  {\n    title: \"Second example section\",\n    body: \"The same rung as the first. Nesting a rung here would be the second blur.\",\n  },\n]\n\nexport default function CardOnASheet() {\n  return (\n    <div className=\"relative w-full max-w-sm overflow-hidden rounded-opsin-lg\">\n      <div\n        aria-hidden=\"true\"\n        className=\"absolute inset-0 grid grid-cols-4 grid-rows-2\"\n      >\n        {BACKDROP_TILES.map((tone, index) => (\n          <div key={`${tone}-${index}`} className={tone} />\n        ))}\n      </div>\n\n      {/* One translucent surface, and everything on it is opaque. The count of\n          composited translucent layers on this example is exactly one, against\n          a budget of three. */}\n      <Surface rung=\"sheet\" className=\"relative mt-opsin-16 rounded-t-opsin-xl\">\n        <div className=\"flex flex-col gap-opsin-4 p-opsin-5\">\n          {SECTIONS.map((section) => (\n            <Card key={section.title}>\n              <Card.Header title={<h3>{section.title}</h3>} />\n              <Card.Body>\n                <p className=\"m-0 text-opsin-body\">{section.body}</p>\n              </Card.Body>\n            </Card>\n          ))}\n        </div>\n      </Surface>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_DIALOG_AN_ANSWER_IS_NEEDED = "\"use client\"\n\n/**\n * `severity=\"alert\"`, which is the form of this component that takes something\n * away and does not give it back until it is answered.\n *\n * FOUR EXITS CLOSE AT ONCE, and they close together or not at all. The role\n * becomes `alertdialog`, the close control is absent, a press on the scrim does\n * nothing, and Escape does not close it. That is one decision — the component\n * swaps Base UI's alert-dialog root in — rather than four props a later edit\n * could get three-quarters right.\n *\n * ESCAPE IS NOT SWALLOWED. Press it and focus moves to the last action, which a\n * keyboard reader sees and a screen-reader user hears. What the key does NOT do\n * is produce a sentence about needing an answer, because that sentence is about\n * this product's own two answers and opsinjs does not know what they mean. It\n * belongs in the description, which is why the component warns in development\n * when an alert dialog ships without one.\n *\n * WHY THIS QUESTION QUALIFIES AND ALMOST NONE DO. There is no state of the\n * world in which going away is a valid answer here: recording has to happen on\n * one device or the other, and dismissing the question would leave the product\n * guessing on the reader's behalf. Nearly every dialog a product reaches for\n * fails that test — the reader could carry on, or there is a safe default — and\n * for those the answer is `severity=\"default\"`, or an AlertBanner, which\n * announces without blocking anything.\n *\n * Neither action is destructive, so `initialFocus=\"safest\"` lands on the last\n * one only because something has to be first: here the order carries no risk,\n * and the labels do all the work.\n */\n\nimport { useState } from \"react\"\n\nimport { Button } from \"@/registry/base-lyra/ui/button\"\nimport { Dialog } from \"@/registry/base-lyra/ui/dialog\"\n\nexport default function DialogAnAnswerIsNeeded() {\n  const [open, setOpen] = useState(false)\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col items-start gap-opsin-4\">\n      <Button variant=\"secondary\" onClick={() => setOpen(true)}>\n        Open the alert dialog\n      </Button>\n\n      <Dialog\n        open={open}\n        onOpenChange={setOpen}\n        severity=\"alert\"\n        title=\"Which device should record your readings?\"\n        description=\"Readings can be recorded on one device at a time, and this account is set up on two. Choose one before you carry on — the other will stop recording, and nothing already saved is affected.\"\n        actions={\n          <>\n            <Button variant=\"secondary\" onClick={() => setOpen(false)}>\n              Use the other device\n            </Button>\n            <Button variant=\"primary\" onClick={() => setOpen(false)}>\n              Use this device\n            </Button>\n          </>\n        }\n      />\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_DIALOG_CONFIRMING_A_DELETION = "\"use client\"\n\n/**\n * The ordinary dialog, doing the only job it is entitled to: asking a question\n * whose answer cannot be guessed and cannot be undone.\n *\n * Three rules are visible here at once.\n *\n * THE TITLE IS THE QUESTION and the description is the consequence of each\n * answer. Neither is \"Are you sure?\", because a reader answering quickly has a\n * fifty per cent chance of being wrong when the buttons say OK and Cancel and\n * the question says nothing.\n *\n * THE ACTION THAT CHANGES SOMETHING COMES FIRST and the one that changes\n * nothing comes last, because `initialFocus=\"safest\"` lands on the last control\n * in the row. A stray Return key therefore keeps the reading. Reverse the order\n * and the same key destroys it — which is why the order is a rule and not a\n * preference.\n *\n * THE DESTRUCTIVE ACTION IS NOT CARRIED BY COLOUR. opsinjs has no destructive\n * role and does not borrow one from the clinical status axis, so what separates\n * *Delete reading* from *Keep it* is the boundary weight and, mostly, the\n * words. That is the reason its label names what will be deleted.\n *\n * There is no number anywhere in this example. Nothing on the screen could be\n * mistaken for somebody's own result.\n */\n\nimport { useState } from \"react\"\n\nimport { Button } from \"@/registry/base-lyra/ui/button\"\nimport { Dialog } from \"@/registry/base-lyra/ui/dialog\"\n\nexport default function DialogConfirmingADeletion() {\n  const [open, setOpen] = useState(false)\n\n  return (\n    <div className=\"flex w-full max-w-sm flex-col items-start gap-opsin-4\">\n      <p className=\"m-0 text-opsin-body text-muted-foreground\">\n        An example measurement, recorded by hand.\n      </p>\n\n      <Button variant=\"destructive\" onClick={() => setOpen(true)}>\n        Delete this reading\n      </Button>\n\n      <Dialog\n        open={open}\n        onOpenChange={setOpen}\n        title=\"Delete this reading?\"\n        description=\"It will be removed from your history and from any trends it appears in. There is no way to bring it back.\"\n        actions={\n          <>\n            <Button variant=\"destructive\" onClick={() => setOpen(false)}>\n              Delete reading\n            </Button>\n            <Button variant=\"primary\" onClick={() => setOpen(false)}>\n              Keep it\n            </Button>\n          </>\n        }\n      />\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_FIELD_ERROR_KEEPS_THE_HINT = "/**\n * The claim on the page that is easiest to state and hardest to hold: an error\n * appears IN ADDITION to the hint, never instead of it.\n *\n * The same field twice, before and after. Almost every hand-rolled form swaps\n * one for the other — the markup is simpler and the column is shorter — and the\n * result is that at the exact moment a reader has got something wrong, the\n * sentence that would have told them the right shape disappears. They are then\n * expected to work out the format from a message about the format being wrong.\n *\n * Nothing here is coloured. A mistyped date is not a clinical status, and the\n * red that means \"this reading needs a decision\" is not available to say \"check\n * that number\". The error is carried by a glyph, a heavier weight, the emphasis\n * border on the control and the words.\n */\n\nimport { Field } from \"@/registry/base-lyra/ui/field\"\n\nexport default function FieldErrorKeepsTheHint() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-opsin-8\">\n      <div className=\"flex flex-col gap-opsin-2\">\n        <p className=\"m-0 text-opsin-footnote text-muted-foreground\">Before</p>\n        <Field label=\"Example date\" hint=\"For example, 27 3 1985.\">\n          <Field.Control\n            name=\"before\"\n            inputMode=\"numeric\"\n            autoComplete=\"off\"\n            defaultValue=\"27 3 3985\"\n          />\n        </Field>\n      </div>\n\n      <div className=\"flex flex-col gap-opsin-2\">\n        <p className=\"m-0 text-opsin-footnote text-muted-foreground\">After</p>\n        <Field\n          label=\"Example date\"\n          hint=\"For example, 27 3 1985.\"\n          error=\"Enter a date in the past.\"\n        >\n          <Field.Control\n            name=\"after\"\n            inputMode=\"numeric\"\n            autoComplete=\"off\"\n            defaultValue=\"27 3 3985\"\n          />\n        </Field>\n      </div>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_FIELD_MARKING_THE_EXCEPTION = "/**\n * Mark the exception, not the rule.\n *\n * Four fields, three of them needed and one not, so the one that is optional is\n * the one that carries a marker. The reverse form — a marker on every field\n * except one — says the same thing four times and leaves the reader counting\n * asterisks to work out which field is the odd one.\n *\n * The sentence above the fields is doing real work and is not decoration. A\n * marker is only information if the reader knows what the unmarked state means,\n * and that is a claim about the whole form rather than about any one field, so\n * no Field can make it. It is the caller's line to write, which is why\n * `optionality` marks in words rather than shipping a symbol and a legend.\n *\n * `autoComplete` and `inputMode` are set here rather than by the component. The\n * right token depends on what is being asked for, and a component that guessed\n * would put somebody's postcode in a field asking for something else.\n */\n\nimport { Field } from \"@/registry/base-lyra/ui/field\"\n\nexport default function FieldMarkingTheException() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-opsin-5\">\n      <p className=\"m-0 text-opsin-body text-muted-foreground\">\n        We need all of these unless the field says otherwise.\n      </p>\n\n      <Field label=\"Example measurement\" hint=\"For example, 14.\">\n        <Field.Control\n          name=\"example-measurement\"\n          inputMode=\"decimal\"\n          autoComplete=\"off\"\n        />\n      </Field>\n\n      <Field label=\"Example date\" hint=\"For example, 27 3 1985.\">\n        <Field.Control\n          name=\"example-date\"\n          inputMode=\"numeric\"\n          autoComplete=\"off\"\n        />\n      </Field>\n\n      <Field label=\"Example time\" hint=\"For example, 9 15 in the morning.\">\n        <Field.Control name=\"example-time\" inputMode=\"numeric\" autoComplete=\"off\" />\n      </Field>\n\n      <Field\n        label=\"Example note\"\n        optionality=\"optional\"\n        hint=\"Anything you want to remember about this entry.\"\n      >\n        <Field.Control name=\"example-note\" autoComplete=\"off\" />\n      </Field>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_FIELD_WITH_ANOTHER_CONTROL = "/**\n * `Field.Control` is a real export, and this is the reason it has to be.\n *\n * Everywhere else in opsinjs a part is internal structure named by `data-slot`,\n * because the content arrives as a prop. A control cannot: it has a type, a\n * name, an `autocomplete` token, an `inputmode`, a value and a change handler,\n * and no single prop carries that. So the slot is a component — and `render`\n * puts the same generated id, the same `aria-describedby` and the same invalid\n * state onto an element opsinjs does not ship.\n *\n * A textarea and a select below. Both get the label relationship, both get the\n * hint in their description, and neither needed an id written by hand. The\n * point of the second one is that the wiring survives a control with its own\n * children.\n */\n\nimport { Field } from \"@/registry/base-lyra/ui/field\"\n\nexport default function FieldWithAnotherControl() {\n  return (\n    <div className=\"flex w-full max-w-md flex-col gap-opsin-6\">\n      <Field\n        label=\"Example note\"\n        optionality=\"optional\"\n        hint=\"A few words is plenty. There is no length this has to reach.\"\n      >\n        <Field.Control\n          render={<textarea rows={3} />}\n          name=\"example-note\"\n          autoComplete=\"off\"\n        />\n      </Field>\n\n      <Field\n        label=\"Example choice\"\n        hint=\"Pick whichever is closest. You can change it later.\"\n      >\n        <Field.Control render={<select />} name=\"example-choice\" defaultValue=\"\">\n          <option value=\"\">Choose one</option>\n          <option value=\"first\">First example option</option>\n          <option value=\"second\">Second example option</option>\n          <option value=\"third\">Third example option</option>\n        </Field.Control>\n      </Field>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_SHEET_A_FORM_THAT_STAYS_PUT = "\"use client\"\n\n/**\n * A sheet holding something a reader typed, and the three exits it closes.\n *\n * `dismissible={false}` is the whole example. With it, the scrim, the escape\n * key and a downward drag stop closing the sheet — the three routes that are\n * all reached by accident and all discard what somebody typed without asking.\n * The close control in the header is untouched, because that is the deliberate\n * one, and a modal surface with no way out is a trap rather than a safeguard.\n *\n * WHAT THIS EXAMPLE IS NOT SHOWING, and it matters. A form sheet in a real\n * product would not simply refuse the escape key: it would ask, and the sheet's\n * accessibility contract says the escape key and a tap on the background take\n * the same route to that question. This example takes the simpler of the two\n * paths so that the flag itself is legible. The other path is `dismissible`\n * left alone and the second argument to `onOpenChange` read — the `route` —\n * with the sheet held open while a confirmation is shown.\n *\n * The field is deliberately about nothing. It has a label, a hint and no\n * clinical meaning at all: a sheet is a container, and an example that put a\n * reading in it would be teaching the container by way of a measurement nobody\n * has reviewed.\n */\n\nimport { useState } from \"react\"\n\nimport { Button } from \"@/registry/base-lyra/ui/button\"\nimport { Field } from \"@/registry/base-lyra/ui/field\"\nimport { Sheet } from \"@/registry/base-lyra/ui/sheet\"\n\nexport default function SheetAFormThatStaysPut() {\n  const [open, setOpen] = useState(false)\n  const [lastRoute, setLastRoute] = useState<string | null>(null)\n\n  return (\n    <div className=\"flex w-full flex-col items-center gap-opsin-4 p-opsin-4\">\n      <p className=\"m-0 max-w-sm text-center text-opsin-footnote text-muted-foreground\">\n        Open it, then try the escape key or a tap on the dimmed area. Neither\n        closes it. The close control in the header does.\n      </p>\n\n      <Button onClick={() => setOpen(true)}>Open the example form</Button>\n\n      {lastRoute ? (\n        <p className=\"m-0 text-opsin-caption1 text-muted-foreground\">\n          Last route reported to the product: {lastRoute}\n        </p>\n      ) : null}\n\n      <Sheet\n        open={open}\n        dismissible={false}\n        title=\"An example form\"\n        onOpenChange={(nextOpen, route) => {\n          setLastRoute(route)\n          setOpen(nextOpen)\n        }}\n        footer={\n          <Button variant=\"primary\" fullWidth onClick={() => setOpen(false)}>\n            Save the example\n          </Button>\n        }\n      >\n        <Sheet.Content>\n          <Field\n            label=\"Example note\"\n            hint=\"Anything at all. Nothing here is stored.\"\n          >\n            <Field.Control name=\"example-note\" autoComplete=\"off\" />\n          </Field>\n\n          <p className=\"mt-opsin-4 mb-0 text-opsin-footnote text-muted-foreground\">\n            The action stays below this text rather than after it, so a\n            software keyboard cannot cover it and scrolling cannot lose it.\n          </p>\n        </Sheet.Content>\n      </Sheet>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_SHEET_TWO_DETENTS_AND_A_CONTROL = "\"use client\"\n\n/**\n * Two rest positions, and the control that reaches the second one without a\n * drag.\n *\n * THE RULE THIS DEMONSTRATES is the one that costs the most to hold: every\n * gesture has a control. Drag-between-detents does not exist for a keyboard\n * user, a switch user, or anybody whose grip makes a precise drag unreliable,\n * so the grabber is not decoration here — it is a real button with a real\n * accessible name that says which height it moves to next. Tab into the sheet\n * and press it: the sheet travels between half and full without a pointer ever\n * touching it.\n *\n * The rows are there to give the content something to scroll, and the scrolling\n * is the second thing worth watching. A flick that starts inside\n * `Sheet.Content` scrolls the list; the same flick started on the header or the\n * grabber drags the sheet. That distinction is what stops a reader losing their\n * place every time they try to scroll a long list, and it is why the content is\n * wrapped rather than dropped in loose.\n *\n * Nothing in the list is a measurement. Twelve rows of a fictional label,\n * numbered so they can be told apart, and not one of them is a reading.\n */\n\nimport { useState } from \"react\"\n\nimport { Button } from \"@/registry/base-lyra/ui/button\"\nimport { Sheet } from \"@/registry/base-lyra/ui/sheet\"\n\nconst ROWS = Array.from({ length: 12 }, (unused, index) => ({\n  id: `row-${index + 1}`,\n  label: `Example item ${index + 1}`,\n}))\n\nexport default function SheetTwoDetentsAndAControl() {\n  const [open, setOpen] = useState(false)\n\n  return (\n    <div className=\"flex w-full flex-col items-center gap-opsin-4 p-opsin-4\">\n      <p className=\"m-0 max-w-sm text-center text-opsin-footnote text-muted-foreground\">\n        The sheet opens at half the screen. The bar at the top is a button:\n        press it, or tab to it and press Enter, to move to the full screen and\n        back.\n      </p>\n\n      <Button onClick={() => setOpen(true)}>Open the example list</Button>\n\n      <Sheet\n        open={open}\n        onOpenChange={(nextOpen) => setOpen(nextOpen)}\n        title=\"An example list\"\n        detents={[\"half\", \"full\"]}\n        footer={\n          <Button variant=\"quiet\" fullWidth onClick={() => setOpen(false)}>\n            Leave the example list\n          </Button>\n        }\n      >\n        <Sheet.Content>\n          <ul className=\"m-0 flex list-none flex-col p-0\">\n            {ROWS.map((row) => (\n              <li\n                key={row.id}\n                className=\"border-b border-border py-opsin-3 text-opsin-body last:border-b-0\"\n              >\n                {row.label}\n              </li>\n            ))}\n          </ul>\n        </Sheet.Content>\n      </Sheet>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_STATUS_PILL_IN_A_LIST = "/**\n * The primary use: making status scannable down a column.\n *\n * The rule this demonstrates is the escalation budget. Four rows, and exactly\n * one of them is `urgent` — because a screen with two urgent pills is a screen\n * that has taught its reader that red means nothing, and that lesson does not\n * wear off. If a product's own rules produce two, the screen needs an\n * AlertBanner about the more serious one, not a second pill.\n *\n * The measurements are deliberately fictional and carry no numbers at all. A\n * screenshot of an opsinjs example must never be mistakable for somebody's\n * result.\n */\n\nimport { StatusPill } from \"@/registry/base-lyra/ui/status-pill\"\n\nconst ROWS = [\n  { subject: \"First example measurement\", status: \"steady\" },\n  { subject: \"Second example measurement\", status: \"watch\" },\n  { subject: \"Third example measurement\", status: \"attention\" },\n  { subject: \"Fourth example measurement\", status: \"urgent\" },\n] as const\n\nexport default function StatusPillInAList() {\n  return (\n    <ul className=\"m-0 flex w-full max-w-md list-none flex-col gap-opsin-2 p-0\">\n      {ROWS.map((row) => (\n        <li\n          key={row.subject}\n          className=\"flex items-center justify-between gap-opsin-4 border-b border-border py-opsin-2 text-opsin-body\"\n        >\n          <span>{row.subject}</span>\n          <StatusPill status={row.status} describes={row.subject} />\n        </li>\n      ))}\n    </ul>\n  )\n}\n"

const SOURCE_EXAMPLES_STATUS_PILL_SIZES = "/**\n * Both sizes, side by side, because the interesting thing about `size` is what\n * it does NOT change.\n *\n * `sm` is visual weight and nothing else. It does not drop the word, it does not\n * drop the icon, and there is no size at which a pill becomes a coloured dot —\n * which is the request this prop exists to refuse. A dot in a dense table is a\n * status carried by colour alone, and the measured CVD audit says that is\n * unreadable for a real share of readers whatever hue it is.\n *\n * If a pill will not fit, the row is too narrow for a status, not too narrow for\n * a word.\n */\n\nimport { StatusPill } from \"@/registry/base-lyra/ui/status-pill\"\n\nexport default function StatusPillSizes() {\n  return (\n    <div className=\"flex flex-col gap-opsin-4\">\n      <div className=\"flex flex-wrap items-center gap-opsin-3\">\n        <span className=\"text-opsin-caption1 text-muted-foreground\">md</span>\n        <StatusPill status=\"watch\" describes=\"example measurement\" />\n        <StatusPill status=\"attention\" describes=\"example measurement\" />\n      </div>\n      <div className=\"flex flex-wrap items-center gap-opsin-3\">\n        <span className=\"text-opsin-caption1 text-muted-foreground\">sm</span>\n        <StatusPill status=\"watch\" size=\"sm\" describes=\"example measurement\" />\n        <StatusPill status=\"attention\" size=\"sm\" describes=\"example measurement\" />\n      </div>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_SURFACE_OPAQUE_FALLBACK = "/**\n * The degraded path, made visible without changing an operating-system setting.\n *\n * Three different conditions end at the same surface: a reader who has switched\n * on Reduce Transparency, a reader who has asked for more contrast, and an\n * engine with no `backdrop-filter`. `tokens/material.json` makes them one\n * fallback on purpose, so that the degraded route is exercised every day by\n * real people rather than only by an old browser nobody tests on.\n *\n * `opaque` is the fourth way in, and it is the one a designer can look at. It\n * takes the same rung to the same opaque fallback for print and export paths —\n * which makes it the cheapest possible review of a claim that would otherwise\n * need a device with the preference set. The two panels below are the same\n * rung, the same content and the same floor; the only thing that differs is\n * whether the backdrop exists.\n *\n * Look at what does NOT change. The border, the shadow and the geometry are\n * identical, because they are what carries the layering once the translucency\n * is gone. A fallback that flattened the ladder would answer the preference by\n * throwing away the information the ladder was there to convey.\n */\n\nimport { Surface } from \"@/registry/base-lyra/ui/surface\"\n\n/* Surface roles only. A backdrop is decoration, and the category and status\n   axes both mean something specific about a person's data; neither is\n   available as wallpaper. */\nconst BACKDROP_TILES = [\n  \"bg-foreground\",\n  \"bg-background\",\n  \"bg-primary\",\n  \"bg-muted\",\n  \"bg-background\",\n  \"bg-foreground\",\n  \"bg-muted\",\n  \"bg-primary\",\n]\n\nexport default function SurfaceOpaqueFallback() {\n  return (\n    <div className=\"relative w-full max-w-lg overflow-hidden rounded-opsin-lg\">\n      <div\n        aria-hidden=\"true\"\n        className=\"absolute inset-0 grid grid-cols-4 grid-rows-2\"\n      >\n        {BACKDROP_TILES.map((tone, index) => (\n          <div key={`${tone}-${index}`} className={tone} />\n        ))}\n      </div>\n\n      <div className=\"relative grid gap-opsin-3 p-opsin-4 sm:grid-cols-2\">\n        <Surface rung=\"sheet\" className=\"rounded-opsin-md\">\n          <div className=\"p-opsin-3\">\n            <p className=\"m-0 text-opsin-headline\">Sheet rung</p>\n            <p className=\"m-0 text-opsin-footnote\">\n              Translucent, with the page blurred behind it.\n            </p>\n          </div>\n        </Surface>\n\n        <Surface rung=\"sheet\" opaque className=\"rounded-opsin-md\">\n          <div className=\"p-opsin-3\">\n            <p className=\"m-0 text-opsin-headline\">Same rung, opaque</p>\n            <p className=\"m-0 text-opsin-footnote\">\n              What reduced transparency, increased contrast, a missing\n              backdrop-filter and a printout all produce.\n            </p>\n          </div>\n        </Surface>\n      </div>\n    </div>\n  )\n}\n"

const SOURCE_EXAMPLES_SURFACE_OVER_SCROLLING_CONTENT = "/**\n * The `overlay` rung doing the job it is named for.\n *\n * This is the rung most often reached for by mistake, because \"overlay\" sounds\n * like the thing that covers a page. On this ladder it is not: `overlay` is\n * chrome that content scrolls *beneath* — a pinned toolbar, a tab bar, a\n * floating action bar. The rung for a panel that covers the page is `sheet`.\n * The two names swapped meaning between the retired vocabulary and this one, so\n * an example that shows the job rather than the word is worth more than a\n * paragraph about it.\n *\n * It is also the rung whose contrast floor is hardest to hold, because it is\n * the thinnest material in the system and the content underneath is by\n * definition moving. Scroll the panel: the header's blur and its scrim are what\n * keep the heading legible while a light row and a dark row pass under it, and\n * neither is optional.\n */\n\nimport { Surface } from \"@/registry/base-lyra/ui/surface\"\n\n/* Deliberately contentless rows. This example is about a material, and a\n   screenshot of an opsinjs example must never be mistakable for somebody's own\n   readings — so there is no number, no unit and no date anywhere in it. */\nconst ROWS = [\n  \"First example row\",\n  \"Second example row\",\n  \"Third example row\",\n  \"Fourth example row\",\n  \"Fifth example row\",\n  \"Sixth example row\",\n  \"Seventh example row\",\n  \"Eighth example row\",\n  \"Ninth example row\",\n  \"Tenth example row\",\n]\n\nexport default function SurfaceOverScrollingContent() {\n  return (\n    <div className=\"h-80 w-full max-w-sm overflow-y-auto rounded-opsin-lg border border-border bg-background\">\n      {/* A direct child of the scroll container, so `top-0` sticks to it rather\n          than to the page. `z-10` puts it above the rows; it does not create a\n          backdrop root, so the blur still reaches the content passing under. */}\n      <Surface rung=\"overlay\" className=\"sticky top-0 z-10\">\n        <div className=\"px-opsin-4 py-opsin-3\">\n          <p className=\"m-0 text-opsin-headline\">Example section</p>\n        </div>\n      </Surface>\n\n      <ul className=\"m-0 flex list-none flex-col p-0\">\n        {ROWS.map((row) => (\n          <li\n            key={row}\n            className=\"border-b border-border px-opsin-4 py-opsin-3 text-opsin-body\"\n          >\n            {row}\n          </li>\n        ))}\n      </ul>\n    </div>\n  )\n}\n"

const SHARED_LIB_OPSINJS_TS = "/**\n * lib/opsinjs.ts — the shared substrate every opsinjs component imports.\n *\n * WHY THIS FILE EXISTS\n * A component under `registry/bases/<base>/` is distributed by `shadcn add`,\n * which copies source files into somebody else's project. Anything a component\n * imports has to travel with it or the copy will not compile, and a component\n * that compiles here and breaks there is worse than no component at all. So the\n * import surface of a registry file is exactly two modules: `@/lib/utils` for\n * `cn`, which `shadcn init` writes into every consumer, and this one, which\n * `scripts/build-registry.mts` appends to every component's `files[]` as a\n * `registry:lib` entry carrying real `content`. There is no third. Not\n * `@/components/*`, not `@/registry/*`, not `@/app/*`, not `@/tokens/*` — those\n * paths exist in this repository and nowhere else.\n *\n * `type: \"registry:lib\"` resolves through the consumer's `components.json`\n * `aliases.lib`, and shadcn 4.20 rewrites a `@/lib/...` import specifier to the\n * same alias, so `@/lib/opsinjs` names the same file in this repository and in a\n * project that installed from it. Nothing is rewritten by hand at either end.\n *\n * IT RE-EXPORTS AND IT NEVER RE-DECLARES. The clinical vocabulary lives in\n * `lib/status.ts`, which is the module the documentation chrome, the section\n * contracts and `assert-ia.mts` already read. A second copy of `CLINICAL_STATUSES`\n * here would be a second copy that can drift, and the two axes are the one thing\n * in this system that must never say two different things. `lib/status.ts` ships\n * beside this file for the same reason, as a second `registry:lib` entry.\n *\n * WHAT IS DECLARED HERE, AND WHY IT IS HERE RATHER THAN IN A COMPONENT\n * Only the shapes that more than one component has to agree on: a reference\n * range, a point on a trend, a sheet detent, a material rung, and the one string\n * every example is allowed to cite as its source. A shape used by exactly one\n * component belongs in that component's own file, because a type nobody else\n * consumes is not substrate, it is that component's API.\n *\n * CONSTRAINTS THIS FILE IS UNDER\n * No JSX and no non-erasable TypeScript — no `enum`, no parameter properties, no\n * `namespace` — and every relative import carries an explicit `.ts` extension,\n * because `scripts/*.mts` run under plain Node 24 with native type stripping and\n * some of them import `lib/` modules directly, with no resolver hook. The same\n * rule holds for `lib/status.ts`, `lib/catalogue.ts`, `lib/routes.ts` and\n * `registry/catalogue.ts`.\n *\n * `scripts/build-reference.mts` scans `lib/` and turns every exported type and\n * interface into a page under `content/docs/reference/api/`, taking the first\n * sentence of the doc comment directly above the declaration as the summary. The\n * comments below are therefore published documentation, not notes to the next\n * reader of the source.\n *\n * ONE REGION OF THIS FILE IS GENERATED. The `OPSIN_ERRORS` table between the\n * `opsinjs:errors` markers near the bottom is emitted from `tokens/errors.json`\n * by `scripts/build-tokens.mts`, and `pnpm run generate` replaces it wholesale.\n * Edit the JSON. Everything outside those two markers, including `warnOnce()`\n * itself, is hand-written and is left alone by the generator.\n *\n * It is generated INTO this file rather than into `lib/generated/` for the\n * reason the first paragraph gives: `lib/generated/` does not travel with\n * `shadcn add`, so `warnOnce()` importing the error table from there would\n * compile in this repository and fail in every project that installed a\n * component. The same table is also emitted into `lib/generated/tokens.ts` as\n * `OPSIN_ERROR_CODES` for the documentation site, which is not a second copy\n * anybody maintains: both are written by one script, from one source, in one\n * run, and `node scripts/build-tokens.mts --check` fails on either drifting.\n */\n\nimport type { ClinicalStatus } from \"./status\"\n\n/* ------------------------------------------------------------------ *\n * The clinical vocabulary, re-exported from lib/status.ts             *\n *                                                                     *\n * A component imports these from `@/lib/opsinjs` and never from       *\n * `@/lib/status` directly. Both files ship, so either specifier would  *\n * resolve in a consumer — but one import surface is what makes the     *\n * substrate reviewable, and it is the specifier every specification    *\n * page's `## Usage` block prints.                                      *\n * ------------------------------------------------------------------ */\n\nexport {\n  CLINICAL_STATUSES,\n  CLINICAL_STATUS_META,\n  HEALTH_CATEGORIES,\n  HEALTH_CATEGORY_LABELS,\n  isClinicalStatus,\n  isHealthCategory,\n  axisConflict,\n} from \"./status\"\n\nexport type {\n  ClinicalStatus,\n  UnknownStatus,\n  ClinicalStatusOrUnknown,\n  ClinicalStatusMeta,\n  HealthCategory,\n  AxisConflict,\n} from \"./status\"\n\n/* ------------------------------------------------------------------ *\n * Example data                                                        *\n * ------------------------------------------------------------------ */\n\n/**\n * The only citation an opsinjs example, demo or preview may carry.\n *\n * Every component ships a zero-prop default export that renders in the docs and\n * in a consumer's editor, and every one of those renders a measurement. A\n * plausible reference range in a demo is a reference range somebody will read as\n * theirs, so the demos cite this string instead — one literal, shared by all of\n * them, saying in the reader's own language that the numbers beside it mean\n * nothing. `ReferenceRange.source` in an example is always this and never a\n * laboratory, a guideline body, a device manufacturer or a study.\n */\nexport const EXAMPLE_SOURCE = \"Example data — not a reference range\"\n\n/* ------------------------------------------------------------------ *\n * Shapes more than one component agrees on                            *\n * ------------------------------------------------------------------ */\n\n/**\n * The interval a reading is being compared against, and who says so.\n *\n * Both bounds are optional because a one-sided range is a real range: some\n * measurements have a floor and no ceiling, and rendering a bound the product\n * did not supply would invent a threshold. An omitted bound renders as an open\n * end, never as zero and never as an assumed limit.\n *\n * `source` is required, and it is required because opsinjs does not own a single\n * clinical number. A range arriving with no attribution is the consuming\n * product asking this system to vouch for a threshold it has never seen, which\n * is the one thing it must not do; a component handed a range with no `source`\n * reports OPSIN-0004 rather than drawing it.\n */\nexport interface ReferenceRange {\n  /** Lower bound, in the reading's own unit. Omitted means the range is open below. */\n  low?: number\n  /** Upper bound, in the reading's own unit. Omitted means the range is open above. */\n  high?: number\n  /** Who this interval came from. Never opsinjs, and never omitted. */\n  source: string\n  /**\n   * When the range was published or last reviewed, ISO 8601. Omitted when the\n   * product does not know — which is rendered as \"we do not know\", never as\n   * today's date.\n   */\n  asOf?: string\n}\n\n/**\n * One reading in a series, for the components that draw change over time.\n *\n * `value` is `number | null` rather than `number` because a gap in a series is\n * information: a day with no reading is not a day with a reading of zero, and\n * charting it as zero invents a measurement. A `null` point is drawn as a break\n * in the line and described in words by the chart's text twin.\n *\n * `status` is optional and is an input, never a derivation. opsinjs does not\n * compare a point to a range and decide what it means, because it does not know\n * the reader; a point carries a verdict only when the consuming product attached\n * one.\n */\nexport interface TrendPoint {\n  /** When this reading was taken, ISO 8601. */\n  at: string\n  /** The reading, or `null` where there is no reading for this point. */\n  value: number | null\n  /** The verdict the product assigned to this point, if it assigned one. */\n  status?: ClinicalStatus\n}\n\n/**\n * How far a sheet is open.\n *\n * Three stops rather than a continuous height, because a sheet a reader can\n * leave at an arbitrary position is a sheet that will be left half over the\n * value it is explaining. `content` is as tall as what is inside it, `half` is\n * the resting stop that keeps the screen behind it readable, and `full` is the\n * whole surface.\n */\nexport type Detent = \"content\" | \"half\" | \"full\"\n\n/**\n * A rung of the material ladder — how a surface sits above what is behind it.\n *\n * These six names are the token names: every rung resolves a matching set of\n * `--opsin-material-<rung>-*` custom properties for blur, tint, shadow and\n * border. Where a specification page names a different set, the tokens win,\n * because the tokens are what actually renders.\n */\nexport type MaterialRung =\n  | \"canvas\"\n  | \"card\"\n  | \"raised\"\n  | \"sheet\"\n  | \"overlay\"\n  | \"scrim\"\n\n/* ------------------------------------------------------------------ *\n * The unit table is deliberately NOT here yet                         *\n *                                                                     *\n * `Unit` and `UNITS` — mmol/L and mg/dL, kg and lb and st, °C and °F,  *\n * and the spoken form of each — are Batch B's work, and they arrive as *\n * an authored `tokens/units.json` with an emitter, exactly like every  *\n * other token source. They do not arrive as a literal in a             *\n * component and they do not arrive as a hand-written table here: a     *\n * conversion factor somebody typed into a component file is a clinical *\n * number with no provenance, and this system does not own one of       *\n * those. Leave the space; do not fill it from memory.                  *\n * ------------------------------------------------------------------ */\n\n/* ------------------------------------------------------------------ *\n * Error codes — GENERATED from tokens/errors.json                     *\n *                                                                     *\n * Everything between the two markers below is written by              *\n * `scripts/build-tokens.mts`. An edit here survives until the next     *\n * `pnpm run generate` and no longer; the source is `tokens/errors.json`*\n * and the drift gate is `node scripts/build-tokens.mts --check`.       *\n * ------------------------------------------------------------------ */\n\n/* opsinjs:errors:begin — replaced by scripts/build-tokens.mts from tokens/errors.json */\n\n/**\n * How severe a warning is.\n *\n * The three classes are declared in `tokens/errors.json`'s `policy.severity`\n * block, which also carries the sentence that says what each one means:\n *   safety - A defect that can mislead a reader about their own health. Treat as a bug, not as a lint warning.\n *   correctness - The component will render something, but not what the author meant.\n *   hygiene - Works today, will not survive an upgrade.\n */\nexport type OpsinErrorSeverity = \"safety\" | \"correctness\" | \"hygiene\"\n\n/**\n * Every warning code opsinjs can emit.\n *\n * Flat, allocated in sequence, and permanent: a code is never reused, never\n * renumbered and never removed. The union is what makes `warnOnce(\"OPSIN-0004\")`\n * a compile error when the code does not exist, which is the difference between\n * a stable code and a string somebody typed.\n */\nexport type OpsinErrorCode =\n  | \"OPSIN-0001\"\n  | \"OPSIN-0002\"\n  | \"OPSIN-0003\"\n  | \"OPSIN-0004\"\n  | \"OPSIN-0005\"\n  | \"OPSIN-0006\"\n  | \"OPSIN-0007\"\n  | \"OPSIN-0008\"\n  | \"OPSIN-0009\"\n  | \"OPSIN-0010\"\n  | \"OPSIN-0011\"\n  | \"OPSIN-0012\"\n  | \"OPSIN-0013\"\n  | \"OPSIN-0014\"\n  | \"OPSIN-0015\"\n  | \"OPSIN-0016\"\n  | \"OPSIN-0017\"\n  | \"OPSIN-0018\"\n  | \"OPSIN-0019\"\n  | \"OPSIN-0020\"\n  | \"OPSIN-0021\"\n\n/** One warning code: what it is called, how severe it is, and the page that prevents it. */\nexport interface OpsinError {\n  /** The stable code. Search by this, never by the message text. */\n  code: OpsinErrorCode\n  severity: OpsinErrorSeverity\n  /** One line naming the mistake. */\n  title: string\n  /** The message template. `{name}` spans are filled from `warnOnce`'s `params`. */\n  message: string\n  /** The docs page id that prevents the mistake, without a leading slash. */\n  docs: string\n  /** The `{name}` spans in `message`, first appearance first. */\n  params: string[]\n}\n\n/** The table `warnOnce()` reads. Generated from `tokens/errors.json`. */\nexport const OPSIN_ERRORS: Record<OpsinErrorCode, OpsinError> = {\n  \"OPSIN-0001\": {\n    code: \"OPSIN-0001\",\n    severity: \"safety\",\n    title: \"Both a category and a status were given to one surface\",\n    message: \"<{component}> received both `category=\\\"{category}\\\"` and `status=\\\"{status}\\\"`. A surface carries one axis. Set the category on the surface and render the status as a StatusPill inside it.\",\n    docs: \"health/two-colour-axes\",\n    params: [\"component\", \"category\", \"status\"],\n  },\n  \"OPSIN-0002\": {\n    code: \"OPSIN-0002\",\n    severity: \"safety\",\n    title: \"A status was rendered without a word\",\n    message: \"<{component}> has `status=\\\"{status}\\\"` and no accessible label. Status is carried by colour, icon and word together; colour alone does not survive grayscale, colour-vision deficiency or a black-and-white printout.\",\n    docs: \"health/clinical-status-semantics\",\n    params: [\"component\", \"status\"],\n  },\n  \"OPSIN-0003\": {\n    code: \"OPSIN-0003\",\n    severity: \"safety\",\n    title: \"A value was rendered without a unit\",\n    message: \"<Value> received `{value}` with no `unit`. A bare number in a health context is ambiguous between unit systems: the same digits are one reading in mmol/L and a very different one in mg/dL, and nothing on the surface tells the reader which was meant. Pass the unit the reading was measured in.\",\n    docs: \"health/unit-systems\",\n    params: [\"value\"],\n  },\n  \"OPSIN-0004\": {\n    code: \"OPSIN-0004\",\n    severity: \"safety\",\n    title: \"A reference range was rendered without a source\",\n    message: \"<{component}> was given a `range` with no `rangeSource`. Name whose range it is — a laboratory, a device maker, or a clinician — because a range is a comparison somebody chose and not a fact about the reader.\",\n    docs: \"health/reference-ranges\",\n    params: [\"component\"],\n  },\n  \"OPSIN-0005\": {\n    code: \"OPSIN-0005\",\n    severity: \"safety\",\n    title: \"More than one urgent surface on a screen\",\n    message: \"{count} surfaces on this screen have `status=\\\"urgent\\\"`. The escalation budget is one. When everything is urgent, nothing is.\",\n    docs: \"health/alarm-fatigue\",\n    params: [\"count\"],\n  },\n  \"OPSIN-0006\": {\n    code: \"OPSIN-0006\",\n    severity: \"safety\",\n    title: \"A banned word appeared in a component's copy\",\n    message: \"The string \\\"{text}\\\" contains \\\"{word}\\\", which this system does not use. Write \\\"{replacement}\\\" instead.\",\n    docs: \"content/plain-english-a-z\",\n    params: [\"text\", \"word\", \"replacement\"],\n  },\n  \"OPSIN-0007\": {\n    code: \"OPSIN-0007\",\n    severity: \"safety\",\n    title: \"A health value was animated\",\n    message: \"<{component}> is animating a health value with `{token}`. A value that overshoots has displayed, for one frame, a number that is not true. Use `spring-calm`, or render the final value immediately.\",\n    docs: \"health/motion-in-health-ui\",\n    params: [\"component\", \"token\"],\n  },\n  \"OPSIN-0008\": {\n    code: \"OPSIN-0008\",\n    severity: \"correctness\",\n    title: \"A raw colour value was passed where a token is required\",\n    message: \"<{component}> received `{prop}=\\\"{value}\\\"`. Components take a category or a status, never a colour. A raw value cannot be re-derived for dark mode, for Display-P3, or for a reader who has asked for more contrast.\",\n    docs: \"foundations/token-architecture\",\n    params: [\"component\", \"prop\", \"value\"],\n  },\n  \"OPSIN-0009\": {\n    code: \"OPSIN-0009\",\n    severity: \"correctness\",\n    title: \"A primitive token was referenced from a component\",\n    message: \"`{token}` is a primitive-tier token. Components consume roles. Primitives may be re-tuned in a minor release; roles are covered by the versioning policy.\",\n    docs: \"foundations/token-architecture\",\n    params: [\"token\"],\n  },\n  \"OPSIN-0010\": {\n    code: \"OPSIN-0010\",\n    severity: \"correctness\",\n    title: \"An unknown category was requested\",\n    message: \"`category=\\\"{category}\\\"` is not one of {known}. Adding a category means adding a ramp, not passing a new string.\",\n    docs: \"theming/category-palettes\",\n    params: [\"category\", \"known\"],\n  },\n  \"OPSIN-0011\": {\n    code: \"OPSIN-0011\",\n    severity: \"correctness\",\n    title: \"`unknown` was used as a status level\",\n    message: \"`unknown` is the absence of an assertion, not a fifth level. Use it when there is no reading or no range; do not use it to mean 'probably fine'.\",\n    docs: \"health/uncertainty-and-staleness\",\n    params: [],\n  },\n  \"OPSIN-0012\": {\n    code: \"OPSIN-0012\",\n    severity: \"correctness\",\n    title: \"A trend was drawn from too few points\",\n    message: \"<TrendSparkline> received {count} points and `minimumWindow` is {minimum}. Two readings are not a trend, and drawing one implies a direction the data does not support.\",\n    docs: \"health/trends-and-change\",\n    params: [\"count\", \"minimum\"],\n  },\n  \"OPSIN-0013\": {\n    code: \"OPSIN-0013\",\n    severity: \"correctness\",\n    title: \"A chart's y-axis was truncated\",\n    message: \"<{component}> has `yAxisMin={min}` on a health value. Truncating the axis exaggerates change; a 2% move drawn across the full height of a card reads as a crisis.\",\n    docs: \"foundations/data-visualisation/chart-anatomy\",\n    params: [\"component\", \"min\"],\n  },\n  \"OPSIN-0014\": {\n    code: \"OPSIN-0014\",\n    severity: \"correctness\",\n    title: \"Category colours were used as chart series colours\",\n    message: \"This chart is colouring {count} series from the category ramps. Category colours identify what a reading is about; using them for series turns an identity into an arbitrary label.\",\n    docs: \"foundations/data-visualisation/chart-colour\",\n    params: [\"count\"],\n  },\n  \"OPSIN-0015\": {\n    code: \"OPSIN-0015\",\n    severity: \"correctness\",\n    title: \"A touch target is below the floor\",\n    message: \"<{component}> renders a {width}x{height} hit area. The floor is 44x44, applied to the hit area rather than to the visible box.\",\n    docs: \"accessibility/target-size-and-motor\",\n    params: [\"component\", \"width\", \"height\"],\n  },\n  \"OPSIN-0016\": {\n    code: \"OPSIN-0016\",\n    severity: \"correctness\",\n    title: \"A stale reading was rendered as current\",\n    message: \"<{component}> was given a reading from {age} ago with no staleness treatment. A number with no time attached is read as 'now'.\",\n    docs: \"health/uncertainty-and-staleness\",\n    params: [\"component\", \"age\"],\n  },\n  \"OPSIN-0017\": {\n    code: \"OPSIN-0017\",\n    severity: \"hygiene\",\n    title: \"More than three translucent surfaces are composited\",\n    message: \"{count} translucent material rungs are visible at once; the budget is 3. Beyond three the blur cost is measurable on mid-range devices and the backdrop is unreadable anyway.\",\n    docs: \"foundations/materials/performance-budget\",\n    params: [\"count\"],\n  },\n  \"OPSIN-0018\": {\n    code: \"OPSIN-0018\",\n    severity: \"hygiene\",\n    title: \"A deprecated token was referenced\",\n    message: \"`{token}` was deprecated in {version} and is replaced by `{replacement}`. It will be removed in {removal}.\",\n    docs: \"project/deprecations\",\n    params: [\"token\", \"version\", \"replacement\", \"removal\"],\n  },\n  \"OPSIN-0019\": {\n    code: \"OPSIN-0019\",\n    severity: \"hygiene\",\n    title: \"The token stylesheet was not loaded\",\n    message: \"`--opsin-tokens-generated` is not set on :root. app/tokens.generated.css has not been imported, or `pnpm run generate` has not run, and every component is falling back to authored defaults.\",\n    docs: \"theming/tailwind-v4\",\n    params: [],\n  },\n  \"OPSIN-0020\": {\n    code: \"OPSIN-0020\",\n    severity: \"hygiene\",\n    title: \"Two theme providers are mounted\",\n    message: \"More than one theme provider is writing the `dark` class. Two providers race on first paint and produce a flash of the wrong theme.\",\n    docs: \"handbook/dark-mode\",\n    params: [],\n  },\n  \"OPSIN-0021\": {\n    code: \"OPSIN-0021\",\n    severity: \"safety\",\n    title: \"A status outside the four levels was passed\",\n    message: \"<{component}> received `status=\\\"{status}\\\"`, which is not one of the four levels. The vocabulary is fixed at steady, watch, attention and urgent; a component that accepted a fifth would be inventing a verdict. Nothing was rendered.\",\n    docs: \"health/clinical-status-semantics\",\n    params: [\"component\", \"status\"],\n  },\n}\n\n/* opsinjs:errors:end */\n\n/* ------------------------------------------------------------------ *\n * warnOnce — the development-mode warning channel                     *\n * ------------------------------------------------------------------ */\n\n/**\n * The values a message template asks for, keyed by placeholder name.\n *\n * Values are stringified as they are: a number arrives as a number so the\n * message does not have to decide how to format it, and no value is ever\n * rounded, unit-converted or localised on its way into a warning. A warning\n * that reformats what it was given is a warning that can disagree with the\n * screen it is complaining about.\n */\nexport type OpsinErrorParams = Record<string, string | number>\n\n/**\n * Where a code's page lives. The canonical origin, hardcoded on purpose: this\n * file ships to projects that have no `lib/routes.ts` and no way to resolve a\n * page id, and a warning whose link is a bare slug sends the reader nowhere.\n */\nconst OPSIN_DOCS_ORIGIN = \"https://opsinjs.dev/docs/\"\n\n/**\n * Every message already emitted this session.\n *\n * Declared but not created. In a production bundle the guard at the top of\n * `warnOnce` is statically false, the body is dead code, and this stays\n * `undefined` — so the set is not merely unused in production, it is never\n * allocated and can never retain a string. In development it is created on the\n * first warning and lives for the session, which is what \"once\" means.\n */\nlet warnedKeys: Set<string> | undefined\n\n/**\n * The parameters that identify WHO raised a warning, as opposed to what they\n * happened to be holding when they raised it. Only these take part in the\n * de-duplication key.\n *\n * `count`, `value`, `text`, `width`, `height`, `age`, `minimum`, `min`, `known`,\n * `version`, `removal` and `replacement` are all deliberately absent: each of\n * them either varies per render or is derived from the table itself, and\n * including any one of them turns \"warn once\" into \"warn every frame\".\n */\nconst IDENTITY_PARAMS = [\n  \"component\",\n  \"prop\",\n  \"slot\",\n  \"token\",\n  \"category\",\n  \"status\",\n  \"word\",\n] as const\n\n/**\n * `process`, declared locally rather than borrowed from `@types/node`.\n *\n * This file ships into consumer projects, and a browser-only or Deno project\n * has no Node types. Referencing the global directly made\n * `Cannot find name 'process'` the first thing a consumer saw after installing\n * a component — a typecheck failure caused entirely by opsinjs, in a file they\n * did not write. A module-scoped `declare const` shadows the global where one\n * exists, emits nothing, and asks for exactly the two properties actually read.\n *\n * Every bundler this system supports replaces `process.env.NODE_ENV` at build\n * time, so in a production bundle the guarded body is dead code and is removed.\n */\ndeclare const process: { env?: { NODE_ENV?: string } } | undefined\n\n/**\n * True in development, and false wherever that cannot be established.\n *\n * Exported because a component must never reach for `process` itself: this is\n * the one place in the shipped substrate that knows how the environment is\n * detected, and a component that guessed differently would log in production.\n */\nexport function isDevelopment(): boolean {\n  return typeof process !== \"undefined\" && process?.env?.NODE_ENV !== \"production\"\n}\n\n/** The point at which the warning channel stops rather than grows. */\nconst MAX_WARNED_KEYS = 500\n\n/** Not a real key. It only records that the cap notice has been printed. */\nconst CAP_KEY = \"\\u0000cap\"\n\n/**\n * Report a defect in development, once, and never do anything else.\n *\n * `tokens/errors.json`'s own policy block is the specification, and it is\n * quoted here so the next reader does not have to relitigate it:\n *\n *   \"Warnings are emitted in development only, once per offending call site,\n *   through console.warn. Nothing in this list throws, and nothing in this list\n *   is emitted in production: a health product must not be made to crash by a\n *   documentation-quality complaint.\"\n *\n * So: several component specifications say a violation \"should fail loudly in\n * development\". Loudly, yes. Fail, no. This function warns and returns, in\n * every case, including the cases where it has itself been called wrongly.\n *\n * WHAT \"ONCE PER CALL SITE\" MEANS AT RUNTIME. A call site is not observable\n * from inside a function — the only handle on one is a stack trace, and a stack\n * trace is minified in one build, source-mapped in another and absent on the\n * server, which would make the de-duplication key differ between environments\n * that are meant to behave the same. The key used instead is the code plus the\n * IDENTIFYING parameters listed in `IDENTITY_PARAMS` below.\n *\n * It is deliberately NOT the filled message. A third of the codes in the table\n * carry a parameter that changes on every render — `{count}` in OPSIN-0005,\n * `{value}` in OPSIN-0003, `{age}` in OPSIN-0016 — so keying on the message\n * would make a `safety` warning fire on every frame of a screen that is already\n * misbehaving, and would grow the key set without bound in a long session. The\n * identifying parameters are the ones that name WHO is at fault rather than what\n * they happened to be holding at the time.\n *\n * Two consequences worth stating rather than leaving to be discovered. A caller\n * may pass `component` even for a code whose message never interpolates it, and\n * doing so buys per-component granularity for free — components should. And for\n * the three codes that take no parameters, and for any caller that supplies\n * none, the key collapses to the code alone: one warning per session for the\n * whole application. That is coarser than \"per call site\". It is the most this\n * function can honestly promise without a call site to key on, and it is still\n * the right trade, because a repeated identical complaint teaches nothing and\n * drowns the next one.\n *\n * It survives React's Strict Mode, which invokes a render twice on purpose: the\n * second invocation computes the same key, finds it, and returns without\n * printing.\n *\n * AN UNFILLED PLACEHOLDER IS A DEFECT, AND IT IS NOT THIS FUNCTION'S. A missing\n * parameter leaves its `{brace}` in the message and adds a line saying which\n * ones were not supplied. It does not throw, and it does not swallow the\n * warning: the underlying complaint may be about a reading a person is about to\n * act on, and losing it to a second bug in the component that raised it is the\n * worse of the two outcomes. The visible `{brace}` is the report.\n */\nexport function warnOnce(code: OpsinErrorCode, params: OpsinErrorParams = {}): void {\n  /* Fail closed. Every bundler this system supports replaces\n     `process.env.NODE_ENV` at build time, so in a production bundle the whole\n     body below is dead code and is removed. Where `process` does not exist at\n     all, the answer is silence rather than a guess: an environment this file\n     cannot identify is not one it may decide to log in. */\n  if (!isDevelopment()) return\n\n  const error = OPSIN_ERRORS[code]\n  if (error === undefined) return\n\n  /* The default parameter covers `undefined` and nothing else, and this file\n     ships into JavaScript projects where the types are advice rather than a\n     guarantee. A caller who passes `null` gets a warning with its braces\n     unfilled, which is the report; a TypeError raised inside the warning\n     channel would be the channel breaking the product it is complaining to. */\n  const supplied: OpsinErrorParams = params ?? {}\n\n  /* The same pattern `placeholders()` in scripts/build-tokens.mts extracts\n     with, so what the table says a message needs is what this fills. */\n  const missing: string[] = []\n  const message = error.message.replace(/\\{([A-Za-z][A-Za-z0-9]*)\\}/g, (span, name: string) => {\n    const value: string | number | undefined = supplied[name]\n    if (value === undefined) {\n      missing.push(name)\n      return span\n    }\n    return String(value)\n  })\n\n  const key = [code, ...IDENTITY_PARAMS.map((name) => supplied[name] ?? \"\")].join(\"\\u0000\")\n  if (warnedKeys === undefined) warnedKeys = new Set<string>()\n  if (warnedKeys.has(key)) return\n\n  /* Bounded, because this set is never cleared and a development session can run\n     for days. At the cap the channel says so once and then goes quiet, rather\n     than either leaking or reverting to warning on every render — a warning\n     channel that degrades into noise is one somebody switches off. */\n  if (warnedKeys.size >= MAX_WARNED_KEYS) {\n    if (!warnedKeys.has(CAP_KEY)) {\n      warnedKeys.add(CAP_KEY)\n      try {\n        console.warn(\n          `[opsinjs] ${MAX_WARNED_KEYS} distinct warnings have been reported in this ` +\n            \"session, so this channel is now quiet. Fix what is already reported, or \" +\n            \"reload to start counting again.\",\n        )\n      } catch {\n        /* A patched console is not a reason to take a health product down. */\n      }\n    }\n    return\n  }\n  warnedKeys.add(key)\n\n  const lines = [`[opsinjs] ${code} (${error.severity}): ${message}`]\n  if (error.docs !== \"\") lines.push(`  → ${OPSIN_DOCS_ORIGIN}${error.docs}`)\n  if (missing.length > 0) {\n    lines.push(\n      `  No value was supplied for ${missing.map((name) => `{${name}}`).join(\", \")}. ` +\n        \"That is a defect in the component that raised this warning, not in the \" +\n        \"code the warning is about.\",\n    )\n  }\n\n  try {\n    console.warn(lines.join(\"\\n\"))\n  } catch {\n    /* A patched or absent console is not a reason to take a health product\n       down. Nothing in this channel throws, including the part that reports\n       that the channel is broken. */\n  }\n}\n"

const SHARED_LIB_STATUS_TS = "/**\n * THE SINGLE STATUS VOCABULARY.\n *\n * `source.config.ts` declares the same two enums for frontmatter validation and\n * cannot export them — fumadocs-mdx refuses any export from a source config\n * that is not a collection — so this file is the runtime copy, and\n * `assert-ia.mts` asserts the two agree. If you add a status or a kind, add it\n * in both places in the same commit.\n *\n * Everything that renders a release phase, gates a section, or asks \"what\n * headings does this page need\" reads from here. Nothing re-declares it.\n *\n * This module has no imports, no JSX and no non-erasable TypeScript syntax,\n * because `scripts/*.mts` are executed by plain `node` and import it directly\n * with an explicit `.ts` extension.\n */\n\n/* ────────────────────────────────────────────────────────────────────────────\n   RELEASE PHASE\n   ──────────────────────────────────────────────────────────────────────────── */\n\nexport const STATUSES = [\n  \"stable\",\n  \"beta\",\n  \"alpha\",\n  \"planned\",\n  \"deprecated\",\n  \"considered\",\n] as const\n\n/** The release phase of a page or a catalogue entry. */\nexport type Status = (typeof STATUSES)[number]\n\nexport function isStatus(value: unknown): value is Status {\n  return (\n    typeof value === \"string\" && (STATUSES as readonly string[]).includes(value)\n  )\n}\n\nexport interface StatusMeta {\n  /** The word shown on the badge. */\n  label: string\n  /** One sentence a reader can act on, shown in the status legend and on hover. */\n  summary: string\n  /**\n   * What this phase PROMISES. Published verbatim on\n   * /docs/project/release-phases; the versioning policy is written against it.\n   */\n  promise: string\n  /** Sort order for the status matrix and the section-progress counts. */\n  order: number\n  /**\n   * Whether a page at this status may show a working example. Exactly one\n   * phase may not, and it is the one every page is currently at.\n   */\n  canDemonstrate: boolean\n  /** The clinical status level the docs chrome tints this badge with. */\n  tone: ClinicalStatus | \"unknown\"\n}\n\n/**\n * Ordered most-finished first. `order` is what `<StatusMatrix>` sorts on and\n * what `<SectionProgress>` counts in.\n */\nexport const STATUS_META: Record<Status, StatusMeta> = {\n  stable: {\n    label: \"Stable\",\n    summary: \"Finished. Safe to build on.\",\n    promise:\n      \"The JavaScript API, the rendered DOM, the data-* attributes and the CSS custom properties are all covered by semver. A breaking change requires a major version and a migration guide.\",\n    order: 0,\n    canDemonstrate: true,\n    tone: \"steady\",\n  },\n  beta: {\n    label: \"Beta\",\n    summary: \"Complete and in use, but the surface may still move.\",\n    promise:\n      \"Feature-complete and accessibility-reviewed. The API may change in a minor version with a deprecation notice and at least one release of overlap.\",\n    order: 1,\n    canDemonstrate: true,\n    tone: \"steady\",\n  },\n  alpha: {\n    label: \"Alpha\",\n    summary: \"Usable, incomplete, and expected to change.\",\n    promise:\n      \"It works and it is documented. The API may change in any release without a deprecation cycle. Not for a production health surface.\",\n    order: 2,\n    canDemonstrate: true,\n    tone: \"watch\",\n  },\n  planned: {\n    label: \"Planned\",\n    summary: \"Specified in full. Not implemented. There is no code.\",\n    promise:\n      \"The page you are reading is a specification: what it is for, when not to use it, what it asserts clinically, its proposed anatomy and API, and the accessibility bar the implementation must clear. Nothing has been built. Do not generate code against it.\",\n    order: 3,\n    canDemonstrate: false,\n    tone: \"attention\",\n  },\n  deprecated: {\n    label: \"Deprecated\",\n    summary: \"Still works. Being removed. A replacement is named.\",\n    promise:\n      \"It keeps working until the removal version stated on its page. Every deprecated entry names its replacement and its removal version; see /docs/project/deprecations.\",\n    order: 4,\n    canDemonstrate: true,\n    tone: \"watch\",\n  },\n  considered: {\n    label: \"Considered\",\n    summary:\n      \"Looked at, decided against for now, with the reason written down.\",\n    promise:\n      \"There is no page, no code and no plan. There IS a catalogue row saying why it is not here and what to reach for instead. A considered entry is a decision, not a backlog item.\",\n    order: 5,\n    canDemonstrate: false,\n    tone: \"unknown\",\n  },\n}\n\n/** Statuses in display order. */\nexport const STATUS_ORDER: Status[] = [...STATUSES].sort(\n  (a, b) => STATUS_META[a].order - STATUS_META[b].order\n)\n\n/** True when a page at this status must carry a not-implemented marker. */\nexport function isNotImplemented(status: Status): boolean {\n  return status === \"planned\" || status === \"considered\"\n}\n\n/* ────────────────────────────────────────────────────────────────────────────\n   PAGE KIND\n   ──────────────────────────────────────────────────────────────────────────── */\n\nexport const KINDS = [\n  \"component\",\n  \"foundation\",\n  \"health\",\n  \"accessibility\",\n  \"content\",\n  \"pattern\",\n  \"recipe\",\n  \"screen\",\n  \"handbook\",\n  \"reference\",\n  \"project\",\n  \"guide\",\n] as const\n\n/**\n * A page's kind. This is a contract, not a label: `kind` fully determines the\n * page's headings, and `assert-ia.mts` fails the build on a missing or an\n * unexpected one.\n */\nexport type Kind = (typeof KINDS)[number]\n\nexport function isKind(value: unknown): value is Kind {\n  return (\n    typeof value === \"string\" && (KINDS as readonly string[]).includes(value)\n  )\n}\n\n/* ────────────────────────────────────────────────────────────────────────────\n   THE CLINICAL AXES\n   ──────────────────────────────────────────────────────────────────────────── */\n\nexport const CLINICAL_STATUSES = [\n  \"steady\",\n  \"watch\",\n  \"attention\",\n  \"urgent\",\n] as const\n\n/**\n * What a reading means and what, if anything, to do about it.\n *\n * Four levels, ordered. This is the ONLY status vocabulary in the system: the\n * documentation chrome's callouts, the product's status pills and the dev\n * warnings all use these four words, so a developer reading a Callout in these\n * docs is reading the same vocabulary they will ship.\n *\n * A level is assigned by the consuming product from a reference range or a\n * threshold that the product owns. opsinjs never assigns one, because opsinjs\n * does not know the reader.\n */\nexport type ClinicalStatus = (typeof CLINICAL_STATUSES)[number]\n\n/**\n * The absence of an assertion — no reading, a stale reading, or a reading whose\n * reference range the product does not own.\n *\n * Deliberately NOT a fifth clinical status: rendering \"we do not know\" as a\n * status would claim a verdict the system does not have, and colouring it\n * anywhere near `watch` would let a reader read it as \"probably fine\".\n */\nexport type UnknownStatus = \"unknown\"\n\nexport type ClinicalStatusOrUnknown = ClinicalStatus | UnknownStatus\n\nexport interface ClinicalStatusMeta {\n  /** The word rendered beside the colour and the icon. Never omitted. */\n  word: string\n  /** The canonical example sentence, used by `<StatusLadder>`. */\n  sentence: string\n  /** Who is entitled to assign this level. */\n  assignedBy: string\n  /** The lucide icon name. Colour is never the only carrier of meaning. */\n  icon: string\n  /** 1 is the calmest. Used for ordering and for the escalation budget. */\n  level: number\n}\n\nexport const CLINICAL_STATUS_META: Record<\n  ClinicalStatusOrUnknown,\n  ClinicalStatusMeta\n> = {\n  steady: {\n    word: \"Steady\",\n    sentence: \"This reading is where it is expected to be.\",\n    assignedBy: \"The consuming product, from a reference range it owns.\",\n    icon: \"Check\",\n    level: 1,\n  },\n  watch: {\n    word: \"Watch\",\n    sentence: \"This reading is outside the usual range. Keep an eye on it.\",\n    assignedBy: \"The consuming product, from a reference range it owns.\",\n    icon: \"Eye\",\n    level: 2,\n  },\n  attention: {\n    word: \"Needs attention\",\n    sentence: \"This reading needs to be looked at. Contact your care team.\",\n    assignedBy: \"The consuming product, from a clinically reviewed threshold.\",\n    icon: \"TriangleAlert\",\n    level: 3,\n  },\n  urgent: {\n    word: \"Urgent\",\n    sentence: \"This reading needs help now.\",\n    assignedBy: \"A clinically reviewed threshold with a named clinical owner.\",\n    icon: \"OctagonAlert\",\n    level: 4,\n  },\n  unknown: {\n    word: \"Not known\",\n    sentence: \"We do not have a reading to show.\",\n    assignedBy: \"Nobody. This is the absence of an assertion.\",\n    icon: \"Minus\",\n    level: 0,\n  },\n}\n\nexport const HEALTH_CATEGORIES = [\n  \"sleep\",\n  \"heart\",\n  \"activity\",\n  \"nutrition\",\n  \"mind\",\n  \"labs\",\n] as const\n\n/**\n * What a reading is ABOUT. Identity, never verdict.\n *\n * A heart-red card does not mean something is wrong with a heart reading; it\n * means the reading concerns the heart. This is the axis products most often\n * misuse, because red already means something else everywhere else on the web.\n */\nexport type HealthCategory = (typeof HEALTH_CATEGORIES)[number]\n\nexport const HEALTH_CATEGORY_LABELS: Record<HealthCategory, string> = {\n  sleep: \"Sleep\",\n  heart: \"Heart\",\n  activity: \"Activity\",\n  nutrition: \"Nutrition\",\n  mind: \"Mind\",\n  labs: \"Labs\",\n}\n\nexport function isClinicalStatus(value: unknown): value is ClinicalStatus {\n  return (\n    typeof value === \"string\" &&\n    (CLINICAL_STATUSES as readonly string[]).includes(value)\n  )\n}\n\nexport function isHealthCategory(value: unknown): value is HealthCategory {\n  return (\n    typeof value === \"string\" &&\n    (HEALTH_CATEGORIES as readonly string[]).includes(value)\n  )\n}\n\nexport interface AxisConflict {\n  code: \"OPSIN-0001\"\n  category: HealthCategory\n  status: ClinicalStatus\n  message: string\n  docs: string\n}\n\n/**\n * THE NEVER-MIX RULE, as a function.\n *\n * Returns a conflict when a single surface has been given both a category and a\n * clinical status. `<StatusAxisDemo>` calls this and REFUSES to render the\n * mixed pair; the dev-mode warning OPSIN-0001 is the same check at runtime.\n *\n * Both axes may appear on one SCREEN — a heart-tinted card containing a\n * `watch` pill is correct and common. What may not happen is one surface\n * carrying both, because then the reader cannot tell which of the two the\n * colour is answering.\n *\n * THE MESSAGE BELOW IS A SECOND WORDING OF OPSIN-0001, ON PURPOSE.\n * `tokens/errors.json` owns the canonical one, and it opens with the component\n * name — which this function does not have, because it is given two values and\n * not the thing that holds them. So the sentence differs and the RULE does not.\n * `scripts/build-tokens.mts` asserts that this file claims the same code and\n * sends a reader to the same page; only the phrasing is free to differ, and if\n * you are adding a third wording somewhere, do not.\n */\nexport function axisConflict(input: {\n  category?: HealthCategory | null\n  status?: ClinicalStatus | null\n}): AxisConflict | null {\n  const { category, status } = input\n  if (!category || !status) return null\n  return {\n    code: \"OPSIN-0001\",\n    category,\n    status,\n    message:\n      \"This surface was given both a category (\" +\n      category +\n      \") and a clinical status (\" +\n      status +\n      \"). A surface carries one axis. Set the category on the surface and render the status as a StatusPill inside it.\",\n    docs: \"health/two-colour-axes\",\n  }\n}\n\n/* ────────────────────────────────────────────────────────────────────────────\n   SECTION CONTRACTS\n   ──────────────────────────────────────────────────────────────────────────── */\n\n/**\n * The H2s a page must have, by `kind`. This is the outline\n * `content/_templates/*.mdx` implements, `<PageTemplate>` asserts and\n * `assert-ia.mts` checks; all three read it from here so they cannot drift.\n *\n * `component` is absent on purpose: a component page's outline depends on its\n * status as well as its kind, and lives in COMPONENT_SECTIONS_BY_STATUS below.\n */\nexport const SECTION_OUTLINES: Record<Exclude<Kind, \"component\">, string[]> = {\n  foundation: [\n    \"Overview\",\n    \"How it works\",\n    \"Using it\",\n    \"Tokens\",\n    \"Accessibility impact\",\n    \"Related\",\n  ],\n  health: [\n    \"What this means\",\n    \"The rule\",\n    \"Why (evidence)\",\n    \"Applying it\",\n    \"Components that implement this\",\n    \"What this does not cover\",\n    \"Updates to this page\",\n  ],\n  accessibility: [\n    \"What we guarantee\",\n    \"What you own\",\n    \"How to check\",\n    \"Measured results\",\n    \"Known gaps\",\n    \"Updates to this page\",\n  ],\n  content: [\n    \"The rule\",\n    \"Approved / Rejected\",\n    \"Patterns\",\n    \"Banned words\",\n    \"Related components\",\n  ],\n  pattern: [\n    \"When to use\",\n    \"When not to use\",\n    \"How it works\",\n    \"Content\",\n    \"Accessibility\",\n    \"Research\",\n    \"Updates to this page\",\n  ],\n  recipe: [\n    \"The task\",\n    \"What you need\",\n    \"Build it\",\n    \"The copy\",\n    \"Get it right\",\n    \"Variations\",\n    \"Related\",\n  ],\n  screen: [\n    \"What this screen does\",\n    \"Composition\",\n    \"Preview\",\n    \"Safety notes\",\n    \"Accessibility\",\n    \"Status\",\n  ],\n  handbook: [\n    \"The short version\",\n    \"How it works\",\n    \"Do this\",\n    \"Not this\",\n    \"Gotchas\",\n    \"Related\",\n  ],\n  reference: [\"How this is generated\"],\n  project: [],\n  guide: [\"Overview\", \"Verify it worked\", \"Troubleshooting\", \"Next\"],\n}\n\n/**\n * `kind: project` is free-form and `kind: guide` has task sections between its\n * fixed first and last headings, so for these two the outline is a REQUIRED\n * SUBSET rather than the complete list. Everything else is exact.\n */\nexport const OUTLINE_IS_EXACT: Record<Exclude<Kind, \"component\">, boolean> = {\n  foundation: true,\n  health: true,\n  accessibility: true,\n  content: true,\n  pattern: true,\n  recipe: true,\n  screen: true,\n  handbook: true,\n  reference: false,\n  project: false,\n  guide: false,\n}\n\n/**\n * THE COMPONENT PAGE ANATOMY, status-gated.\n *\n * Sections 1 (header) and 22 (footer) are generated from frontmatter and never\n * appear as an H2, so they are not listed. Everything else is, in page order.\n *\n * At each status the listed sections are the WHOLE page. The others are\n * omitted, not left empty — a heading with nothing under it is worse than an\n * absent heading, and `<PageTemplate kind=\"component\">` fails the build either\n * way. `## Clinical meaning` is included here but is mandatory only for a\n * `health-*` category and forbidden outside one; `assert-ia.mts` checks both\n * directions, which is why it is listed separately below.\n */\nexport const COMPONENT_SECTIONS_BY_STATUS: Record<\n  Exclude<Status, \"considered\">,\n  string[]\n> = {\n  planned: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Proposed API\",\n    \"Content guidelines\",\n    \"Accessibility requirements\",\n    \"Related\",\n  ],\n  alpha: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"Usage\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Examples\",\n    \"Content guidelines\",\n    \"Accessibility\",\n    \"API reference\",\n    \"Related\",\n  ],\n  beta: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"Usage\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Examples\",\n    \"States\",\n    \"Content guidelines\",\n    \"Motion\",\n    \"Accessibility\",\n    \"Data attributes\",\n    \"CSS variables\",\n    \"Tokens\",\n    \"API reference\",\n    \"Cost\",\n    \"Related\",\n  ],\n  stable: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"Usage\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Examples\",\n    \"States\",\n    \"Content guidelines\",\n    \"Motion\",\n    \"Accessibility\",\n    \"Data attributes\",\n    \"CSS variables\",\n    \"Tokens\",\n    \"API reference\",\n    \"Cost\",\n    \"Related\",\n    \"Research and rationale\",\n  ],\n  deprecated: [\n    \"Status\",\n    \"Preview\",\n    \"Installation\",\n    \"Usage\",\n    \"When to use it\",\n    \"Clinical meaning\",\n    \"Anatomy\",\n    \"Content guidelines\",\n    \"Accessibility\",\n    \"API reference\",\n    \"Related\",\n  ],\n}\n\n/**\n * Sections whose presence depends on the component's category rather than on\n * its status. Required when `category` starts with the prefix, and forbidden\n * when it does not.\n */\nexport const CATEGORY_GATED_SECTIONS: {\n  section: string\n  requiredForCategoryPrefix: string\n}[] = [{ section: \"Clinical meaning\", requiredForCategoryPrefix: \"health-\" }]\n\n/**\n * The H2 that carries a component's accessibility contract. It is named\n * \"Accessibility requirements\" at `planned`, because at that status it is a bar\n * the implementation must clear rather than a set of results, and\n * \"Accessibility\" from `alpha` onwards, when there is something to measure.\n * Mandatory at every status; never delegated upstream.\n */\nexport function accessibilitySectionFor(status: Status): string {\n  return status === \"planned\" ? \"Accessibility requirements\" : \"Accessibility\"\n}\n\n/** The sections required for a component page at a given status and category. */\nexport function componentSections(status: Status, category: string): string[] {\n  if (status === \"considered\") return []\n  const base = COMPONENT_SECTIONS_BY_STATUS[status]\n  return base.filter((section) => {\n    const gate = CATEGORY_GATED_SECTIONS.find((g) => g.section === section)\n    if (!gate) return true\n    return category.startsWith(gate.requiredForCategoryPrefix)\n  })\n}\n"

/**
 * The substrate appended to every component's `files`, named once and shared by
 * reference so that twenty-four components cost one copy of each file rather
 * than twenty-four. Nothing mutates these; the machine layer copies each entry
 * into a fresh object on the way out.
 *
 * These texts differ from the files on disk in exactly one way: a relative
 * import's `.ts` extension is dropped, because the repository needs it (plain
 * node resolves no extensions) and a consumer cannot compile with it (TS5097,
 * unless they enable `allowImportingTsExtensions`). See `forDistribution` in
 * scripts/build-registry.mts. A component's own text is never rewritten.
 */
const SHARED_FILES: RegistrySourceFile[] = [
  { path: "lib/opsinjs.ts", type: "registry:lib", target: "@lib/opsinjs.ts", content: SHARED_LIB_OPSINJS_TS },
  { path: "lib/status.ts", type: "registry:lib", target: "@lib/status.ts", content: SHARED_LIB_STATUS_TS },
]

